#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
enum MailLayout {
    #[default]
    Vertical,
    Horizontal,
}

impl MailLayout {
    fn from_setting(value: &str) -> Self {
        match value {
            "horizontal" | "classic" => Self::Horizontal,
            _ => Self::Vertical,
        }
    }

    fn setting_value(self) -> &'static str {
        match self {
            Self::Vertical => "vertical",
            Self::Horizontal => "horizontal",
        }
    }

    fn orientation(self) -> gtk::Orientation {
        match self {
            Self::Vertical => gtk::Orientation::Horizontal,
            Self::Horizontal => gtk::Orientation::Vertical,
        }
    }

    fn default_position(self) -> i32 {
        match self {
            Self::Vertical => 420,
            Self::Horizontal => 360,
        }
    }
}

pub(crate) fn account_sources_match(source_a: &str, source_b: &str) -> bool {
    let a = source_a.trim();
    let b = source_b.trim();
    if a.eq_ignore_ascii_case(b) {
        return true;
    }
    let canon_a = MailPage::canonical_account_uid(a);
    let canon_b = MailPage::canonical_account_uid(b);
    if canon_a.eq_ignore_ascii_case(canon_b) {
        return true;
    }
    fn strip_acc(s: &str) -> &str {
        s.strip_prefix("account:").unwrap_or(s)
    }
    let stripped_a = strip_acc(canon_a);
    let stripped_b = strip_acc(canon_b);
    if stripped_a.eq_ignore_ascii_case(stripped_b) {
        return true;
    }
    // Fast path: if neither identifier contains '@' (e.g. two distinct 40-char hex EDS UIDs),
    // they cannot match via an AccountProfile email alias.
    if !stripped_a.contains('@') && !stripped_b.contains('@') {
        return false;
    }
    let profiles = crate::services::account_config_service::AccountConfigStore::default().load_cached();
    for profile in profiles.iter() {
        let matches_a = profile.id.eq_ignore_ascii_case(a)
            || profile.id.eq_ignore_ascii_case(canon_a)
            || strip_acc(&profile.id).eq_ignore_ascii_case(stripped_a)
            || profile.email.eq_ignore_ascii_case(a)
            || profile.email.eq_ignore_ascii_case(canon_a);
        let matches_b = profile.id.eq_ignore_ascii_case(b)
            || profile.id.eq_ignore_ascii_case(canon_b)
            || strip_acc(&profile.id).eq_ignore_ascii_case(stripped_b)
            || profile.email.eq_ignore_ascii_case(b)
            || profile.email.eq_ignore_ascii_case(canon_b);
        if matches_a && matches_b {
            return true;
        }
    }
    false
}

pub(crate) fn folder_names_match(a: &str, b: &str) -> bool {
    fn strip_gmail(s: &str) -> &str {
        let trimmed = s.trim();
        if trimmed.len() > 8 && trimmed[..8].eq_ignore_ascii_case("[gmail]/") {
            trimmed[8..].trim()
        } else {
            trimmed
        }
    }
    let a = a.trim();
    let b = b.trim();
    if a.eq_ignore_ascii_case(b) {
        return true;
    }
    let sa = strip_gmail(a);
    let sb = strip_gmail(b);
    if sa.eq_ignore_ascii_case(sb) {
        return true;
    }
    let is_inbox = |s: &str| s.eq_ignore_ascii_case("inbox") || s.eq_ignore_ascii_case("posteingang");
    if is_inbox(sa) && is_inbox(sb) {
        return true;
    }
    let is_sent = |s: &str| {
        s.eq_ignore_ascii_case("sent")
            || s.eq_ignore_ascii_case("sent items")
            || s.eq_ignore_ascii_case("sent mail")
            || s.eq_ignore_ascii_case("gesendete elemente")
            || s.eq_ignore_ascii_case("gesendete")
            || s.eq_ignore_ascii_case("gesendet")
    };
    if is_sent(sa) && is_sent(sb) {
        return true;
    }
    let is_trash = |s: &str| {
        s.eq_ignore_ascii_case("trash")
            || s.eq_ignore_ascii_case("deleted items")
            || s.eq_ignore_ascii_case("gelöschte elemente")
            || s.eq_ignore_ascii_case("gelöscht")
            || s.eq_ignore_ascii_case("papierkorb")
            || s.eq_ignore_ascii_case("bin")
    };
    if is_trash(sa) && is_trash(sb) {
        return true;
    }
    let is_drafts = |s: &str| {
        s.eq_ignore_ascii_case("drafts")
            || s.eq_ignore_ascii_case("draft")
            || s.eq_ignore_ascii_case("entwürfe")
    };
    if is_drafts(sa) && is_drafts(sb) {
        return true;
    }
    let is_junk = |s: &str| {
        s.eq_ignore_ascii_case("junk")
            || s.eq_ignore_ascii_case("junk-e-mail")
            || s.eq_ignore_ascii_case("junk email")
            || s.eq_ignore_ascii_case("spam")
    };
    if is_junk(sa) && is_junk(sb) {
        return true;
    }
    let is_archive = |s: &str| {
        s.eq_ignore_ascii_case("archive")
            || s.eq_ignore_ascii_case("archiv")
            || s.eq_ignore_ascii_case("all mail")
            || s.eq_ignore_ascii_case("alle nachrichten")
    };
    if is_archive(sa) && is_archive(sb) {
        return true;
    }
    false
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct FolderSelection {
    folder_id: String,
    source_uid: Option<String>,
    folder_name: Option<String>,
}

impl FolderSelection {
    fn all() -> Self {
        Self {
            folder_id: "all".to_string(),
            source_uid: None,
            folder_name: None,
        }
    }

    fn from_folder_id(folder_id: &str) -> Self {
        let trimmed = folder_id.trim();
        if let Some((src, fname)) = trimmed.split_once("::") {
            let src = src.trim();
            let fname = fname.trim();
            if !src.is_empty() && !fname.is_empty() {
                return Self {
                    folder_id: fname.to_string(),
                    source_uid: Some(src.to_string()),
                    folder_name: Some(fname.to_string()),
                };
            }
        }
        let folder_id = match trimmed {
            "all" | "inbox" | "sent" | "drafts" | "trash" | "archive" | "spam" | "outbox"
            | "unified_inbox" | "unified_unread" | "unified_flagged" | "unified_sent" => {
                trimmed
            }
            _ => "inbox",
        };
        Self {
            folder_id: folder_id.to_string(),
            source_uid: None,
            folder_name: None,
        }
    }

    fn configured_initial() -> Self {
        let unified_enabled = AppSettings::try_new()
            .map(|settings| settings.mail_enable_unified_inbox())
            .unwrap_or(true);
        let folder_id = AppSettings::try_new()
            .map(|settings| settings.mail_default_folder())
            .unwrap_or_else(|| "inbox".to_string());
        if unified_enabled && !folder_id.contains("::") {
            match folder_id.as_str() {
                "inbox" | "all" => return Self::from_folder_id("unified_inbox"),
                "sent" => return Self::from_folder_id("unified_sent"),
                _ => {}
            }
        }
        Self::from_folder_id(&folder_id)
    }

    fn is_remote(&self) -> bool {
        self.source_uid.is_some()
    }

    pub(crate) fn is_unified(&self) -> bool {
        self.folder_id.starts_with("unified_")
    }

    pub(crate) fn selection_key(&self) -> String {
        if let Some(source_uid) = &self.source_uid {
            format!("{}:{}", source_uid, self.folder_name.as_deref().unwrap_or(""))
        } else {
            self.folder_id.clone()
        }
    }

    fn matches(&self, message: &MailMessageObject) -> bool {
        if let Some(source_uid) = self.source_uid.as_deref() {
            return message
                .backend_location()
                .map(|location| {
                    account_sources_match(&location.source_uid, source_uid)
                        && self
                            .folder_name
                            .as_deref()
                            .is_none_or(|folder_name| folder_names_match(&location.folder_name, folder_name))
                })
                .unwrap_or(false);
        }

        match self.folder_id.as_str() {
            "all" => true,
            "unified_inbox" => message.folder_id().eq_ignore_ascii_case("inbox"),
            "unified_unread" => {
                message.is_unread()
                    && !message.folder_id().eq_ignore_ascii_case("trash")
                    && !message.folder_id().eq_ignore_ascii_case("junk")
                    && !message.folder_id().eq_ignore_ascii_case("spam")
            }
            "unified_flagged" => message.is_flagged(),
            "unified_sent" => message.folder_id().eq_ignore_ascii_case("sent"),
            "spam" => message.folder_id().eq_ignore_ascii_case("junk"),
            folder_id => {
                message.folder_id().eq_ignore_ascii_case(folder_id)
                    || (folder_id.starts_with("custom:")
                        && message
                            .folder_id()
                            .strip_prefix(folder_id)
                            .is_some_and(|rest| rest.starts_with('/')))
            }
        }
    }

    fn title_and_icon(&self) -> (String, &'static str) {
        if let Some(ref name) = self.folder_name {
            (name.clone(), MailPage::folder_icon_name(name))
        } else {
            match self.folder_id.as_str() {
                "all" => (gettext("All Messages"), "mail-inbox-symbolic"),
                "unified_inbox" => (gettext("All Inboxes"), "mail-inbox-symbolic"),
                "unified_unread" => (gettext("All Unread"), "mail-unread-symbolic"),
                "unified_flagged" => (gettext("All Flagged"), "starred-symbolic"),
                "unified_sent" => (gettext("All Sent"), "mail-send-symbolic"),
                "inbox" => (gettext("Inbox"), "mail-inbox-symbolic"),
                "sent" => (gettext("Sent"), "mail-send-symbolic"),
                "drafts" => (gettext("Drafts"), "mail-drafts-symbolic"),
                "trash" => (gettext("Trash"), "user-trash-symbolic"),
                "archive" => (gettext("Archive"), "folder-symbolic"),
                "spam" => (gettext("Junk"), "mail-mark-junk-symbolic"),
                "outbox" => (gettext("Outbox"), "mail-outbox-symbolic"),
                _ => (gettext("Inbox"), "mail-inbox-symbolic"),
            }
        }
    }
}

/// A folder popup must use its clicked tree row without changing the reader's
/// active folder.  Account roots have no folder name and are intentionally not
/// folder-action targets.
fn popup_folder_target(selection: FolderSelection, selectable: bool) -> Option<FolderSelection> {
    let is_remote_account_root = selection.is_remote()
        && selection
            .folder_name
            .as_deref()
            .is_none_or(|name| name.trim().is_empty());
    (selectable && !selection.folder_id.trim().is_empty() && !is_remote_account_root)
        .then_some(selection)
}

fn folder_context_action_selection(
    active: FolderSelection,
    popup_target: Option<FolderSelection>,
) -> FolderSelection {
    popup_target.unwrap_or(active)
}

fn folder_mutation_capability_allows(
    capabilities: &CamelFolderMutationCapabilities,
    kind: CamelFolderMutationKind,
) -> bool {
    match kind {
        CamelFolderMutationKind::CreateChild => capabilities.can_create_child,
        CamelFolderMutationKind::Rename => capabilities.can_rename,
        CamelFolderMutationKind::Delete => capabilities.can_delete,
        CamelFolderMutationKind::Refresh => capabilities.can_refresh,
        CamelFolderMutationKind::Copy => capabilities.can_copy,
        CamelFolderMutationKind::Move => capabilities.can_move,
    }
}

fn folder_mutation_progress_message(kind: CamelFolderMutationKind) -> String {
    match kind {
        CamelFolderMutationKind::CreateChild => gettext("Creating folder…"),
        CamelFolderMutationKind::Rename => gettext("Renaming folder…"),
        CamelFolderMutationKind::Delete => gettext("Deleting folder…"),
        CamelFolderMutationKind::Refresh => gettext("Refreshing folder…"),
        CamelFolderMutationKind::Copy | CamelFolderMutationKind::Move => {
            gettext("Checking folder transfer…")
        }
    }
}

fn folder_mutation_unsupported_message(kind: CamelFolderMutationKind) -> String {
    match kind {
        CamelFolderMutationKind::CreateChild => gettext("The provider does not allow subfolders here."),
        CamelFolderMutationKind::Rename => gettext("The provider does not allow renaming this folder."),
        CamelFolderMutationKind::Delete => {
            gettext("The provider does not allow safe deletion of this folder.")
        }
        CamelFolderMutationKind::Refresh => {
            gettext("The provider does not allow refreshing this folder.")
        }
        CamelFolderMutationKind::Copy | CamelFolderMutationKind::Move => {
            gettext("The Camel provider does not offer atomic folder transfer.")
        }
    }
}

fn folder_mutation_success_message(kind: CamelFolderMutationKind, display_name: &str) -> String {
    match kind {
        CamelFolderMutationKind::CreateChild => {
            gettext("Subfolder created in “{display_name}”").replace("{display_name}", display_name)
        }
        CamelFolderMutationKind::Rename => {
            gettext("Folder “{display_name}” renamed").replace("{display_name}", display_name)
        }
        CamelFolderMutationKind::Delete => {
            gettext("Folder “{display_name}” deleted").replace("{display_name}", display_name)
        }
        CamelFolderMutationKind::Refresh => {
            gettext("Folder “{display_name}” refreshed").replace("{display_name}", display_name)
        }
        CamelFolderMutationKind::Copy | CamelFolderMutationKind::Move => {
            gettext("Folder “{display_name}” transferred").replace("{display_name}", display_name)
        }
    }
}

fn folder_path_with_replaced_leaf(folder_name: &str, new_leaf: &str) -> String {
    folder_name
        .rsplit_once('/')
        .map(|(parent, _)| format!("{parent}/{new_leaf}"))
        .unwrap_or_else(|| new_leaf.to_string())
}

fn popup_mark_all_read_target_is_loaded(
    active: &FolderSelection,
    popup_target: Option<&FolderSelection>,
    local_store_loaded: bool,
) -> bool {
    popup_target
        .is_none_or(|target| target == active || (!target.is_remote() && local_store_loaded))
}

impl Default for FolderSelection {
    fn default() -> Self {
        Self::all()
    }
}

fn folder_path_is_within(folder_name: &str, parent_name: &str) -> bool {
    folder_names_match(folder_name, parent_name)
        || folder_name
            .strip_prefix(parent_name)
            .is_some_and(|suffix| suffix.starts_with('/'))
        || folder_name.to_lowercase()
            .strip_prefix(&parent_name.to_lowercase())
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn folder_selection_matches_with_subfolders(
    selection: &FolderSelection,
    message: &MailMessageObject,
) -> bool {
    if selection.matches(message) {
        return true;
    }

    if let Some(source_uid) = selection.source_uid.as_deref() {
        let Some(location) = message.backend_location() else {
            return false;
        };
        if !account_sources_match(&location.source_uid, source_uid) {
            return false;
        }
        let Some(parent_name) = selection.folder_name.as_deref() else {
            return true;
        };
        return folder_names_match(&location.folder_name, parent_name)
            || folder_path_is_within(&location.folder_name, parent_name);
    }

    let parent_folder_id = match selection.folder_id.as_str() {
        "all" => return true,
        "spam" => "junk",
        folder_id => folder_id,
    };
    folder_path_is_within(message.folder_id().as_str(), parent_folder_id)
}

fn renamed_folder_path(folder_name: &str, old_name: &str, new_name: &str) -> Option<String> {
    if folder_name == old_name {
        return Some(new_name.to_string());
    }
    folder_name
        .strip_prefix(old_name)
        .filter(|suffix| suffix.starts_with('/'))
        .map(|suffix| format!("{new_name}{suffix}"))
}

#[derive(Copy, Clone, Debug, Default, Eq, PartialEq)]
pub enum QuickSearchField {
    #[default]
    SubjectOrAddresses,
    /// Compatibility name for the former all-fields mode.  It remains
    /// intentionally hidden from the selector and shares FreeForm semantics.
    AllFields,
    FreeForm,
    Subject,
    Sender,
    Recipient,
    Message,
    Body,
}

impl QuickSearchField {
    fn from_selector_index(index: u32) -> Self {
        match index {
            0 => Self::SubjectOrAddresses,
            1 => Self::Subject,
            2 => Self::Sender,
            3 => Self::Recipient,
            4 => Self::Message,
            5 => Self::Body,
            6 => Self::FreeForm,
            _ => Self::FreeForm,
        }
    }

    fn selector_index(self) -> u32 {
        match self {
            Self::SubjectOrAddresses => 0,
            Self::Subject => 1,
            Self::Sender => 2,
            Self::Recipient => 3,
            Self::Message => 4,
            Self::Body => 5,
            Self::FreeForm | Self::AllFields => 6,
        }
    }

    fn canonical_scope(self) -> MailSearchFieldScope {
        match self {
            Self::FreeForm | Self::AllFields => MailSearchFieldScope::Any,
            Self::SubjectOrAddresses => MailSearchFieldScope::SubjectOrAddresses,
            Self::Subject => MailSearchFieldScope::Subject,
            Self::Sender => MailSearchFieldScope::Sender,
            Self::Recipient => MailSearchFieldScope::Recipients,
            Self::Message => MailSearchFieldScope::Message,
            Self::Body => MailSearchFieldScope::Body,
        }
    }

    fn to_saved(self) -> SavedSearchFieldMode {
        match self {
            Self::SubjectOrAddresses => SavedSearchFieldMode::SubjectOrAddresses,
            Self::AllFields | Self::FreeForm => SavedSearchFieldMode::FreeForm,
            Self::Subject => SavedSearchFieldMode::Subject,
            Self::Sender => SavedSearchFieldMode::Sender,
            Self::Recipient => SavedSearchFieldMode::Recipients,
            Self::Message => SavedSearchFieldMode::Message,
            Self::Body => SavedSearchFieldMode::Body,
        }
    }

    fn from_saved(field: SavedSearchFieldMode) -> Self {
        match field {
            SavedSearchFieldMode::SubjectOrAddresses => Self::SubjectOrAddresses,
            SavedSearchFieldMode::Subject => Self::Subject,
            SavedSearchFieldMode::Sender => Self::Sender,
            SavedSearchFieldMode::Recipients => Self::Recipient,
            SavedSearchFieldMode::Message => Self::Message,
            SavedSearchFieldMode::Body => Self::Body,
            SavedSearchFieldMode::FreeForm => Self::FreeForm,
        }
    }
}

impl From<QuickSearchField> for SavedSearchFieldMode {
    fn from(field: QuickSearchField) -> Self {
        field.to_saved()
    }
}

impl From<SavedSearchFieldMode> for QuickSearchField {
    fn from(field: SavedSearchFieldMode) -> Self {
        Self::from_saved(field)
    }
}

#[derive(Copy, Clone, Debug, Default, Eq, PartialEq)]
pub enum QuickSearchScope {
    #[default]
    CurrentFolder,
    CurrentFolderAndSubfolders,
    CurrentAccount,
    AllAccounts,
}

impl QuickSearchScope {
    fn from_selector_index(index: u32) -> Self {
        match index {
            1 => Self::CurrentFolderAndSubfolders,
            2 => Self::CurrentAccount,
            3 => Self::AllAccounts,
            _ => Self::CurrentFolder,
        }
    }

    fn selector_index(self) -> u32 {
        match self {
            Self::CurrentFolder => 0,
            Self::CurrentFolderAndSubfolders => 1,
            Self::CurrentAccount => 2,
            Self::AllAccounts => 3,
        }
    }

    fn to_saved(self) -> SavedSearchScope {
        match self {
            Self::CurrentFolder => SavedSearchScope::CurrentFolder,
            Self::CurrentFolderAndSubfolders => SavedSearchScope::CurrentFolderAndSubfolders,
            Self::CurrentAccount => SavedSearchScope::CurrentAccount,
            Self::AllAccounts => SavedSearchScope::AllAccounts,
        }
    }

    fn from_saved(scope: SavedSearchScope) -> Self {
        match scope {
            SavedSearchScope::CurrentFolder => Self::CurrentFolder,
            SavedSearchScope::CurrentFolderAndSubfolders => Self::CurrentFolderAndSubfolders,
            SavedSearchScope::CurrentAccount => Self::CurrentAccount,
            SavedSearchScope::AllAccounts => Self::AllAccounts,
        }
    }
}

impl From<QuickSearchScope> for SavedSearchScope {
    fn from(scope: QuickSearchScope) -> Self {
        scope.to_saved()
    }
}

impl From<SavedSearchScope> for QuickSearchScope {
    fn from(scope: SavedSearchScope) -> Self {
        Self::from_saved(scope)
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
enum MessageSearchCanonicalState {
    #[default]
    Empty,
    Parsed(ParsedMailSearchQuery),
    Invalid(SearchQueryParseError),
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct MessageSearchQuery {
    canonical: MessageSearchCanonicalState,
}

impl MessageSearchQuery {
    #[cfg(test)]
    fn parse(input: &str) -> Self {
        Self::parse_with_field_scope(input, QuickSearchField::FreeForm)
    }

    fn parse_with_field_scope(input: &str, field_scope: QuickSearchField) -> Self {
        Self::parse_with_field_scope_and_mode(input, field_scope, SearchSyntaxMode::Plain)
    }

    fn parse_with_field_scope_and_mode(
        input: &str,
        field_scope: QuickSearchField,
        syntax_mode: SearchSyntaxMode,
    ) -> Self {
        Self {
            canonical: match parse_mail_query_with_mode(
                input,
                field_scope.canonical_scope(),
                syntax_mode,
            ) {
                Ok(Some(parsed)) => MessageSearchCanonicalState::Parsed(parsed),
                Ok(None) => MessageSearchCanonicalState::Empty,
                Err(error) => MessageSearchCanonicalState::Invalid(error),
            },
        }
    }

    fn is_invalid(&self) -> bool {
        matches!(&self.canonical, MessageSearchCanonicalState::Invalid(_))
    }

    fn is_empty(&self) -> bool {
        matches!(&self.canonical, MessageSearchCanonicalState::Empty)
    }

    fn canonical_query(&self) -> Option<&ParsedMailSearchQuery> {
        match &self.canonical {
            MessageSearchCanonicalState::Parsed(query) => Some(query),
            MessageSearchCanonicalState::Empty | MessageSearchCanonicalState::Invalid(_) => None,
        }
    }
}

/// The one representation used by saved-search selection and counters.  The
/// persisted query is checked against its versioned AST before it can reach a
/// filter or a provider adapter, so field/scope/target changes cannot leave a
/// stale textual query behind.
#[derive(Clone, Debug)]
struct CompiledSavedSearch {
    query: MessageSearchQuery,
    scope: QuickSearchScope,
}

#[derive(Clone, Debug)]
struct ResolvedSavedSearch {
    compiled: CompiledSavedSearch,
    target: FolderSelection,
}

const SAVED_SEARCH_TARGET_WARNING: &str =
    "Saved search: The exact destination is unavailable; showing 0 matches.";

fn compile_saved_search(search: &SavedSearch) -> Result<CompiledSavedSearch, String> {
    let field = QuickSearchField::from_saved(search.field);
    let query_from_text = MessageSearchQuery::parse_with_field_scope(&search.query, field);
    let Some(parsed_from_text) = query_from_text.canonical_query() else {
        return Err(gettext("Search query is empty or invalid"));
    };
    let parsed_from_ast = decode_mail_query_fixture(&search.ast)
        .map_err(|error| gettext("AST search fixture is invalid: {error}").replace("{error}", &error.to_string()))?;
    // Relative date predicates are resolved when parsed.  Compare the
    // canonical wire form instead of the resolved Rust AST so a save/load
    // crossing local midnight does not make an otherwise identical search
    // stale.  The wire form still covers the raw predicate/operator/field.
    let text_fixture = encode_mail_query_fixture(parsed_from_text)
        .map_err(|error| gettext("Search query could not be canonically encoded: {error}").replace("{error}", &error.to_string()))?;
    let ast_fixture = encode_mail_query_fixture(&parsed_from_ast).map_err(|error| {
        gettext("AST search fixture could not be canonically encoded: {error}").replace("{error}", &error.to_string())
    })?;
    if text_fixture != ast_fixture {
        return Err(gettext("AST search fixture and search query do not match"));
    }
    Ok(CompiledSavedSearch {
        query: MessageSearchQuery {
            canonical: MessageSearchCanonicalState::Parsed(parsed_from_ast),
        },
        scope: QuickSearchScope::from_saved(search.scope),
    })
}

fn saved_search_remote_folder_key(source_uid: &str, folder_name: &str) -> String {
    format!("{source_uid}\u{0}{folder_name}")
}

fn is_known_local_saved_folder(folder_id: &str, local_folder_ids: &HashSet<String>) -> bool {
    matches!(
        folder_id,
        "inbox"
            | "sent"
            | "drafts"
            | "trash"
            | "archive"
            | "spam"
            | "junk"
            | "unified_inbox"
            | "unified_unread"
            | "unified_flagged"
            | "unified_sent"
    ) || local_folder_ids.contains(folder_id)
}

/// Resolve only exact persisted identities.  In particular, an unavailable
/// folder or account is an error rather than an invitation to use the active
/// folder, Inbox, or all accounts.
fn resolve_saved_search_target(
    search: &SavedSearch,
    local_folder_ids: &HashSet<String>,
    remote_folder_ids: &HashSet<String>,
    remote_folders: &[CamelFolderSummary],
) -> Result<FolderSelection, String> {
    let source_uid = search.source_uid.as_deref();
    let folder_name = search.folder_name.as_deref();
    match search.scope {
        SavedSearchScope::AllAccounts => {
            if search.folder_id.is_some() || source_uid.is_some() || folder_name.is_some() {
                return Err(
                    gettext("Cross-account search contains an unexpected destination identity"),
                );
            }
            Ok(FolderSelection::all())
        }
        SavedSearchScope::CurrentAccount => {
            if search.folder_id.is_some() || folder_name.is_some() {
                return Err(gettext("Account search contains an unexpected folder identity"));
            }
            let Some(source_uid) = source_uid.filter(|value| !value.trim().is_empty()) else {
                return Err(gettext("Source ID of saved account is unavailable"));
            };
            let source_available = remote_folders
                .iter()
                .any(|folder| folder.source_uid == source_uid)
                || remote_folder_ids.iter().any(|folder_id| {
                    folder_id
                        .split_once('\u{0}')
                        .is_some_and(|(source, _)| source == source_uid)
                });
            if !source_available {
                return Err(gettext("Mail account “{source_uid}” is unavailable").replace("{source_uid}", source_uid));
            }
            Ok(FolderSelection {
                folder_id: format!("account:{source_uid}"),
                source_uid: Some(source_uid.to_string()),
                folder_name: None,
            })
        }
        SavedSearchScope::CurrentFolder | SavedSearchScope::CurrentFolderAndSubfolders => {
            let Some(folder_id) = search.folder_id.as_deref() else {
                return Err(gettext("Saved folder search contains no folder ID"));
            };
            match (source_uid, folder_name) {
                (None, None) => {
                    if !is_known_local_saved_folder(folder_id, local_folder_ids) {
                        return Err(gettext("Local folder “{folder_id}” is unavailable").replace("{folder_id}", folder_id));
                    }
                    Ok(FolderSelection {
                        folder_id: folder_id.to_string(),
                        source_uid: None,
                        folder_name: None,
                    })
                }
                (Some(source_uid), Some(folder_name))
                    if !source_uid.trim().is_empty() && !folder_name.trim().is_empty() =>
                {
                    let expected_id = saved_search_remote_folder_key(source_uid, folder_name);
                    if folder_id != expected_id {
                        return Err(gettext("Remote folder ID does not match exact destination"));
                    }
                    let exact_summary = remote_folders.iter().any(|folder| {
                        folder.is_selectable
                            && folder.source_uid == source_uid
                            && folder.folder_name == folder_name
                            && folder.folder_id == folder_id
                    });
                    if !remote_folder_ids.contains(folder_id) || !exact_summary {
                        return Err(gettext("Remote folder “{source_uid}/{folder_name}” is unavailable")
                            .replace("{source_uid}", source_uid)
                            .replace("{folder_name}", folder_name));
                    }
                    Ok(FolderSelection {
                        folder_id: folder_id.to_string(),
                        source_uid: Some(source_uid.to_string()),
                        folder_name: Some(folder_name.to_string()),
                    })
                }
                _ => Err(
                    gettext("Saved folder search contains no complete target identity"),
                ),
            }
        }
    }
}

fn resolve_compiled_saved_search(
    search: &SavedSearch,
    local_folder_ids: &HashSet<String>,
    remote_folder_ids: &HashSet<String>,
    remote_folders: &[CamelFolderSummary],
) -> Result<ResolvedSavedSearch, String> {
    let compiled = compile_saved_search(search)?;
    let target =
        resolve_saved_search_target(search, local_folder_ids, remote_folder_ids, remote_folders)?;
    Ok(ResolvedSavedSearch { compiled, target })
}

fn mail_graph_search_query(query: &MessageSearchQuery) -> Option<String> {
    let MessageSearchCanonicalState::Parsed(parsed) = &query.canonical else {
        return None;
    };
    match parsed.graph_search_plan() {
        MailGraphSearchPlan::SafePositiveConjunction(expression) => Some(expression),
        MailGraphSearchPlan::Unsupported(_) => None,
    }
}

const GRAPH_LOCAL_SEARCH_WARNING: &str =
    "This search is only evaluated on loaded messages; additional matches may be missing.";

fn graph_local_search_warning(
    query: &MessageSearchQuery,
    graph_backend_active: bool,
) -> Option<&'static str> {
    if !graph_backend_active {
        return None;
    }
    let MessageSearchCanonicalState::Parsed(parsed) = &query.canonical else {
        return None;
    };
    matches!(
        parsed.graph_search_plan(),
        MailGraphSearchPlan::Unsupported(_)
    )
    .then_some(GRAPH_LOCAL_SEARCH_WARNING)
}

fn graph_scope_local_search_warning(
    search_scope: QuickSearchScope,
    graph_backend_active: bool,
) -> Option<&'static str> {
    if !graph_backend_active {
        return None;
    }
    match search_scope {
        QuickSearchScope::CurrentFolderAndSubfolders => Some(GRAPH_SUBFOLDER_SEARCH_WARNING),
        QuickSearchScope::AllAccounts => Some(GRAPH_ALL_ACCOUNTS_SEARCH_WARNING),
        QuickSearchScope::CurrentFolder | QuickSearchScope::CurrentAccount => None,
    }
}

fn graph_local_search_warning_for_scope(
    query: &MessageSearchQuery,
    graph_backend_active: bool,
    search_scope: QuickSearchScope,
) -> Option<&'static str> {
    graph_scope_local_search_warning(search_scope, graph_backend_active)
        .or_else(|| graph_local_search_warning(query, graph_backend_active))
}

fn message_date(message: &MailMessageObject) -> Option<NaiveDate> {
    let value = message.date_str();
    parse_message_date(&value)
}

fn parse_message_date(value: &str) -> Option<NaiveDate> {
    parse_flexible_datetime(value).map(|dt| dt.with_timezone(&chrono::Local).date_naive())
}

fn parse_message_timestamp(value: &str) -> i64 {
    if let Some(ts) = crate::services::evolution_summary_cache::parse_rfc2822_utc_fast(value) {
        return ts;
    }
    parse_flexible_datetime(value)
        .map(|dt| dt.timestamp())
        .unwrap_or(0)
}

// format_month_short handles localized month abbreviations via gettext

fn format_month_short(month: u32) -> String {
    match month {
        1 => gettext("Jan"),
        2 => gettext("Feb"),
        3 => gettext("Mar"),
        4 => gettext("Apr"),
        5 => gettext("May"),
        6 => gettext("Jun"),
        7 => gettext("Jul"),
        8 => gettext("Aug"),
        9 => gettext("Sep"),
        10 => gettext("Oct"),
        11 => gettext("Nov"),
        12 => gettext("Dec"),
        _ => String::new(),
    }
}

fn strip_date_comments(raw: &str) -> String {
    let mut without_comments = String::with_capacity(raw.len());
    let mut depth_paren = 0;
    let mut depth_bracket = 0;
    for ch in raw.chars() {
        match ch {
            '(' => depth_paren += 1,
            ')' => {
                if depth_paren > 0 {
                    depth_paren -= 1;
                }
            }
            '[' => depth_bracket += 1,
            ']' => {
                if depth_bracket > 0 {
                    depth_bracket -= 1;
                }
            }
            _ => {
                if depth_paren == 0 && depth_bracket == 0 {
                    without_comments.push(ch);
                }
            }
        }
    }
    without_comments
}

fn normalize_weekday_token(s: &str) -> Option<&'static str> {
    let clean = s.trim_matches(|c: char| !c.is_alphabetic()).to_lowercase();
    match clean.as_str() {
        "mo" | "mon" | "montag" | "monday" => Some("Mon,"),
        "di" | "die" | "tue" | "tues" | "dienstag" | "tuesday" => Some("Tue,"),
        "mi" | "mit" | "wed" | "mittwoch" | "wednesday" => Some("Wed,"),
        "do" | "don" | "thu" | "thur" | "thurs" | "donnerstag" | "thursday" => Some("Thu,"),
        "fr" | "fri" | "freitag" | "friday" => Some("Fri,"),
        "sa" | "sam" | "sat" | "samstag" | "sonnabend" | "saturday" => Some("Sat,"),
        "so" | "son" | "sun" | "sonntag" | "sunday" => Some("Sun,"),
        _ => None,
    }
}

fn normalize_month_token(s: &str) -> Option<&'static str> {
    let clean = s.trim_matches(|c: char| !c.is_alphabetic()).to_lowercase();
    match clean.as_str() {
        "jan" | "januar" | "january" => Some("Jan"),
        "feb" | "februar" | "february" => Some("Feb"),
        "mar" | "mär" | "märz" | "mrz" | "maerz" | "mae" | "march" => Some("Mar"),
        "apr" | "april" => Some("Apr"),
        "mai" | "may" => Some("May"),
        "jun" | "juni" | "june" => Some("Jun"),
        "jul" | "juli" | "july" => Some("Jul"),
        "aug" | "august" => Some("Aug"),
        "sep" | "sept" | "september" => Some("Sep"),
        "okt" | "oct" | "oktober" | "october" => Some("Oct"),
        "nov" | "november" => Some("Nov"),
        "dez" | "dec" | "dezember" | "december" => Some("Dec"),
        _ => None,
    }
}

fn normalize_timezone_token(s: &str) -> Option<String> {
    let clean = s.trim_matches(|c: char| c == '(' || c == ')' || c == '[' || c == ']' || c == ',');
    if (clean.starts_with('+') || clean.starts_with('-')) && clean.contains(':') {
        let stripped: String = clean.chars().filter(|&c| c != ':').collect();
        if stripped.len() == 5 && stripped[1..].chars().all(|c| c.is_ascii_digit()) {
            return Some(stripped);
        }
    }
    if (clean.starts_with('+') || clean.starts_with('-'))
        && clean.len() == 5
        && clean[1..].chars().all(|c| c.is_ascii_digit())
    {
        return Some(clean.to_string());
    }
    let tz_upper = clean.to_ascii_uppercase();
    match tz_upper.as_str() {
        "UTC" | "GMT" | "Z" | "WET" => Some("+0000".to_string()),
        "CET" | "MEZ" | "WEST" | "BST" => Some("+0100".to_string()),
        "CEST" | "MESZ" | "EET" => Some("+0200".to_string()),
        "EEST" | "MSK" => Some("+0300".to_string()),
        "EST" | "CDT" => Some("-0500".to_string()),
        "EDT" => Some("-0400".to_string()),
        "CST" | "MDT" => Some("-0600".to_string()),
        "MST" | "PDT" => Some("-0700".to_string()),
        "PST" => Some("-0800".to_string()),
        "AKST" => Some("-0900".to_string()),
        "AKDT" => Some("-0800".to_string()),
        "HST" => Some("-1000".to_string()),
        "AEST" => Some("+1000".to_string()),
        "AEDT" => Some("+1100".to_string()),
        "JST" => Some("+0900".to_string()),
        _ => None,
    }
}

fn naive_to_fixed_offset(ndt: chrono::NaiveDateTime) -> Option<chrono::DateTime<chrono::FixedOffset>> {
    use chrono::TimeZone;
    if let Some(local) = chrono::Local.from_local_datetime(&ndt).single() {
        Some(local.fixed_offset())
    } else if let Some(local) = chrono::Local.from_local_datetime(&ndt).earliest() {
        Some(local.fixed_offset())
    } else {
        let offset = *chrono::Local::now().offset();
        Some(chrono::DateTime::from_naive_utc_and_offset(ndt - offset, offset))
    }
}

fn normalize_date_tokens(cleaned: &str) -> String {
    let tokens: Vec<&str> = cleaned.split_whitespace().collect();
    if tokens.is_empty() {
        return String::new();
    }
    let mut normalized_tokens = Vec::with_capacity(tokens.len());
    let mut has_weekday = false;

    for (i, token) in tokens.iter().enumerate() {
        // Weekday as first token
        if i == 0 {
            if let Some(wd) = normalize_weekday_token(token) {
                normalized_tokens.push(wd.to_string());
                has_weekday = true;
                continue;
            }
        }

        // Day of month or year (e.g. "21." -> "21", "2026." -> "2026")
        let trimmed_num = token.trim_end_matches(['.', ',']);
        if let Ok(num) = trimmed_num.parse::<u32>() {
            if (1..=31).contains(&num) && ((has_weekday && i == 1) || (!has_weekday && i == 0)) {
                normalized_tokens.push(num.to_string());
                continue;
            }
            if (1900..=2200).contains(&num) {
                normalized_tokens.push(num.to_string());
                continue;
            }
        }

        // Month (e.g. "Sep." -> "Sep", "Okt." -> "Oct")
        if let Some(m) = normalize_month_token(token) {
            normalized_tokens.push(m.to_string());
            continue;
        }

        // Time with missing seconds (e.g. "14:30" -> "14:30:00")
        if token.contains(':') && token.matches(':').count() == 1 {
            let parts: Vec<&str> = token.split(':').collect();
            if parts.len() == 2 && parts[0].chars().all(|c| c.is_ascii_digit()) && parts[1].chars().all(|c| c.is_ascii_digit()) {
                normalized_tokens.push(format!("{}:00", token));
                continue;
            }
        }

        // Timezone (e.g. "+02:00" -> "+0200", "CEST" -> "+0200")
        if let Some(tz) = normalize_timezone_token(token) {
            normalized_tokens.push(tz);
            continue;
        }

        // Keep raw token (e.g. year "2026", time "10:24:16")
        normalized_tokens.push((*token).to_string());
    }

    normalized_tokens.join(" ")
}

pub(crate) fn parse_flexible_datetime(value: &str) -> Option<chrono::DateTime<chrono::FixedOffset>> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }

    let cleaned_cow: std::borrow::Cow<'_, str> = if trimmed.contains('(') || trimmed.contains('[') {
        std::borrow::Cow::Owned(strip_date_comments(trimmed))
    } else {
        std::borrow::Cow::Borrowed(trimmed)
    };
    let cleaned = cleaned_cow.trim();
    if cleaned.is_empty() {
        return None;
    }

    // 1. Direct standard parse attempts
    if let Ok(dt) = chrono::DateTime::parse_from_rfc2822(cleaned) {
        return Some(dt);
    }
    if let Some(idx) = cleaned.find(',') {
        let without_weekday = cleaned[idx + 1..].trim();
        if let Ok(dt) = chrono::DateTime::parse_from_rfc2822(without_weekday) {
            return Some(dt);
        }
    }
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(cleaned) {
        return Some(dt);
    }

    // 2. ISO 8601 with space instead of 'T' (e.g. "2026-09-21 10:24:16+02:00")
    if cleaned.contains(' ') && (cleaned.contains('+') || cleaned.contains('-') || cleaned.ends_with('Z')) {
        let with_t = cleaned.replacen(' ', "T", 1);
        if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(&with_t) {
            return Some(dt);
        }
    }

    // 3. Token-normalized RFC 2822 parse attempt (handles German locales, dots, colons in TZ, named TZ)
    let normalized = normalize_date_tokens(cleaned);
    if !normalized.is_empty() && normalized != cleaned {
        if let Ok(dt) = chrono::DateTime::parse_from_rfc2822(&normalized) {
            return Some(dt);
        }
        if let Some(idx) = normalized.find(',') {
            let without_weekday = normalized[idx + 1..].trim();
            if let Ok(dt) = chrono::DateTime::parse_from_rfc2822(without_weekday) {
                return Some(dt);
            }
        }
        if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(&normalized) {
            return Some(dt);
        }
    }

    // 4. Naive formats on cleaned and normalized strings
    let mut candidate_strings = vec![normalized.clone(), cleaned.to_string()];
    if let Some(idx) = normalized.find(',') {
        candidate_strings.push(normalized[idx + 1..].trim().to_string());
    }
    if let Some(idx) = cleaned.find(',') {
        candidate_strings.push(cleaned[idx + 1..].trim().to_string());
    }

    for candidate in &candidate_strings {
        if candidate.is_empty() {
            continue;
        }
        for fmt in [
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d %H:%M",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%dT%H:%M",
            "%d.%m.%Y %H:%M:%S",
            "%d.%m.%Y %H:%M",
            "%a, %d %b %Y %H:%M:%S",
            "%d %b %Y %H:%M:%S",
            "%a, %d %b %Y %H:%M",
            "%d %b %Y %H:%M",
            "%b %d, %Y %H:%M:%S",
            "%B %d, %Y %H:%M:%S",
            "%b %d %Y %H:%M:%S",
        ] {
            if let Ok(ndt) = chrono::NaiveDateTime::parse_from_str(candidate, fmt) {
                if let Some(dt) = naive_to_fixed_offset(ndt) {
                    return Some(dt);
                }
            }
        }
        for fmt in [
            "%Y-%m-%d",
            "%d.%m.%Y",
            "%d %b %Y",
            "%a, %d %b %Y",
            "%b %d, %Y",
            "%B %d, %Y",
        ] {
            if let Ok(nd) = chrono::NaiveDate::parse_from_str(candidate, fmt) {
                if let Some(ndt) = nd.and_hms_opt(12, 0, 0) {
                    if let Some(dt) = naive_to_fixed_offset(ndt) {
                        return Some(dt);
                    }
                }
            }
        }
    }

    None
}

pub(crate) fn format_mail_table_date(
    value: &str,
    date_format_style: &str,
    custom_format: &str,
    time_format: &str,
) -> String {
    format_mail_table_date_with_now(
        value,
        date_format_style,
        custom_format,
        time_format,
        chrono::Local::now().date_naive(),
    )
}

fn format_weekday_short(date: chrono::NaiveDate) -> String {
    match date.weekday() {
        chrono::Weekday::Mon => gettext("Mon"),
        chrono::Weekday::Tue => gettext("Tue"),
        chrono::Weekday::Wed => gettext("Wed"),
        chrono::Weekday::Thu => gettext("Thu"),
        chrono::Weekday::Fri => gettext("Fri"),
        chrono::Weekday::Sat => gettext("Sat"),
        chrono::Weekday::Sun => gettext("Sun"),
    }
}

pub(crate) fn format_mail_table_date_with_now(
    value: &str,
    date_format_style: &str,
    custom_format: &str,
    time_format: &str,
    now_date: chrono::NaiveDate,
) -> String {
    let Some(parsed) = parse_flexible_datetime(value) else {
        return value.to_string();
    };

    let local_dt = parsed.with_timezone(&chrono::Local);
    let msg_date = local_dt.date_naive();
    let days_diff = (now_date - msg_date).num_days();
    let time_pattern = if time_format == "12h" { "%I:%M %p" } else { "%H:%M" };

    match date_format_style {
        "short" => msg_date.format("%d.%m.%y").to_string(),
        "full" => msg_date.format("%d.%m.%Y").to_string(),
        "datetime" => format!("{} {}", msg_date.format("%d.%m.%Y"), local_dt.format(time_pattern)),
        "iso" => msg_date.format("%Y-%m-%d").to_string(),
        "custom" => {
            let pattern = custom_format.trim();
            if !pattern.is_empty() {
                let formatted = local_dt.format(pattern).to_string();
                if !formatted.is_empty() {
                    return formatted;
                }
            }
            if msg_date == now_date {
                local_dt.format(time_pattern).to_string()
            } else if days_diff >= 1 && days_diff < 7 {
                format_weekday_short(msg_date)
            } else if now_date.year() == msg_date.year() {
                let month_name = format_month_short(msg_date.month());
                format!("{}. {}", msg_date.day(), month_name)
            } else {
                msg_date.format("%d.%m.%y").to_string()
            }
        }
        _ => {
            // Gmail-style relative date formatting:
            // 1. Same day: time only (e.g. "14:30")
            // 2. Last 6-7 days: short weekday name (e.g. "Mon" / "Mo")
            // 3. Older within current year: "10. Sep"
            // 4. Older year: "10.09.25"
            if msg_date == now_date {
                local_dt.format(time_pattern).to_string()
            } else if days_diff >= 1 && days_diff < 7 {
                format_weekday_short(msg_date)
            } else if now_date.year() == msg_date.year() {
                let month_name = format_month_short(msg_date.month());
                format!("{}. {}", msg_date.day(), month_name)
            } else {
                msg_date.format("%d.%m.%y").to_string()
            }
        }
    }
}

fn format_smart_date<Tz: chrono::TimeZone>(
    parsed: &chrono::DateTime<Tz>,
    time_pattern: &str,
    date_format: &str,
) -> String {
    let now_date = chrono::Local::now().date_naive();
    let local_dt = parsed.with_timezone(&chrono::Local);
    let msg_date = local_dt.date_naive();
    let days_diff = (now_date - msg_date).num_days();

    if msg_date == now_date {
        local_dt.format(time_pattern).to_string()
    } else if days_diff >= 1 && days_diff < 7 {
        format_weekday_short(msg_date)
    } else if now_date.year() == msg_date.year() {
        let month_name = format_month_short(msg_date.month());
        format!("{}. {}", msg_date.day(), month_name)
    } else {
        match date_format {
            "iso" => msg_date.format("%Y-%m-%d").to_string(),
            "us" => msg_date.format("%m/%d/%Y").to_string(),
            _ => msg_date.format("%d.%m.%Y").to_string(),
        }
    }
}

fn format_message_date(value: &str) -> String {
    let Some(parsed) = parse_flexible_datetime(value) else {
        return value.to_string();
    };
    let settings = AppSettings::try_new();
    let show_real_date = settings
        .as_ref()
        .map(|s| s.mail_show_real_date())
        .unwrap_or(true);
    let date_format = settings
        .as_ref()
        .map(|settings| settings.resolved_date_format())
        .unwrap_or_else(|| "german".to_string());
    let time_format = settings
        .as_ref()
        .map(|settings| settings.time_format())
        .unwrap_or_else(|| "24h".to_string());

    let time_pattern = match time_format.as_str() {
        "12h" => "%I:%M %p",
        _ => "%H:%M",
    };

    if !show_real_date {
        return format_smart_date(&parsed, time_pattern, &date_format);
    }

    let pattern = match (date_format.as_str(), time_format.as_str()) {
        ("iso", "12h") => "%Y-%m-%d %I:%M %p",
        ("iso", _) => "%Y-%m-%d %H:%M",
        ("us", "12h") => "%m/%d/%Y %I:%M %p",
        ("us", _) => "%m/%d/%Y %H:%M",
        ("german", "12h") => "%d.%m.%Y %I:%M %p",
        _ => "%d.%m.%Y %H:%M",
    };
    parsed.format(pattern).to_string()
}

fn format_preview_header_date(value: &str) -> String {
    format_preview_header_date_with_now(value, chrono::Local::now().date_naive())
}

fn format_preview_header_date_with_now(value: &str, now_date: chrono::NaiveDate) -> String {
    let Some(parsed) = parse_flexible_datetime(value) else {
        return value.to_string();
    };
    let settings = AppSettings::try_new();
    let time_format = settings
        .as_ref()
        .map(|s| s.time_format())
        .unwrap_or_else(|| "24h".to_string());
    let time_pattern = if time_format == "12h" { "%I:%M %p" } else { "%H:%M" };

    let local_dt = parsed.with_timezone(&chrono::Local);
    let msg_date = local_dt.date_naive();
    let days_diff = (now_date - msg_date).num_days();

    if msg_date == now_date {
        local_dt.format(time_pattern).to_string()
    } else if days_diff == 1 {
        format!("{}, {}", gettext("Yesterday"), local_dt.format(time_pattern))
    } else if days_diff > 1 && days_diff < 7 {
        format!("{}, {}", format_weekday_short(msg_date), local_dt.format(time_pattern))
    } else if now_date.year() == msg_date.year() {
        let month_name = format_month_short(msg_date.month());
        format!("{}. {}", msg_date.day(), month_name)
    } else {
        msg_date.format("%d.%m.%Y").to_string()
    }
}

fn parse_email_recipients(raw: &str) -> Vec<(String, String)> {
    if raw.trim().is_empty() {
        return Vec::new();
    }
    let mut recipients = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut in_angle = false;

    for c in raw.chars() {
        match c {
            '"' => {
                in_quotes = !in_quotes;
                current.push(c);
            }
            '<' => {
                in_angle = true;
                current.push(c);
            }
            '>' => {
                in_angle = false;
                current.push(c);
            }
            ',' if !in_quotes && !in_angle => {
                let trimmed = current.trim();
                if !trimmed.is_empty() {
                    recipients.push(parse_single_address(trimmed));
                }
                current.clear();
            }
            _ => {
                current.push(c);
            }
        }
    }
    let trimmed = current.trim();
    if !trimmed.is_empty() {
        recipients.push(parse_single_address(trimmed));
    }
    recipients
}

fn parse_single_address(item: &str) -> (String, String) {
    if let Some(start) = item.rfind('<') {
        if let Some(end_offset) = item[start..].find('>') {
            let end = start + end_offset;
            let email = item[start + 1..end].trim().to_lowercase();
            let name = item[..start].trim().trim_matches('"').trim().to_string();
            return (if name.is_empty() { email.clone() } else { name }, email);
        }
    }
    let email = item.trim().trim_matches('"').trim().to_lowercase();
    (email.clone(), email)
}

pub(crate) fn clean_display_name_from_email(email: &str) -> String {
    let local = email.split('@').next().unwrap_or(email).trim();
    if local.is_empty() {
        return email.to_string();
    }
    let words: Vec<String> = local
        .split(|c: char| c == '.' || c == '_' || c == '-' || c == '+')
        .filter(|w| !w.trim().is_empty())
        .map(|w| {
            let lower = w.to_lowercase();
            match lower.as_str() {
                "edv" => "EDV".to_string(),
                "it" => "IT".to_string(),
                "hr" => "HR".to_string(),
                "ceo" => "CEO".to_string(),
                "cto" => "CTO".to_string(),
                "cfo" => "CFO".to_string(),
                "gmbh" => "GmbH".to_string(),
                "ag" => "AG".to_string(),
                "llc" => "LLC".to_string(),
                "co" => "Co".to_string(),
                "kg" => "KG".to_string(),
                "dev" => "Dev".to_string(),
                "ops" => "Ops".to_string(),
                "api" => "API".to_string(),
                _ => {
                    let mut chars = w.chars();
                    match chars.next() {
                        Some(first) => {
                            let mut s = first.to_uppercase().to_string();
                            s.extend(chars.map(|c| c.to_ascii_lowercase()));
                            s
                        }
                        None => String::new(),
                    }
                }
            }
        })
        .filter(|w| !w.is_empty())
        .collect();

    if words.is_empty() {
        local.to_string()
    } else {
        words.join(" ")
    }
}

pub(crate) fn resolve_recipient_klarname(name: &str, email: &str) -> String {
    let clean_name = name.trim().trim_matches('"').trim();
    let clean_email = email.trim().trim_matches('"').trim();

    // 1. If explicit display name exists in RFC822 header and is not just the email:
    if !clean_name.is_empty()
        && !clean_name.contains('@')
        && !clean_name.eq_ignore_ascii_case(clean_email)
    {
        return clean_name.to_string();
    }

    // 2. Lookup in local contacts cache (EDS address books / SQLite cache):
    if !clean_email.is_empty() {
        if let Some(contact_name) =
            crate::services::evolution_contact_cache::lookup_contact_name_by_email(clean_email)
        {
            let contact_trimmed = contact_name.trim();
            if !contact_trimmed.is_empty() && !contact_trimmed.contains('@') {
                return contact_trimmed.to_string();
            }
        }
    }

    // 3. Check system user real name:
    let sys_real_name = glib::real_name();
    let sys_real_str = sys_real_name.to_string_lossy();
    if !sys_real_str.is_empty() && sys_real_str != "Unknown" {
        let sys_user_name = glib::user_name();
        let sys_user_str = sys_user_name.to_string_lossy().to_lowercase();
        let sys_user_local = sys_user_str.split('@').next().unwrap_or("").trim();
        let email_lower = clean_email.to_lowercase();
        let email_local = email_lower.split('@').next().unwrap_or("").trim();

        if (!sys_user_local.is_empty() && email_local == sys_user_local)
            || (!sys_user_str.is_empty() && email_lower == sys_user_str)
        {
            return sys_real_str.to_string();
        }
    }

    // 4. Clean humanized format from email address local-part (e.g. intern_edv -> "Intern EDV"):
    clean_display_name_from_email(clean_email)
}

pub(crate) fn format_recipient_display(raw: &str, show_address: bool) -> String {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    let recipients = parse_email_recipients(trimmed);
    if recipients.is_empty() {
        if show_address {
            return trimmed.to_string();
        } else {
            return clean_display_name_from_email(trimmed);
        }
    }
    recipients
        .into_iter()
        .map(|(name, email)| {
            if show_address {
                if email.contains('@') {
                    email
                } else if name.contains('@') {
                    name
                } else if !email.trim().is_empty() {
                    email
                } else {
                    name
                }
            } else {
                resolve_recipient_klarname(&name, &email)
            }
        })
        .filter(|s| !s.is_empty())
        .collect::<Vec<_>>()
        .join(", ")
}

fn extract_emails_from_text(text: &str) -> Vec<String> {
    let mut emails = Vec::new();
    for token in text.split(|c: char| {
        c.is_whitespace()
            || c == ','
            || c == ';'
            || c == '('
            || c == ')'
            || c == '<'
            || c == '>'
            || c == '"'
            || c == '\''
            || c == '['
            || c == ']'
    }) {
        let trimmed = token.trim();
        if trimmed.contains('@') && !trimmed.starts_with('@') && !trimmed.ends_with('@') {
            let email = trimmed.to_lowercase();
            if !emails.contains(&email) {
                emails.push(email);
            }
        }
    }
    emails
}

fn format_modern_recipient_summary(
    recipient_to: &str,
    recipient_cc: &str,
    user_emails: &[String],
    expanded: bool,
) -> String {
    let to_list = parse_email_recipients(recipient_to);
    let cc_list = parse_email_recipients(recipient_cc);
    let total_count = to_list.len() + cc_list.len();

    let arrow = if expanded { "▴" } else { "▾" };
    let to_prefix = gettext("to");
    let me_label = gettext("me");

    if total_count == 0 {
        return format!("{to_prefix} {me_label} {arrow}");
    }

    let is_user_email = |email: &str| -> bool {
        let lower = email.to_lowercase();
        if lower == "me@example.com" {
            return true;
        }
        user_emails.iter().any(|u| u.trim().to_lowercase() == lower)
    };

    let user_match = to_list
        .iter()
        .chain(cc_list.iter())
        .find(|(_, email)| is_user_email(email));

    let target_display = if let Some((_, email)) = user_match {
        if !email.trim().is_empty() {
            email.clone()
        } else {
            me_label
        }
    } else {
        let first = to_list.first().or_else(|| cc_list.first());
        if let Some((name, email)) = first {
            if !name.trim().is_empty() {
                name.clone()
            } else if !email.trim().is_empty() {
                email.clone()
            } else {
                me_label
            }
        } else {
            me_label
        }
    };

    let summary = if total_count <= 1 {
        format!("{to_prefix} {target_display}")
    } else {
        format!("{to_prefix} {target_display}, +{}", total_count - 1)
    };

    format!("{summary} {arrow}")
}

fn format_mail_list_date(value: &str) -> String {
    let settings = AppSettings::try_new();
    let date_format = settings
        .as_ref()
        .map(|s| s.mail_date_format())
        .unwrap_or_else(|| "standard".to_string());
    let custom_format = settings
        .as_ref()
        .map(|s| s.mail_date_custom_format())
        .unwrap_or_default();
    let time_format = settings
        .as_ref()
        .map(|s| s.time_format())
        .unwrap_or_else(|| "24h".to_string());
    format_mail_table_date(value, &date_format, &custom_format, &time_format)
}

fn mail_row_density_metrics(value: &str) -> (i32, i32) {
    match value {
        "compact" => (0, 1),
        "spacious" => (7, 14),
        _ => (3, 6),
    }
}

fn mail_row_status_icon(
    is_unread: bool,
    is_replied: bool,
    is_forwarded: bool,
) -> (&'static str, String) {
    if is_replied && is_forwarded {
        ("mail-replied-symbolic", gettext("Replied and forwarded"))
    } else if is_replied {
        ("mail-replied-symbolic", gettext("Replied"))
    } else if is_forwarded {
        ("mail-forward-symbolic", gettext("Forwarded"))
    } else if is_unread {
        ("mail-unread-symbolic", gettext("Unread"))
    } else {
        ("", gettext("Read"))
    }
}

fn mail_row_attachment_info(
    attachments: &[crate::models::mail_message::AttachmentInfo],
) -> Option<(&'static str, String)> {
    let regular: Vec<_> = attachments.iter().filter(|att| att.is_user_attachment()).collect();
    if regular.is_empty() {
        return None;
    }
    for att in &regular {
        let mime = att.mime_type.to_ascii_lowercase();
        let filename = att.filename.to_ascii_lowercase();
        if mime.contains("calendar") || filename.ends_with(".ics") {
            return Some(("x-office-calendar-symbolic", gettext("Calendar invitation (.ics)")));
        }
        if mime.contains("vcard") || filename.ends_with(".vcf") {
            return Some(("x-office-address-book-symbolic", gettext("Contact card (.vcf)")));
        }
    }
    Some(("mail-attachment-symbolic", gettext("Attachment")))
}

pub(crate) fn themed_icon_name<W: IsA<gtk::Widget>>(
    widget: &W,
    preferred: &str,
    fallback: &str,
) -> String {
    let theme = gtk::IconTheme::for_display(&widget.display());
    if theme.has_icon(preferred) {
        preferred.to_string()
    } else if preferred == "mail-forwarded-symbolic" && theme.has_icon("mail-forward-symbolic") {
        "mail-forward-symbolic".to_string()
    } else if (preferred == "mail-flag-symbolic" || preferred == "flag-symbolic")
        && theme.has_icon("emoji-flags-symbolic")
    {
        "emoji-flags-symbolic".to_string()
    } else if theme.has_icon(fallback) {
        fallback.to_string()
    } else if (preferred == "mail-thread-symbolic" || fallback == "chat-bubble-symbolic")
        && theme.has_icon("user-available-symbolic")
    {
        "user-available-symbolic".to_string()
    } else if (preferred == "mail-thread-symbolic" || fallback == "chat-bubble-symbolic")
        && theme.has_icon("mail-reply-all-symbolic")
    {
        "mail-reply-all-symbolic".to_string()
    } else if theme.has_icon("emblem-important-symbolic") {
        "emblem-important-symbolic".to_string()
    } else if theme.has_icon("bookmark-symbolic") {
        "bookmark-symbolic".to_string()
    } else if theme.has_icon("starred-symbolic") {
        "starred-symbolic".to_string()
    } else if theme.has_icon("tag-symbolic") {
        "tag-symbolic".to_string()
    } else {
        preferred.to_string()
    }
}

pub(crate) fn set_image_icon_with_fallback(image: &gtk::Image, preferred: &str, fallback: &str) {
    image.set_icon_name(Some(&themed_icon_name(image, preferred, fallback)));
}

pub(crate) fn set_button_icon_with_fallback(button: &gtk::Button, preferred: &str, fallback: &str) {
    button.set_icon_name(&themed_icon_name(button, preferred, fallback));
}

fn format_labels_for_display_with_defs(
    labels: &[String],
    configured: &[crate::services::settings_service::MailLabelDefinition],
) -> String {
    if labels.is_empty() {
        return String::new();
    }
    let display_names: Vec<String> = labels
        .iter()
        .map(|lbl| {
            let trimmed = lbl.trim();
            if let Some(def) = configured.iter().find(|d| {
                d.tag.eq_ignore_ascii_case(trimmed)
                    || d.name.eq_ignore_ascii_case(trimmed)
                    || d.display_name().eq_ignore_ascii_case(trimmed)
            }) {
                def.display_name()
            } else if let Some(stripped) = trimmed
                .strip_prefix("$Label")
                .or_else(|| trimmed.strip_prefix("$label"))
            {
                stripped.replace('_', " ").trim().to_string()
            } else {
                trimmed.replace('_', " ")
            }
        })
        .filter(|s| !s.is_empty())
        .collect();

    display_names.join(", ")
}

fn format_labels_for_display(labels: &[String]) -> String {
    if labels.is_empty() {
        return String::new();
    }
    let configured = AppSettings::try_new()
        .map(|s| s.mail_labels())
        .unwrap_or_else(crate::services::settings_service::MailLabelDefinition::default_labels);
    format_labels_for_display_with_defs(labels, &configured)
}

fn mail_row_expander_visible(thread_size: usize, depth: u32) -> bool {
    depth == 0 && thread_size > 1
}

fn mail_list_uses_wide_messages(profile: &str, order: &[String]) -> bool {
    if profile == "wide" {
        return true;
    }
    if profile != "custom" {
        return false;
    }
    let position = |column: &str| {
        order
            .iter()
            .position(|candidate| candidate == column)
            .unwrap_or(usize::MAX)
    };
    position("messages") < position("sender").min(position("subject"))
}

fn mail_list_profile_allows_column(profile: &str, wide_messages: bool, column: &str) -> bool {
    if column == "important" || (column == "preview" && profile != "cards") {
        return false;
    }
    match profile {
        "messages" => matches!(
            column,
            "avatar" | "status" | "attachment" | "flagged" | "follow-up" | "memo" | "sender" | "subject" | "date"
        ),
        "wide" => matches!(column, "status" | "flagged" | "follow-up" | "memo" | "messages"),
        "cards" => matches!(column, "avatar" | "status" | "flagged" | "follow-up" | "memo" | "labels" | "preview"),
        _ => match column {
            "messages" => wide_messages,
            "sender" | "subject" => !wide_messages,
            "important" | "preview" | "follow-up-due" | "location" => false,
            _ => true,
        },
    }
}

fn visible_thread_size(threading: bool, stored_size: usize) -> usize {
    if threading { stored_size.max(1) } else { 1 }
}

fn compact_folder_indent(depth: usize) -> i32 {
    6 + (depth as i32).saturating_mul(12)
}

const MAIL_INDICATOR_COLUMN_WIDTH: i32 = 28;
const MAIL_AVATAR_COLUMN_WIDTH: i32 = 28;
const MAIL_PREVIEW_COLUMN_WIDTH: i32 = 160;
const MAIL_DATE_COLUMN_WIDTH: i32 = 96;
const MAIL_SIZE_COLUMN_WIDTH: i32 = 66;
const MAIL_DUE_COLUMN_WIDTH: i32 = 132;
const MAIL_LOCATION_COLUMN_WIDTH: i32 = 180;

fn format_message_size(bytes: usize) -> String {
    const KIB: f64 = 1024.0;
    const MIB: f64 = KIB * 1024.0;
    const GIB: f64 = MIB * 1024.0;
    let bytes_f = bytes as f64;
    if bytes_f >= GIB {
        format!("{:.1} GiB", bytes_f / GIB)
    } else if bytes_f >= MIB {
        format!("{:.1} MiB", bytes_f / MIB)
    } else if bytes_f >= KIB {
        format!("{:.1} KiB", bytes_f / KIB)
    } else {
        format!("{bytes} B")
    }
}

