fn folder_default_sort_bucket(folder_id: &str, label: &str) -> u32 {
    let clean_id = folder_id.trim().to_lowercase();
    let clean_label = label.trim().to_lowercase();

    let matches_pattern =
        |pattern: &str| -> bool { clean_id.contains(pattern) || clean_label.contains(pattern) };

    // 0: Inbox
    if matches_pattern("inbox") || matches_pattern("posteingang") {
        return 0;
    }

    // 2: Drafts
    if matches_pattern("draft")
        || matches_pattern("entwurf")
        || matches_pattern("entwürf")
        || matches_pattern("entwuerf")
    {
        return 2;
    }

    // 3: Trash / Deleted Items
    if matches_pattern("trash")
        || matches_pattern("mülleimer")
        || matches_pattern("muelleimer")
        || matches_pattern("papierkorb")
        || matches_pattern("gelöscht")
        || matches_pattern("geloescht")
        || matches_pattern("deleted")
    {
        return 3;
    }

    // 4: Sent Items / Sent
    if matches_pattern("sent") || matches_pattern("gesendet") {
        return 4;
    }

    // 5: Junk / Spam
    if matches_pattern("junk")
        || matches_pattern("spam")
        || matches_pattern("unerwünscht")
        || matches_pattern("unerwuenscht")
    {
        return 5;
    }

    // 6: Outbox
    if matches_pattern("outbox") || matches_pattern("postausgang") {
        return 6;
    }

    // 7: RSS Feeds / RSS
    if matches_pattern("rss") {
        return 7;
    }

    // 8: Sync Issues / Sync Problems
    if matches_pattern("sync") || matches_pattern("synchronisier") {
        return 8;
    }

    // 1: Personal Folders (default for custom / personal folders, e.g. Archive, Projects, etc.)
    1
}

fn compare_folder_siblings(
    left_id: &str,
    left_label: &str,
    right_id: &str,
    right_label: &str,
    order: &BTreeMap<String, u32>,
) -> std::cmp::Ordering {
    match (order.get(left_id), order.get(right_id)) {
        (Some(left), Some(right)) => left
            .cmp(right)
            .then_with(|| {
                let left_bucket = folder_default_sort_bucket(left_id, left_label);
                let right_bucket = folder_default_sort_bucket(right_id, right_label);
                left_bucket.cmp(&right_bucket)
            })
            .then_with(|| left_label.to_lowercase().cmp(&right_label.to_lowercase()))
            .then_with(|| left_id.cmp(right_id)),
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => {
            let left_bucket = folder_default_sort_bucket(left_id, left_label);
            let right_bucket = folder_default_sort_bucket(right_id, right_label);
            left_bucket
                .cmp(&right_bucket)
                .then_with(|| left_label.to_lowercase().cmp(&right_label.to_lowercase()))
                .then_with(|| left_id.cmp(right_id))
        }
    }
}

fn local_folder_parent_id(folder_id: &str) -> Option<String> {
    let path = folder_id.strip_prefix("custom:")?;
    path.rsplit_once('/')
        .map(|(parent, _)| format!("custom:{parent}"))
}

const LOCAL_SORTABLE_BUILTIN_FOLDER_IDS: &[&str] =
    &["inbox", "sent", "drafts", "trash", "archive", "spam"];

fn is_sortable_local_folder_id(folder_id: &str) -> bool {
    folder_id.starts_with("custom:") || LOCAL_SORTABLE_BUILTIN_FOLDER_IDS.contains(&folder_id)
}

fn compare_local_folder_siblings(
    left_id: &str,
    left_label: &str,
    right_id: &str,
    right_label: &str,
    order: &BTreeMap<String, u32>,
) -> std::cmp::Ordering {
    compare_folder_siblings(left_id, left_label, right_id, right_label, order)
}

#[cfg(test)]
fn ordered_local_folder_ids(
    folder_ids: &HashSet<String>,
    order: &BTreeMap<String, u32>,
) -> Vec<String> {
    fn append_children(
        parent: Option<&str>,
        folder_ids: &HashSet<String>,
        order: &BTreeMap<String, u32>,
        result: &mut Vec<String>,
    ) {
        let mut children = folder_ids
            .iter()
            .filter(|folder_id| local_folder_parent_id(folder_id).as_deref() == parent)
            .cloned()
            .collect::<Vec<_>>();
        children.sort_by(|left, right| {
            compare_folder_siblings(
                left,
                &MailPage::local_folder_label(left),
                right,
                &MailPage::local_folder_label(right),
                order,
            )
        });
        for child in children {
            result.push(child.clone());
            append_children(Some(&child), folder_ids, order, result);
        }
    }

    let mut result = Vec::with_capacity(folder_ids.len());
    append_children(None, folder_ids, order, &mut result);
    result
}

fn ordered_local_sidebar_folder_ids(
    folder_ids: &HashSet<String>,
    order: &BTreeMap<String, u32>,
) -> Vec<String> {
    fn append_children(
        parent: Option<&str>,
        folder_ids: &HashSet<String>,
        order: &BTreeMap<String, u32>,
        result: &mut Vec<String>,
    ) {
        let mut children = folder_ids
            .iter()
            .filter(|folder_id| local_folder_parent_id(folder_id).as_deref() == parent)
            .cloned()
            .collect::<Vec<_>>();
        if parent.is_none() {
            children.extend(
                LOCAL_SORTABLE_BUILTIN_FOLDER_IDS
                    .iter()
                    .map(|folder_id| (*folder_id).to_string()),
            );
        }
        children.sort_by(|left, right| {
            compare_local_folder_siblings(
                left,
                &MailPage::local_folder_sort_label(left),
                right,
                &MailPage::local_folder_sort_label(right),
                order,
            )
        });
        for child in children {
            result.push(child.clone());
            if child.starts_with("custom:") {
                append_children(Some(&child), folder_ids, order, result);
            }
        }
    }

    let mut result = Vec::with_capacity(folder_ids.len() + LOCAL_SORTABLE_BUILTIN_FOLDER_IDS.len());
    append_children(None, folder_ids, order, &mut result);
    result
}

