impl PendingMailApply {
    fn from_camel(
        mut request: MailLoadRequest,
        mut camel: CamelMailLoad,
        local_messages: Option<Vec<ParsedMail>>,
        local_deleted_ids: HashSet<String>,
        searchable_body_texts: SearchableBodyTextCache,
        local_folders: HashSet<String>,
        replace: bool,
        previous_selection: MailSelectionAnchor,
        pending_search: Option<String>,
        generation: u64,
        graph_search_state: Option<GraphSearchState>,
        is_same_folder_refresh: bool,
    ) -> Self {
        let status = format_camel_status(&camel);
        let has_more = if camel.is_graph {
            if camel.search_query.is_some() {
                camel.graph_search_next_cursor.is_some()
            } else {
                !camel.graph_next_links.is_empty()
            }
        } else {
            camel.has_more_for(
                request.source_uid.as_deref(),
                request.folder_name.as_deref(),
                request.offset,
                request.max_messages_per_folder,
            )
        };
        request.graph_cursors = camel.graph_next_links.clone();
        let graph_search_next_cursor = camel.graph_search_next_cursor.clone();
        let camel_warning_visible =
            camel.warning.is_some() || !camel.folders.iter().any(|folder| folder.is_selectable);
        let messages = std::mem::take(&mut camel.messages);
        let camel_folders = camel.folders;

        let combined = local_messages.is_some();
        Self {
            started: Instant::now(),
            generation,
            request,
            replace,
            previous_selection,
            pending_search,
            result_kind: if combined { "combined" } else { "camel" },
            stage: PendingMailApplyStage::Camel,
            active_messages: messages,
            combined,
            local_messages,
            local_deleted_ids,
            searchable_body_texts,
            local_folders,
            local_counts: HashMap::new(),
            existing_ids: HashSet::new(),
            appended: 0,
            camel_folders,
            camel_status: Some(status),
            camel_has_more: has_more,
            camel_warning_visible,
            camel_is_graph: camel.is_graph,
            camel_search_applied: camel.search_query.is_some(),
            graph_search_state,
            graph_search_next_cursor,
            local_reason: None,
            is_same_folder_refresh,
            existing_messages: HashMap::new(),
            existing_messages_by_uid: HashMap::new(),
            incoming_ids: HashSet::new(),
        }
    }

    fn from_local(
        request: MailLoadRequest,
        reason: String,
        messages: Vec<ParsedMail>,
        local_deleted_ids: HashSet<String>,
        searchable_body_texts: SearchableBodyTextCache,
        local_folders: HashSet<String>,
        replace: bool,
        previous_selection: MailSelectionAnchor,
        generation: u64,
        is_same_folder_refresh: bool,
    ) -> Self {
        Self {
            started: Instant::now(),
            generation,
            request,
            replace,
            previous_selection,
            pending_search: None,
            result_kind: "local",
            stage: PendingMailApplyStage::Local,
            active_messages: messages,
            combined: false,
            local_messages: None,
            local_deleted_ids,
            searchable_body_texts,
            local_folders,
            local_counts: HashMap::new(),
            existing_ids: HashSet::new(),
            appended: 0,
            camel_folders: Vec::new(),
            camel_status: None,
            camel_has_more: false,
            camel_warning_visible: false,
            camel_is_graph: false,
            camel_search_applied: false,
            graph_search_state: None,
            graph_search_next_cursor: None,
            local_reason: Some(reason),
            is_same_folder_refresh,
            existing_messages: HashMap::new(),
            existing_messages_by_uid: HashMap::new(),
            incoming_ids: HashSet::new(),
        }
    }
}

pub(crate) fn parsed_mail_belongs_to_disabled_account(mail: &ParsedMail) -> bool {
    if let Some(ref loc) = mail.backend_location {
        let canon = MailPage::canonical_account_uid(&loc.source_uid);
        if !canon.is_empty() && canon != "local" {
            return !eds_service::is_source_enabled_for_service(canon, EdsSourceKind::Mail);
        }
    }
    if let Some(ref raw_headers) = mail.raw_headers {
        let header_str = String::from_utf8_lossy(raw_headers);
        for line in header_str.lines() {
            let trimmed = line.trim();
            if let Some(rest) = trimmed
                .strip_prefix("X-Evolution-Source-Folder:")
                .or_else(|| trimmed.strip_prefix("X-Evolution-Fcc:"))
            {
                if let Some(folder_uri) = rest.trim().strip_prefix("folder://") {
                    if let Some((uid, _)) = folder_uri.split_once('/') {
                        let uid = uid.trim();
                        if !uid.is_empty()
                            && uid != "local"
                            && !eds_service::is_source_enabled_for_service(uid, EdsSourceKind::Mail)
                        {
                            return true;
                        }
                    }
                }
            }
            if let Some(delivered_to) = trimmed.strip_prefix("Delivered-To:") {
                let addr = delivered_to.trim();
                if eds_service::is_email_account_disabled_for_mail(addr) {
                    return true;
                }
            }
        }
    }
    for (_, email) in parse_email_recipients(&mail.recipient_to)
        .into_iter()
        .chain(parse_email_recipients(&mail.recipient_cc))
    {
        if eds_service::is_email_account_disabled_for_mail(&email) {
            return true;
        }
    }
    if eds_service::is_email_account_disabled_for_mail(&mail.sender_email) {
        return true;
    }
    false
}

fn load_mail_backend(
    input: MailLoadWorkerInput,
    cancelled: &Arc<AtomicBool>,
    progress_sender: Option<&async_channel::Sender<camel_mail_service::CamelSyncProgress>>,
) -> MailPageLoadResult {
    let MailLoadWorkerInput {
        request,
        offline_mode,
        show_deleted,
        store_config,
    } = input;
    let started = Instant::now();
    tracing::debug!(
        source_uid = ?request.source_uid,
        folder_name = ?request.folder_name,
        offset = request.offset,
        limit = request.max_messages_per_folder,
        "Mail backend load started"
    );
    let try_cached_sqlite = || -> Option<MailPageLoadResult> {
        let hint = request.source_uid.as_deref();
        let page_limit = request.max_messages_per_folder.max(1) as usize;
        if hint.is_none() {
            let (sqlite_folders, sqlite_msgs, source_count) =
                crate::services::evolution_summary_cache::load_unified_accounts_from_sqlite(
                    page_limit.min(500),
                );
            if !sqlite_folders.is_empty() || !sqlite_msgs.is_empty() {
                let fast_load = camel_mail_service::CamelMailLoad {
                    messages: sqlite_msgs,
                    folders: sqlite_folders,
                    configured_sources: source_count.max(1),
                    successful_sources: 0,
                    failed_sources: source_count.max(1),
                    warning: Some(format!(
                        "{} · {}",
                        gettext("Offline"),
                        gettext("Showing cached messages")
                    )),
                    is_graph: false,
                    search_query: None,
                    graph_next_links: HashMap::new(),
                    graph_search_next_cursor: None,
                };
                return Some(prepared_camel_result(fast_load, cancelled));
            }
        }
        if let Some(cache) = crate::services::evolution_summary_cache::find_evolution_account_cache(hint) {
            let effective_source = hint.unwrap_or(&cache.source_uid);
            let folder_to_load = request
                .folder_name
                .as_deref()
                .unwrap_or("");
            let sqlite_folders = crate::services::evolution_summary_cache::load_folders_from_sqlite(
                &cache.folders_db,
                &cache.source_uid,
                &cache.display_name,
            )
            .unwrap_or_default();
            let page_limit = request
                .max_messages_per_folder
                .max(1) as usize;
            let sqlite_limit =
                crate::services::evolution_summary_cache::effective_sqlite_folder_limit(page_limit);
            let sqlite_msgs = crate::services::evolution_summary_cache::load_folder_messages_from_sqlite(
                &cache.folders_db,
                effective_source,
                folder_to_load,
                Some(sqlite_limit),
            )
            .unwrap_or_default();

            if !sqlite_folders.is_empty() || !sqlite_msgs.is_empty() {
                let fast_load = camel_mail_service::CamelMailLoad {
                    messages: sqlite_msgs,
                    folders: sqlite_folders,
                    configured_sources: 1,
                    successful_sources: 0,
                    failed_sources: 1,
                    warning: Some(format!("{} · {}", gettext("Offline"), gettext("Showing cached messages"))),
                    is_graph: false,
                    search_query: None,
                    graph_next_links: HashMap::new(),
                    graph_search_next_cursor: None,
                };
                return Some(prepared_camel_result(fast_load, cancelled));
            }
        }

        if let Some(mut cached) = camel_mail_service::load_mail_load_cache() {
            if !cached.folders.is_empty() || !cached.messages.is_empty() {
                cached.failed_sources = 1;
                cached.warning = Some(format!("{} · {}", gettext("Offline"), gettext("Showing cached messages")));
                return Some(prepared_camel_result(cached, cancelled));
            }
        }
        None
    };

    if offline_mode {
        let store = crate::services::MailStoreService::new_worker_safe(store_config.clone());
        let local_folders = store.local_folder_definitions();
        let (mut messages, local_deleted_ids) =
            store.load_local_records_with_deleted_cancelable(cancelled, show_deleted);
        messages.retain(|m| !parsed_mail_belongs_to_disabled_account(m));

        if let Some(MailPageLoadResult::Camel {
            mut camel,
            searchable_body_texts: mut camel_searchable_texts,
        }) = try_cached_sqlite()
        {
            camel.folders.retain(|f| {
                eds_service::is_source_enabled_for_service(&f.source_uid, EdsSourceKind::Mail)
            });
            camel
                .messages
                .retain(|m| !parsed_mail_belongs_to_disabled_account(m));
            if !camel.folders.is_empty() || !camel.messages.is_empty() {
                if request.is_remote_or_paged() {
                    return MailPageLoadResult::Camel {
                        camel,
                        searchable_body_texts: camel_searchable_texts,
                    };
                }
                let mut local_messages = messages;
                local_messages.retain(|m| {
                    let is_welcome = m.message_id.as_deref()
                        == Some("welcome-meridian@meridian.local")
                        || m.id.contains("welcome.eml");
                    local_folders.contains(&m.folder_id) || !is_welcome
                });
                let local_searchable_body_texts =
                    match prepare_searchable_body_texts(&local_messages, cancelled) {
                        Ok(texts) => texts,
                        Err(error) => return MailPageLoadResult::Error(error),
                    };
                camel_searchable_texts = merge_authoritative_searchable_body_texts(
                    camel_searchable_texts,
                    local_searchable_body_texts,
                );
                if local_messages.is_empty() && local_folders.is_empty() {
                    return MailPageLoadResult::Camel {
                        camel,
                        searchable_body_texts: camel_searchable_texts,
                    };
                }
                return MailPageLoadResult::Combined {
                    camel,
                    local_messages,
                    local_deleted_ids,
                    local_folders,
                    searchable_body_texts: camel_searchable_texts,
                };
            }
        }

        let searchable_body_texts = match prepare_searchable_body_texts(&messages, cancelled) {
            Ok(texts) => texts,
            Err(error) => return MailPageLoadResult::Error(error),
        };
        return MailPageLoadResult::Local {
            reason: "Offline-Modus: lokaler Meridian-Speicher".to_string(),
            messages,
            local_deleted_ids,
            local_folders,
            searchable_body_texts,
        };
    }
    tracing::debug!(
        elapsed_ms = started.elapsed().as_millis() as u64,
        "Starting synchronous EDS/Camel work on mail worker"
    );
    let camel_result = camel_mail_service::load_messages_page_with_progress_and_cancellation(
        request.source_uid.as_deref(),
        request.folder_name.as_deref(),
        request.offset,
        if request.source_uid.is_some() || request.folder_name.is_some() {
            request.max_messages_per_folder.max(500)
        } else {
            request.max_messages_per_folder
        },
        Some(cancelled),
        progress_sender,
    );
    if let Ok(ref camel) = camel_result {
        if request.source_uid.is_none()
            && request.folder_name.is_none()
            && request.offset == 0
            && (!camel.messages.is_empty() || !camel.folders.is_empty())
        {
            camel_mail_service::save_mail_load_cache(camel);
        }
    }
    tracing::debug!(
        elapsed_ms = started.elapsed().as_millis() as u64,
        result = if camel_result.is_ok() { "ok" } else { "error" },
        "Mail backend returned from EDS/Camel"
    );

    if cancelled.load(Ordering::Relaxed) {
        return MailPageLoadResult::Error(gettext("Mail loading was cancelled."));
    }

    if request.is_remote_or_paged() {
        return match camel_result {
            Ok(camel) => prepared_camel_result(camel, cancelled),
            Err(error) => match camel_mail_service::load_messages_graph(
                request.source_uid.as_deref(),
                request.folder_name.as_deref(),
                request.offset,
                request.max_messages_per_folder,
                &request.graph_cursors,
                cancelled,
            ) {
                Ok(graph) => prepared_camel_result(graph, cancelled),
                Err(graph_error) => {
                    if let Some(cached_res) = try_cached_sqlite() {
                        return cached_res;
                    }
                    MailPageLoadResult::Error(format!(
                        "{}: {error}; {}: {graph_error}",
                        gettext("Mail account synchronization unavailable"),
                        gettext("online search also unavailable")
                    ))
                }
            },
        };
    }

    match camel_result {
        Ok(mut camel)
            if camel.configured_sources > 0
                || !camel.messages.is_empty()
                || !camel.folders.is_empty() =>
        {
            camel.folders.retain(|f| {
                eds_service::is_source_enabled_for_service(&f.source_uid, EdsSourceKind::Mail)
            });
            camel
                .messages
                .retain(|m| !parsed_mail_belongs_to_disabled_account(m));
            let store = crate::services::MailStoreService::new_worker_safe(store_config.clone());
            let incoming_local_rules = MailFilterStore::default()
                .load()
                .into_iter()
                .filter(|rule| {
                    rule.enabled
                        && rule.scope == crate::services::mail_filter_service::FilterScope::Incoming
                        && rule.effective_actions().iter().any(|action| match action {
                            crate::services::mail_filter_service::FilterAction::MoveToFolder(t)
                            | crate::services::mail_filter_service::FilterAction::CopyToFolder(t) => {
                                crate::services::mail_filter_service::is_explicit_local_folder_target(t)
                            }
                            _ => false,
                        })
                })
                .collect::<Vec<_>>();
            if !incoming_local_rules.is_empty() && !camel.messages.is_empty() {
                let _ = store.apply_local_first_rules_to_remote_messages(
                    &incoming_local_rules,
                    &camel.messages,
                    cancelled,
                );
            }
            let local_folders = store.local_folder_definitions();
            let (mut local_messages, local_deleted_ids) =
                store.load_local_records_with_deleted_cancelable(cancelled, show_deleted);
            local_messages.retain(|m| {
                let is_welcome = m.message_id.as_deref()
                    == Some("welcome-meridian@meridian.local")
                    || m.id.contains("welcome.eml");
                (local_folders.contains(&m.folder_id) || !is_welcome)
                    && !parsed_mail_belongs_to_disabled_account(m)
            });
            let mut searchable_body_texts =
                match prepare_searchable_body_texts(&camel.messages, cancelled) {
                    Ok(texts) => texts,
                    Err(error) => return MailPageLoadResult::Error(error),
                };
            let local_searchable_body_texts =
                match prepare_searchable_body_texts(&local_messages, cancelled) {
                    Ok(texts) => texts,
                    Err(error) => return MailPageLoadResult::Error(error),
                };
            searchable_body_texts = merge_authoritative_searchable_body_texts(
                searchable_body_texts,
                local_searchable_body_texts,
            );
            if local_messages.is_empty() && local_folders.is_empty() {
                MailPageLoadResult::Camel {
                    camel,
                    searchable_body_texts,
                }
            } else {
                MailPageLoadResult::Combined {
                    camel,
                    local_messages,
                    local_deleted_ids,
                    local_folders,
                    searchable_body_texts,
                }
            }
        }
        Ok(_) => {
            if let Ok(graph) = camel_mail_service::load_messages_graph(
                request.source_uid.as_deref(),
                request.folder_name.as_deref(),
                request.offset,
                request.max_messages_per_folder,
                &request.graph_cursors,
                cancelled,
            ) {
                return prepared_camel_result(graph, cancelled);
            }
            if let Some(cached_res) = try_cached_sqlite() {
                return cached_res;
            }
            let store = crate::services::MailStoreService::new_worker_safe(store_config.clone());
            let (mut messages, local_deleted_ids) =
                store.load_local_records_with_deleted_cancelable(cancelled, show_deleted);
            messages.retain(|m| !parsed_mail_belongs_to_disabled_account(m));
            let searchable_body_texts = match prepare_searchable_body_texts(&messages, cancelled) {
                Ok(texts) => texts,
                Err(error) => return MailPageLoadResult::Error(error),
            };
            MailPageLoadResult::Local {
                reason: gettext("No active mail accounts; local Meridian storage"),
                messages,
                local_deleted_ids,
                local_folders: store.local_folder_definitions(),
                searchable_body_texts,
            }
        }
        Err(error) => {
            if let Ok(graph) = camel_mail_service::load_messages_graph(
                request.source_uid.as_deref(),
                request.folder_name.as_deref(),
                request.offset,
                request.max_messages_per_folder,
                &request.graph_cursors,
                cancelled,
            ) {
                return prepared_camel_result(graph, cancelled);
            }
            if let Some(cached_res) = try_cached_sqlite() {
                return cached_res;
            }
            let store = crate::services::MailStoreService::new_worker_safe(store_config);
            let (mut messages, local_deleted_ids) =
                store.load_local_records_with_deleted_cancelable(cancelled, show_deleted);
            messages.retain(|m| !parsed_mail_belongs_to_disabled_account(m));
            let searchable_body_texts = match prepare_searchable_body_texts(&messages, cancelled) {
                Ok(texts) => texts,
                Err(search_error) => {
                    return MailPageLoadResult::Error(search_error);
                }
            };
            MailPageLoadResult::Local {
                reason: gettext("Mail account synchronization unavailable ({error}); local Meridian storage")
                    .replace("{error}", &error.to_string()),
                messages,
                local_deleted_ids,
                local_folders: store.local_folder_definitions(),
                searchable_body_texts,
            }
        }
    }
}

fn format_camel_status(camel: &CamelMailLoad) -> String {
    let backend_label = if camel.search_query.is_some() {
        gettext("Graph Search")
    } else if camel.is_graph {
        "Microsoft Graph".to_string()
    } else {
        gettext("Mail Account")
    };
    let sync_status = if camel.failed_sources == 0 {
        ngettext(
            "{} account synchronized",
            "{} accounts synchronized",
            camel.successful_sources as u32,
        )
        .replace("{}", &camel.successful_sources.to_string())
    } else if camel.successful_sources > 0 {
        gettext("{}/{} accounts synchronized, {} with errors")
            .replace("{}/{}", &format!("{}/{}", camel.successful_sources, camel.configured_sources))
            .replace("{}", &camel.failed_sources.to_string())
    } else {
        ngettext(
            "{} account not synchronized",
            "{} accounts not synchronized",
            camel.failed_sources as u32,
        )
        .replace("{}", &camel.failed_sources.to_string())
    };
    let message_status = ngettext(
        "{} message loaded",
        "{} messages loaded",
        camel.messages.len() as u32,
    )
    .replace("{}", &camel.messages.len().to_string());
    let warning = camel
        .warning
        .as_deref()
        .map(|warning| format!(" · {}: {warning}", gettext("Note")))
        .unwrap_or_default();
    let folder_warning = (camel.configured_sources > 0
        && camel.successful_sources > 0
        && !camel.folders.iter().any(|folder| folder.is_selectable))
    .then(|| format!(" · {}", gettext("No readable mail folders found")))
    .unwrap_or_default();

    format!(
        "{backend_label}: {sync_status}, {message_status}{warning}{folder_warning}"
    )
}

fn pending_graph_search_input(
    camel: &CamelMailLoad,
    input: Option<&str>,
    suppress_retry: bool,
) -> Option<String> {
    if suppress_retry || !camel.is_graph || camel.search_query.is_some() {
        return None;
    }
    let input = input?.trim();
    (!input.is_empty()).then(|| input.to_string())
}

#[derive(Clone, Debug, PartialEq)]
pub(crate) enum AgendaSidebarCanvasItem {
    DateHeader {
        date: chrono::NaiveDate,
        title: String,
        is_expanded: bool,
        y: f64,
        height: f64,
    },
    TasksSectionHeader {
        title: String,
        is_expanded: bool,
        y: f64,
        height: f64,
    },
    EventBar {
        event: crate::services::calendar_store_service::CalendarEventRecord,
        color: String,
        is_dark: bool,
        time_str: Option<String>,
        summary: String,
        y: f64,
        height: f64,
    },
    TaskRow {
        task: crate::services::calendar_store_service::TaskRecord,
        completed: bool,
        summary: String,
        checkbox_rect: (f64, f64, f64, f64),
        y: f64,
        height: f64,
    },
    EmptyState {
        text: String,
        y: f64,
        height: f64,
    },
}

impl AgendaSidebarCanvasItem {
    pub fn y(&self) -> f64 {
        match self {
            Self::DateHeader { y, .. } => *y,
            Self::TasksSectionHeader { y, .. } => *y,
            Self::EventBar { y, .. } => *y,
            Self::TaskRow { y, .. } => *y,
            Self::EmptyState { y, .. } => *y,
        }
    }

    pub fn height(&self) -> f64 {
        match self {
            Self::DateHeader { height, .. } => *height,
            Self::TasksSectionHeader { height, .. } => *height,
            Self::EventBar { height, .. } => *height,
            Self::TaskRow { height, .. } => *height,
            Self::EmptyState { height, .. } => *height,
        }
    }
}

