#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) enum MailSidebarPanelId {
    Agenda,
    Tasks,
    Memos,
}

impl MailSidebarPanelId {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Agenda => "agenda",
            Self::Tasks => "tasks",
            Self::Memos => "memos",
        }
    }

    pub fn from_str(s: &str) -> Option<Self> {
        match s.trim() {
            "agenda" | "events" => Some(Self::Agenda),
            "tasks" => Some(Self::Tasks),
            "memos" => Some(Self::Memos),
            _ => None,
        }
    }

    pub fn display_title(&self) -> String {
        match self {
            Self::Agenda => gettext("Agenda"),
            Self::Tasks => gettext("Tasks"),
            Self::Memos => gettext("Memos"),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct MailSidebarPanelSpec {
    pub id: MailSidebarPanelId,
    pub mode: crate::views::calendar_page::SidebarPanelMode,
}

pub(crate) fn default_mail_sidebar_panel_specs() -> Vec<MailSidebarPanelSpec> {
    use crate::views::calendar_page::SidebarPanelMode;
    vec![
        MailSidebarPanelSpec {
            id: MailSidebarPanelId::Agenda,
            mode: SidebarPanelMode::Split,
        },
        MailSidebarPanelSpec {
            id: MailSidebarPanelId::Tasks,
            mode: SidebarPanelMode::Split,
        },
        MailSidebarPanelSpec {
            id: MailSidebarPanelId::Memos,
            mode: SidebarPanelMode::Off,
        },
    ]
}

pub(crate) fn parse_mail_sidebar_layout(raw: &str) -> Vec<MailSidebarPanelSpec> {
    use crate::views::calendar_page::SidebarPanelMode;
    let mut specs = Vec::new();
    for part in raw.split(',') {
        let mut iter = part.split(':');
        let Some(id_str) = iter.next() else { continue };
        let Some(mode_str) = iter.next() else { continue };
        let Some(id) = MailSidebarPanelId::from_str(id_str) else { continue };
        let Some(mode) = SidebarPanelMode::from_str(mode_str) else { continue };
        if !specs.iter().any(|s: &MailSidebarPanelSpec| s.id == id) {
            specs.push(MailSidebarPanelSpec { id, mode });
        }
    }
    for fallback in default_mail_sidebar_panel_specs() {
        if !specs.iter().any(|s| s.id == fallback.id) {
            specs.push(fallback);
        }
    }
    if !specs.iter().any(|s| s.mode != SidebarPanelMode::Off) {
        specs[0].mode = SidebarPanelMode::Split;
    }
    specs
}

pub(crate) fn format_mail_sidebar_layout(specs: &[MailSidebarPanelSpec]) -> String {
    format_mail_sidebar_layout_with_heights(specs, None, None, None)
}

pub(crate) fn format_mail_sidebar_layout_with_heights(
    specs: &[MailSidebarPanelSpec],
    vpane_bottom: Option<i32>,
    inner_bottom: Option<i32>,
    sidebar_width: Option<i32>,
) -> String {
    let mut parts: Vec<String> = specs
        .iter()
        .map(|s| format!("{}:{}", s.id.as_str(), s.mode.as_str()))
        .collect();
    if let Some(b) = vpane_bottom.filter(|&v| v >= 60) {
        parts.push(format!("vpane_bottom:{b}"));
    }
    if let Some(ib) = inner_bottom.filter(|&v| v >= 60) {
        parts.push(format!("inner_bottom:{ib}"));
    }
    if let Some(sw) = sidebar_width.filter(|&v| (185..=380).contains(&v)) {
        parts.push(format!("sidebar_w:{sw}"));
    }
    parts.join(",")
}

pub(crate) fn parse_mail_sidebar_manual_heights(raw: &str) -> (Option<i32>, Option<i32>, Option<i32>) {
    let mut vpane_bottom = None;
    let mut inner_bottom = None;
    let mut sidebar_width = None;
    for part in raw.split(',') {
        let mut iter = part.split(':');
        let Some(k) = iter.next() else { continue };
        let Some(v) = iter.next() else { continue };
        if k.trim() == "vpane_bottom" {
            if let Ok(px) = v.trim().parse::<i32>() {
                if (60..=1600).contains(&px) {
                    vpane_bottom = Some(px);
                }
            }
        } else if k.trim() == "inner_bottom" {
            if let Ok(px) = v.trim().parse::<i32>() {
                if (60..=1600).contains(&px) {
                    inner_bottom = Some(px);
                }
            }
        } else if k.trim() == "sidebar_w" {
            if let Ok(px) = v.trim().parse::<i32>() {
                if (185..=380).contains(&px) {
                    sidebar_width = Some(px);
                }
            }
        }
    }
    (vpane_bottom, inner_bottom, sidebar_width)
}

