    pub(crate) fn cached_folder_summaries(&self) -> Vec<CamelFolderSummary> {
        self.imp().mail_folder_summaries.borrow().clone()
    }

    pub fn pin_selected_folder_to_toolbar(&self) {
        let sel = self.folder_context_action_selection();
        let token = if sel.is_remote() {
            let src = sel.source_uid.as_deref().unwrap_or("");
            let fname = sel.folder_name.as_deref().unwrap_or(&sel.folder_id);
            let short = Self::clean_folder_display_title(fname).replace(',', " ");
            format!("folder:{src}::{fname}={short}")
        } else {
            let fid = sel.folder_id.trim();
            if fid.is_empty() {
                return;
            }
            let (raw_title, _) = sel.title_and_icon();
            let short = Self::clean_folder_display_title(&raw_title).replace(',', " ");
            format!("folder:{fid}={short}")
        };
        let base_key = token.split('=').next().unwrap_or(&token);
        if let Some(settings) = AppSettings::try_new() {
            let mut items = settings.mail_list_toolbar_items();
            if !items.iter().any(|it| it.split('=').next().unwrap_or(it) == base_key) {
                items.push(token);
                settings.set_mail_list_toolbar_items(&items);
            }
            if !settings.mail_show_toolbar() {
                settings.set_mail_show_toolbar(true);
            }
            self.rebuild_mail_list_toolbar();
            self.show_toast(&gettext("Folder pinned to Action Bar"));
        }
    }

    fn build_list_toolbar_overflow_button() -> (gtk::MenuButton, gtk::Box) {
        let pop_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(2)
            .margin_start(4)
            .margin_end(4)
            .margin_top(4)
            .margin_bottom(4)
            .build();
        let pop = gtk::Popover::builder()
            .child(&pop_box)
            .has_arrow(false)
            .css_classes(["menu", "context-menu"])
            .build();
        let overflow_btn = gtk::MenuButton::builder()
            .icon_name("pan-down-symbolic")
            .tooltip_text(gettext("More actions"))
            .popover(&pop)
            .valign(gtk::Align::Center)
            .halign(gtk::Align::End)
            .visible(false)
            .css_classes(["flat", "mail-list-bar-btn"])
            .build();
        (overflow_btn, pop_box)
    }

    pub(crate) fn update_mail_list_toolbar_active_states(&self) {
        if self.imp().mail_list_toolbar_entries.borrow().is_empty() {
            self.rebuild_mail_list_toolbar();
            return;
        }
        let active_qf = self
            .imp()
            .quick_filter
            .borrow()
            .as_ref()
            .map(|qf| qf.selected())
            .unwrap_or(0);
        let active_folder = self.active_folder_selection();
        let active_search_text = self
            .imp()
            .search_entry
            .borrow()
            .as_ref()
            .map(|e| e.text().to_string())
            .unwrap_or_default();

        let mut priority_changed = false;
        {
            let mut entries = self.imp().mail_list_toolbar_entries.borrow_mut();
            for entry in entries.iter_mut() {
                if entry.is_separator || entry.is_spacer {
                    continue;
                }
                let base_token = entry.base_token.as_str();
                let new_active = if let Some(filter_kind) = base_token.strip_prefix("filter:") {
                    if filter_kind == "today" {
                        active_search_text.trim().eq_ignore_ascii_case("on:today")
                    } else {
                        let qf_index = match filter_kind {
                            "unread" => Some(1u32),
                            "flagged" | "starred" => Some(2u32),
                            "important" => Some(3u32),
                            "attachment" | "attachments" => Some(4u32),
                            "followup" | "follow-up" => Some(5u32),
                            "memo" | "memos" => Some(6u32),
                            _ => None,
                        };
                        qf_index.is_some_and(|idx| active_qf == idx)
                    }
                } else if let Some(folder_spec) = base_token.strip_prefix("folder:") {
                    let target_sel = if let Some((src, fname)) = folder_spec.split_once("::") {
                        FolderSelection {
                            folder_id: fname.to_string(),
                            source_uid: Some(src.to_string()),
                            folder_name: Some(fname.to_string()),
                        }
                    } else {
                        FolderSelection::from_folder_id(folder_spec)
                    };
                    active_folder == target_sel
                } else if let Some(label_tag) = base_token.strip_prefix("label:") {
                    let query_token = format!("tag:{label_tag}");
                    active_search_text.trim().eq_ignore_ascii_case(&query_token)
                } else {
                    false
                };

                if entry.is_active != new_active {
                    entry.is_active = new_active;
                    if new_active {
                        entry.widget.add_css_class("active");
                    } else {
                        entry.widget.remove_css_class("active");
                    }
                    if base_token.starts_with("filter:") {
                        let new_prio = if new_active || entry.has_custom_alias { 2 } else { 1 };
                        if entry.collapse_priority != new_prio {
                            entry.collapse_priority = new_prio;
                            priority_changed = true;
                        }
                    }
                }
            }
        }
        if priority_changed {
            self.imp().mail_list_toolbar_last_width.set(-1);
            self.sync_list_toolbar_responsive();
        }
    }

    pub(crate) fn rebuild_mail_list_toolbar(&self) {
        let Some(container) = self.imp().mail_list_toolbar_box.borrow().clone() else {
            return;
        };
        while let Some(child) = container.first_child() {
            container.remove(&child);
        }

        let items = AppSettings::try_new()
            .map(|s| s.mail_list_toolbar_items())
            .unwrap_or_else(|| {
                crate::services::settings_service::DEFAULT_MAIL_LIST_TOOLBAR_ITEMS
                    .iter()
                    .map(|id| (*id).to_string())
                    .collect()
            });
        let configured_labels = AppSettings::try_new()
            .map(|s| s.mail_labels())
            .unwrap_or_default();
        let active_qf = self
            .imp()
            .quick_filter
            .borrow()
            .as_ref()
            .map(|qf| qf.selected())
            .unwrap_or(0);
        let active_folder = self.active_folder_selection();
        let active_search_text = self
            .imp()
            .search_entry
            .borrow()
            .as_ref()
            .map(|e| e.text().to_string())
            .unwrap_or_default();

        let mut entries: Vec<ListToolbarEntry> = Vec::with_capacity(items.len());
        let measure_pill = |btn: &gtk::Button, lbl: &Option<gtk::Label>| -> (i32, i32) {
            if let Some(l) = lbl {
                l.set_visible(true);
                btn.remove_css_class("compact-pill");
                let (_, nat_full, _, _) = btn.measure(gtk::Orientation::Horizontal, -1);
                l.set_visible(false);
                btn.add_css_class("compact-pill");
                let (_, nat_compact, _, _) = btn.measure(gtk::Orientation::Horizontal, -1);
                l.set_visible(true);
                btn.remove_css_class("compact-pill");
                (nat_full.max(30) + 2, nat_compact.max(28) + 2)
            } else {
                let (_, nat_w, _, _) = btn.measure(gtk::Orientation::Horizontal, -1);
                let w = nat_w.max(28) + 2;
                (w, w)
            }
        };

        for (item_idx, raw_item) in items.iter().enumerate() {
            let (base_token, custom_alias) = match raw_item.split_once('=') {
                Some((b, a)) => (b.trim(), Some(a.trim().to_string())),
                None => (raw_item.trim(), None),
            };
            if base_token.is_empty() {
                continue;
            }
            if base_token == "separator" {
                let sep = gtk::Separator::new(gtk::Orientation::Vertical);
                self.attach_list_toolbar_item_context_menu(&sep, item_idx, base_token, custom_alias.as_deref());
                container.append(&sep);
                entries.push(ListToolbarEntry {
                    widget: sep.upcast(),
                    button: None,
                    pill_label: None,
                    full_w: 6,
                    compact_w: 6,
                    is_separator: true,
                    is_spacer: false,
                    collapse_priority: 0,
                    menu_label: String::new(),
                    menu_icon: String::new(),
                    is_active: false,
                    base_token: base_token.to_string(),
                    has_custom_alias: false,
                });
                continue;
            }
            if base_token == "spacer" {
                let spacer = gtk::Box::builder()
                    .orientation(gtk::Orientation::Horizontal)
                    .hexpand(true)
                    .width_request(12)
                    .build();
                self.attach_list_toolbar_item_context_menu(&spacer, item_idx, base_token, custom_alias.as_deref());
                container.append(&spacer);
                entries.push(ListToolbarEntry {
                    widget: spacer.upcast(),
                    button: None,
                    pill_label: None,
                    full_w: 12,
                    compact_w: 12,
                    is_separator: false,
                    is_spacer: true,
                    collapse_priority: 0,
                    menu_label: String::new(),
                    menu_icon: String::new(),
                    is_active: false,
                    base_token: base_token.to_string(),
                    has_custom_alias: false,
                });
                continue;
            }

            if let Some(filter_kind) = base_token.strip_prefix("filter:") {
                if filter_kind == "today" {
                    let default_label = gettext("Today");
                    let has_alias = custom_alias.as_deref().is_some_and(|s| !s.is_empty());
                    let display_label = custom_alias.clone().unwrap_or(default_label);
                    let query_token = "on:today";
                    let is_active = active_search_text.trim().eq_ignore_ascii_case(query_token);
                    let (btn, pill_lbl) = Self::make_list_toolbar_pill_with_label(
                        "x-office-calendar-symbolic",
                        &display_label,
                        &display_label,
                        is_active,
                    );
                    let page_weak = self.downgrade();
                    btn.connect_clicked(move |_| {
                        let Some(page) = page_weak.upgrade() else { return; };
                        if let Some(entry) = page.imp().search_entry.borrow().as_ref() {
                            let cur = entry.text().to_string();
                            if cur.trim().eq_ignore_ascii_case(query_token) {
                                entry.set_text("");
                            } else {
                                entry.set_text(query_token);
                            }
                        }
                        page.update_mail_list_toolbar_active_states();
                    });
                    self.attach_list_toolbar_item_context_menu(&btn, item_idx, base_token, custom_alias.as_deref());
                    container.append(&btn);
                    let (full_w, compact_w) = measure_pill(&btn, &pill_lbl);
                    entries.push(ListToolbarEntry {
                        widget: btn.clone().upcast(),
                        button: Some(btn),
                        pill_label: pill_lbl,
                        full_w,
                        compact_w,
                        is_separator: false,
                        is_spacer: false,
                        collapse_priority: if is_active { 2 } else if has_alias { 2 } else { 1 },
                        menu_label: display_label,
                        menu_icon: "x-office-calendar-symbolic".to_string(),
                        is_active,
                        base_token: base_token.to_string(),
                        has_custom_alias: has_alias,
                    });
                    continue;
                }
                let (qf_index, default_label, icon_name) = match filter_kind {
                    "unread" => (1u32, gettext("Unread"), "mail-unread-symbolic"),
                    "flagged" | "starred" => (2u32, gettext("Starred"), "starred-symbolic"),
                    "important" => (3u32, gettext("Important"), "emblem-important-symbolic"),
                    "attachment" | "attachments" => (4u32, gettext("Attachments"), "mail-attachment-symbolic"),
                    "followup" | "follow-up" => (5u32, gettext("Follow-Up"), "bookmark-new-symbolic"),
                    "memo" | "memos" => (6u32, gettext("Memos"), "accessories-text-editor-symbolic"),
                    _ => continue,
                };
                let has_alias = custom_alias.as_deref().is_some_and(|s| !s.is_empty());
                let display_label = custom_alias.clone().unwrap_or(default_label);
                let is_active = active_qf == qf_index;
                let (btn, pill_lbl) = Self::make_list_toolbar_pill_with_label(
                    icon_name,
                    &display_label,
                    &display_label,
                    is_active,
                );
                let page_weak = self.downgrade();
                btn.connect_clicked(move |_| {
                    let Some(page) = page_weak.upgrade() else { return; };
                    if let Some(qf) = page.imp().quick_filter.borrow().as_ref() {
                        let next = if qf.selected() == qf_index { 0 } else { qf_index };
                        qf.set_selected(next);
                    }
                    page.update_mail_list_toolbar_active_states();
                });
                self.attach_list_toolbar_item_context_menu(&btn, item_idx, base_token, custom_alias.as_deref());
                container.append(&btn);
                let (full_w, compact_w) = measure_pill(&btn, &pill_lbl);
                entries.push(ListToolbarEntry {
                    widget: btn.clone().upcast(),
                    button: Some(btn),
                    pill_label: pill_lbl,
                    full_w,
                    compact_w,
                    is_separator: false,
                    is_spacer: false,
                    collapse_priority: if is_active { 2 } else if has_alias { 2 } else { 1 },
                    menu_label: display_label,
                    menu_icon: icon_name.to_string(),
                    is_active,
                    base_token: base_token.to_string(),
                    has_custom_alias: has_alias,
                });
                continue;
            }

            if let Some(folder_spec) = base_token.strip_prefix("folder:") {
                let (target_sel, default_label, icon_name) = if let Some((src, fname)) = folder_spec.split_once("::") {
                    let sel = FolderSelection {
                        folder_id: fname.to_string(),
                        source_uid: Some(src.to_string()),
                        folder_name: Some(fname.to_string()),
                    };
                    let lbl = Self::clean_folder_display_title(fname);
                    let (_, ic) = sel.title_and_icon();
                    (sel, lbl, ic)
                } else {
                    let sel = FolderSelection::from_folder_id(folder_spec);
                    let (raw_t, ic) = sel.title_and_icon();
                    let lbl = Self::clean_folder_display_title(&raw_t);
                    (sel, lbl, ic)
                };
                let has_alias = custom_alias.as_deref().is_some_and(|s| !s.is_empty());
                let display_label = custom_alias.clone().unwrap_or(default_label);
                let is_active = active_folder == target_sel;
                let (btn, pill_lbl) = Self::make_list_toolbar_pill_with_label(
                    icon_name,
                    &display_label,
                    &display_label,
                    is_active,
                );
                btn.add_css_class("folder-pill");
                let page_weak = self.downgrade();
                btn.connect_clicked(move |_| {
                    let Some(page) = page_weak.upgrade() else { return; };
                    if let Some(current) = page.imp().folder_selection.borrow().as_ref() {
                        current.replace(target_sel.clone());
                    }
                    page.select_folder_row(&target_sel);
                    page.refresh_mail();
                });
                self.attach_list_toolbar_item_context_menu(&btn, item_idx, base_token, custom_alias.as_deref());
                container.append(&btn);
                let (full_w, compact_w) = measure_pill(&btn, &pill_lbl);
                entries.push(ListToolbarEntry {
                    widget: btn.clone().upcast(),
                    button: Some(btn),
                    pill_label: pill_lbl,
                    full_w,
                    compact_w,
                    is_separator: false,
                    is_spacer: false,
                    collapse_priority: 3,
                    menu_label: display_label,
                    menu_icon: icon_name.to_string(),
                    is_active,
                    base_token: base_token.to_string(),
                    has_custom_alias: has_alias,
                });
                continue;
            }

            if let Some(label_tag) = base_token.strip_prefix("label:") {
                let def = configured_labels.iter().find(|d| {
                    d.tag.eq_ignore_ascii_case(label_tag) || d.name.eq_ignore_ascii_case(label_tag)
                });
                let default_label = def
                    .map(|d| d.display_name())
                    .unwrap_or_else(|| label_tag.to_string());
                let color_hex = def
                    .map(|d| d.color.clone())
                    .unwrap_or_else(|| "#3584e4".to_string());
                let has_alias = custom_alias.as_deref().is_some_and(|s| !s.is_empty());
                let display_label = custom_alias.clone().unwrap_or(default_label);
                let query_token = format!("tag:{label_tag}");
                let is_active = active_search_text.trim().eq_ignore_ascii_case(&query_token);
                let (btn, pill_lbl) = Self::make_list_toolbar_color_pill_with_label(&color_hex, &display_label, is_active);
                let page_weak = self.downgrade();
                btn.connect_clicked(move |_| {
                    let Some(page) = page_weak.upgrade() else { return; };
                    if let Some(entry) = page.imp().search_entry.borrow().as_ref() {
                        let cur = entry.text().to_string();
                        if cur.trim().eq_ignore_ascii_case(&query_token) {
                            entry.set_text("");
                        } else {
                            entry.set_text(&query_token);
                        }
                    }
                    page.update_mail_list_toolbar_active_states();
                });
                self.attach_list_toolbar_item_context_menu(&btn, item_idx, base_token, custom_alias.as_deref());
                container.append(&btn);
                let (full_w, compact_w) = measure_pill(&btn, &pill_lbl);
                entries.push(ListToolbarEntry {
                    widget: btn.clone().upcast(),
                    button: Some(btn),
                    pill_label: pill_lbl,
                    full_w,
                    compact_w,
                    is_separator: false,
                    is_spacer: false,
                    collapse_priority: 3,
                    menu_label: display_label,
                    menu_icon: "preferences-color-symbolic".to_string(),
                    is_active,
                    base_token: base_token.to_string(),
                    has_custom_alias: has_alias,
                });
                continue;
            }

            // Standard & List actions
            let (icon_name, default_label, action_name) = match base_token {
                "follow-up" => ("bookmark-new-symbolic", gettext("Follow-Up"), Some("win.edit-follow-up")),
                "star" => ("starred-symbolic", gettext("Star"), Some("win.toggle-star")),
                "important" => ("emblem-important-symbolic", gettext("Important"), Some("win.toggle-important")),
                "edit-labels" => ("preferences-color-symbolic", gettext("Labels"), Some("win.edit-message-labels")),
                "mark-read" => ("mail-read-symbolic", gettext("Mark Read"), Some("win.mark-read")),
                "mark-unread" => ("mail-unread-symbolic", gettext("Mark Unread"), Some("win.mark-unread")),
                "move" => ("folder-symbolic", gettext("Move To"), Some("win.move-message")),
                "copy" => ("edit-copy-symbolic", gettext("Copy To"), Some("win.copy-message")),
                "archive" => ("package-x-generic-symbolic", gettext("Archive"), Some("win.archive")),
                "delete" => ("user-trash-symbolic", gettext("Delete"), Some("win.delete")),
                "junk" => ("mail-mark-junk-symbolic", gettext("Junk"), Some("win.mark-junk")),
                "not-junk" => ("security-high-symbolic", gettext("Not Junk"), Some("win.mark-not-junk")),
                "mark-all-read" => ("mail-read-symbolic", gettext("All Read"), Some("win.mark-all-read")),
                "next-unread-folder" => ("go-jump-symbolic", gettext("Next Unread"), Some("win.next-unread-folder")),
                "expand-threads" => ("view-list-symbolic", gettext("Threads"), None),
                "mark-thread-read" => ("mail-read-symbolic", gettext("Read Thread"), Some("win.mark-thread-read")),
                "delete-thread" => ("user-trash-symbolic", gettext("Delete Thread"), Some("win.delete-thread")),
                "select-all" => ("edit-select-all-symbolic", gettext("Select All"), Some("win.select-all-messages")),
                "refresh-mail" => ("view-refresh-symbolic", gettext("Refresh"), Some("win.refresh-mail")),
                "apply-filters" => ("system-run-symbolic", gettext("Run Filters"), Some("win.apply-filters")),
                "filter-editor" => ("emblem-system-symbolic", gettext("Filter Rules"), Some("win.filter-editor")),
                "search-advanced" => ("system-search-symbolic", gettext("Adv. Search"), Some("win.search-advanced")),
                "oof-settings" => ("user-away-symbolic", gettext("Out of Office"), Some("win.open-oof-settings")),
                "expunge" => ("user-trash-symbolic", gettext("Expunge"), Some("win.folder-expunge")),
                "undo" => ("edit-undo-symbolic", gettext("Undo"), Some("win.undo")),
                "redo" => ("edit-redo-symbolic", gettext("Redo"), Some("win.redo")),
                "reply" => ("mail-reply-sender-symbolic", gettext("Reply"), Some("win.reply")),
                "reply-all" => ("mail-reply-all-symbolic", gettext("Reply All"), Some("win.reply-all")),
                "forward" => ("mail-forward-symbolic", gettext("Forward"), Some("win.forward")),
                "edit-as-new" => ("document-edit-symbolic", gettext("Edit as New"), Some("win.edit-as-new")),
                "add-sender-contact" => ("contact-new-symbolic", gettext("Add Contact"), Some("win.add-sender-to-contacts")),
                "memo" => ("accessories-text-editor-symbolic", gettext("Notes"), None),
                "print" => ("document-print-symbolic", gettext("Print"), Some("win.mail-print")),
                "export" => ("document-save-symbolic", gettext("Save EML"), Some("win.export")),
                "source" => ("text-x-generic-symbolic", gettext("Source"), Some("win.view-message-source")),
                "prev" => ("go-previous-symbolic", gettext("Previous"), Some("win.mail-prev")),
                "next" => ("go-next-symbolic", gettext("Next"), Some("win.mail-next")),
                _ => continue,
            };
            let show_text = custom_alias.as_deref().is_some_and(|s| !s.is_empty());
            let label_text = custom_alias.clone().unwrap_or_else(|| default_label.clone());
            let (btn, pill_lbl) = if show_text {
                Self::make_list_toolbar_pill_with_label(icon_name, &label_text, &default_label, false)
            } else {
                (Self::make_list_toolbar_icon_btn(icon_name, &default_label), None)
            };
            if let Some(act) = action_name {
                btn.set_action_name(Some(act));
            } else if base_token == "memo" {
                let page_weak = self.downgrade();
                btn.connect_clicked(move |_| {
                    let Some(page) = page_weak.upgrade() else { return; };
                    page.toggle_mail_memo_editor();
                });
            } else if base_token == "expand-threads" {
                let page_weak = self.downgrade();
                btn.connect_clicked(move |_| {
                    let Some(page) = page_weak.upgrade() else { return; };
                    let any_expanded = !page.imp().expanded_threads.borrow().is_empty();
                    if any_expanded {
                        page.collapse_all_threads();
                    } else {
                        page.expand_all_threads();
                    }
                });
            }
            self.attach_list_toolbar_item_context_menu(&btn, item_idx, base_token, custom_alias.as_deref());
            container.append(&btn);
            let (full_w, compact_w) = measure_pill(&btn, &pill_lbl);
            entries.push(ListToolbarEntry {
                widget: btn.clone().upcast(),
                button: Some(btn),
                pill_label: pill_lbl,
                full_w,
                compact_w,
                is_separator: false,
                is_spacer: false,
                collapse_priority: if show_text { 3 } else { 0 },
                menu_label: label_text,
                menu_icon: icon_name.to_string(),
                is_active: false,
                base_token: base_token.to_string(),
                has_custom_alias: show_text,
            });
        }

        self.imp().mail_list_toolbar_entries.replace(entries);
        self.imp().mail_list_toolbar_last_width.set(-1);
        self.sync_list_toolbar_responsive();

        let page_weak = self.downgrade();
        glib::idle_add_local_once(move || {
            if let Some(page) = page_weak.upgrade() {
                page.imp().mail_list_toolbar_last_width.set(-1);
                page.sync_list_toolbar_responsive();
            }
        });
    }

    pub(crate) fn sync_list_toolbar_responsive(&self) {
        let imp = self.imp();
        let entries = imp.mail_list_toolbar_entries.borrow().clone();
        if entries.is_empty() {
            if let Some(ob) = imp.mail_list_overflow_btn.borrow().as_ref() {
                ob.set_visible(false);
            }
            return;
        }

        let raw_w = imp
            .classic_toolbar
            .borrow()
            .as_ref()
            .map(|w| w.width())
            .filter(|&w| w > 40)
            .unwrap_or_else(|| {
                if imp.mail_layout.get() == MailLayout::Horizontal {
                    let w = imp.inner_paned.width();
                    if w > 40 { w } else { self.width() }
                } else {
                    let pos = imp.inner_paned.position();
                    if pos > 40 { pos } else { 380 }
                }
            });

        let avail_w = (raw_w - 20).max(60);
        if imp.mail_list_toolbar_last_width.get() == avail_w {
            return;
        }
        imp.mail_list_toolbar_last_width.set(avail_w);

        let n = entries.len();
        let mut compact = vec![false; n];
        let mut vis = vec![true; n];

        let calc_width = |c_flags: &[bool], v_flags: &[bool]| -> i32 {
            let mut sum = 0i32;
            let mut count = 0i32;
            for (i, e) in entries.iter().enumerate() {
                if !v_flags[i] {
                    continue;
                }
                sum += if c_flags[i] { e.compact_w } else { e.full_w };
                count += 1;
            }
            if count > 1 {
                sum += (count - 1) * 4;
            }
            sum
        };

        // Stage 1 & 2: If full pills exceed available width, progressively compact pill labels
        // from right to left (priority 1 = inactive filters, 2 = active/custom filters, 3 = folders/labels).
        if calc_width(&compact, &vis) > avail_w {
            for prio in 1..=3u8 {
                for idx in (0..n).rev() {
                    if entries[idx].collapse_priority == prio && entries[idx].pill_label.is_some() {
                        compact[idx] = true;
                        if calc_width(&compact, &vis) <= avail_w {
                            break;
                        }
                    }
                }
                if calc_width(&compact, &vis) <= avail_w {
                    break;
                }
            }
        }

        // Stage 3: If even with compacted pills total width still exceeds avail_w,
        // move overflowing rightmost items into the `▾` overflow popover menu.
        let mut has_overflow = false;
        if calc_width(&compact, &vis) > avail_w {
            let budget = (avail_w - 34).max(32);
            let mut running_w = 0i32;
            let mut shown_count = 0i32;
            for i in 0..n {
                let item_w = if compact[i] { entries[i].compact_w } else { entries[i].full_w };
                let step_w = if shown_count > 0 { item_w + 4 } else { item_w };
                if running_w + step_w <= budget || (shown_count == 0 && !entries[i].is_separator) {
                    vis[i] = true;
                    running_w += step_w;
                    shown_count += 1;
                } else {
                    for j in i..n {
                        vis[j] = false;
                        if !entries[j].is_separator && !entries[j].is_spacer {
                            has_overflow = true;
                        }
                    }
                    break;
                }
            }
        }

        // Clean up leading, trailing, or consecutive visible separators
        let mut prev_was_sep = true;
        for i in 0..n {
            if !vis[i] {
                continue;
            }
            if entries[i].is_separator {
                if prev_was_sep {
                    vis[i] = false;
                } else {
                    prev_was_sep = true;
                }
            } else {
                prev_was_sep = false;
            }
        }
        for i in (0..n).rev() {
            if !vis[i] {
                continue;
            }
            if entries[i].is_separator {
                vis[i] = false;
            } else {
                break;
            }
        }

        // Apply compact states and visibility to widgets
        for i in 0..n {
            if let Some(lbl) = entries[i].pill_label.as_ref() {
                lbl.set_visible(!compact[i]);
            }
            if compact[i] {
                entries[i].widget.add_css_class("compact-pill");
            } else {
                entries[i].widget.remove_css_class("compact-pill");
            }
            entries[i].widget.set_visible(vis[i]);
        }

        // Populate overflow menu if needed
        if let Some(overflow_btn) = imp.mail_list_overflow_btn.borrow().as_ref() {
            overflow_btn.set_visible(has_overflow);
            if let Some(overflow_box) = imp.mail_list_overflow_box.borrow().as_ref() {
                while let Some(child) = overflow_box.first_child() {
                    overflow_box.remove(&child);
                }
                if has_overflow {
                    let pop_opt = overflow_btn.popover();
                    for i in 0..n {
                        if vis[i] || entries[i].is_separator || entries[i].is_spacer {
                            continue;
                        }
                        let Some(target_btn) = entries[i].button.clone() else {
                            continue;
                        };
                        let row = gtk::Box::builder()
                            .orientation(gtk::Orientation::Horizontal)
                            .spacing(8)
                            .valign(gtk::Align::Center)
                            .build();
                        let img = gtk::Image::builder()
                            .pixel_size(16)
                            .valign(gtk::Align::Center)
                            .build();
                        set_image_icon_with_fallback(&img, &entries[i].menu_icon, "folder-symbolic");
                        let lbl = gtk::Label::builder()
                            .label(&entries[i].menu_label)
                            .halign(gtk::Align::Start)
                            .valign(gtk::Align::Center)
                            .build();
                        row.append(&img);
                        row.append(&lbl);

                        let mut classes = vec!["flat", "context-menu-item"];
                        if entries[i].is_active {
                            classes.push("active");
                        }
                        let menu_item = gtk::Button::builder()
                            .child(&row)
                            .halign(gtk::Align::Fill)
                            .css_classes(classes)
                            .build();
                        let pop_weak = pop_opt.as_ref().map(|p| p.downgrade());
                        let page_weak = self.downgrade();
                        menu_item.connect_clicked(move |_| {
                            if let Some(pw) = pop_weak.as_ref() {
                                if let Some(p) = pw.upgrade() {
                                    p.popdown();
                                }
                            }
                            if let Some(act) = target_btn.action_name() {
                                if let Some(page) = page_weak.upgrade() {
                                    let _ = page.activate_action(
                                        act.as_str(),
                                        target_btn.action_target_value().as_ref(),
                                    );
                                }
                            } else {
                                target_btn.emit_clicked();
                            }
                        });
                        overflow_box.append(&menu_item);
                    }
                }
            }
        }
    }

    fn make_list_toolbar_icon_btn(icon_name: &str, tooltip: &str) -> gtk::Button {
        let img = gtk::Image::builder()
            .pixel_size(16)
            .halign(gtk::Align::Center)
            .valign(gtk::Align::Center)
            .build();
        set_image_icon_with_fallback(&img, icon_name, "folder-symbolic");
        let btn = gtk::Button::builder()
            .child(&img)
            .tooltip_text(tooltip)
            .valign(gtk::Align::Center)
            .css_classes(["flat", "mail-list-bar-btn"])
            .build();
        set_accessible_label(&btn, tooltip);
        btn
    }

    fn make_list_toolbar_pill_with_label(
        icon_name: &str,
        label_text: &str,
        tooltip: &str,
        is_active: bool,
    ) -> (gtk::Button, Option<gtk::Label>) {
        let row = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(5)
            .valign(gtk::Align::Center)
            .build();
        let img = gtk::Image::builder()
            .pixel_size(16)
            .halign(gtk::Align::Center)
            .valign(gtk::Align::Center)
            .build();
        set_image_icon_with_fallback(&img, icon_name, "folder-symbolic");
        row.append(&img);
        let pill_lbl = if !label_text.trim().is_empty() {
            let lbl = gtk::Label::builder()
                .label(label_text)
                .valign(gtk::Align::Center)
                .build();
            row.append(&lbl);
            Some(lbl)
        } else {
            None
        };
        let mut classes = vec!["flat", "mail-list-bar-pill"];
        if is_active {
            classes.push("active");
        }
        let btn = gtk::Button::builder()
            .child(&row)
            .tooltip_text(tooltip)
            .valign(gtk::Align::Center)
            .css_classes(classes)
            .build();
        set_accessible_label(&btn, tooltip);
        (btn, pill_lbl)
    }

    fn make_list_toolbar_color_pill_with_label(
        color_hex: &str,
        label_text: &str,
        is_active: bool,
    ) -> (gtk::Button, Option<gtk::Label>) {
        let row = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(5)
            .valign(gtk::Align::Center)
            .build();
        let rgba = gdk::RGBA::parse(color_hex).unwrap_or_else(|_| gdk::RGBA::new(0.2, 0.5, 0.9, 1.0));
        let dot = gtk::DrawingArea::builder()
            .content_width(10)
            .content_height(10)
            .valign(gtk::Align::Center)
            .build();
        dot.set_draw_func(move |_, cr, w, h| {
            let r = (w.min(h) as f64) / 2.0;
            cr.arc(w as f64 / 2.0, h as f64 / 2.0, r, 0.0, std::f64::consts::TAU);
            cr.set_source_rgba(rgba.red() as f64, rgba.green() as f64, rgba.blue() as f64, 1.0);
            let _ = cr.fill();
        });
        row.append(&dot);
        let lbl = gtk::Label::builder()
            .label(label_text)
            .valign(gtk::Align::Center)
            .build();
        row.append(&lbl);
        let mut classes = vec!["flat", "mail-list-bar-pill"];
        if is_active {
            classes.push("active");
        }
        let btn = gtk::Button::builder()
            .child(&row)
            .tooltip_text(label_text)
            .valign(gtk::Align::Center)
            .css_classes(classes)
            .build();
        (btn, Some(lbl))
    }

    fn attach_list_toolbar_item_context_menu(
        &self,
        widget: &impl IsA<gtk::Widget>,
        item_idx: usize,
        base_token: &str,
        current_alias: Option<&str>,
    ) {
        let gesture = gtk::GestureClick::builder().button(3).build();
        let page_weak = self.downgrade();
        let base_token_str = base_token.to_string();
        let alias_str = current_alias.unwrap_or("").to_string();
        gesture.connect_pressed(move |g, _, x, y| {
            g.set_state(gtk::EventSequenceState::Claimed);
            let Some(page) = page_weak.upgrade() else { return; };
            let Some(parent) = g.widget() else { return; };
            let total_len = AppSettings::try_new()
                .map(|s| s.mail_list_toolbar_items().len())
                .unwrap_or(0);
            let pop_box = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .spacing(2)
                .margin_start(4)
                .margin_end(4)
                .margin_top(4)
                .margin_bottom(4)
                .build();
            let pop = gtk::Popover::builder()
                .child(&pop_box)
                .has_arrow(false)
                .css_classes(["menu", "context-menu"])
                .build();
            pop.set_parent(&parent);
            pop.set_pointing_to(Some(&gdk::Rectangle::new(x as i32, y as i32, 1, 1)));

            let make_menu_btn = |label: &str, sensitive: bool| -> gtk::Button {
                gtk::Button::builder()
                    .child(
                        &gtk::Label::builder()
                            .label(label)
                            .halign(gtk::Align::Start)
                            .build(),
                    )
                    .halign(gtk::Align::Fill)
                    .sensitive(sensitive)
                    .css_classes(["flat", "context-menu-item"])
                    .build()
            };

            if !matches!(base_token_str.as_str(), "separator" | "spacer") {
                let btn_rename = make_menu_btn(&gettext("Rename…"), true);
                let pop_weak_rn = pop.downgrade();
                let page_weak_rn = page.downgrade();
                let base_for_rn = base_token_str.clone();
                let alias_for_rn = alias_str.clone();
                btn_rename.connect_clicked(move |_| {
                    if let Some(p) = pop_weak_rn.upgrade() {
                        p.popdown();
                    }
                    let Some(pg) = page_weak_rn.upgrade() else { return; };
                    let dialog = adw::AlertDialog::builder()
                        .heading(gettext("Rename Action Bar Item"))
                        .body(gettext("Enter a custom label for this button, or leave it empty to use the default icon/name."))
                        .default_response("save")
                        .close_response("cancel")
                        .build();
                    dialog.add_response("cancel", &gettext("Cancel"));
                    dialog.add_response("save", &gettext("Save"));
                    dialog.set_response_appearance("save", adw::ResponseAppearance::Suggested);
                    let entry = gtk::Entry::builder()
                        .text(&alias_for_rn)
                        .placeholder_text(gettext("Default label"))
                        .activates_default(true)
                        .build();
                    dialog.set_extra_child(Some(&entry));
                    let entry_for_resp = entry.clone();
                    let base_save = base_for_rn.clone();
                    dialog.connect_response(Some("save"), move |_, _| {
                        if let Some(settings) = AppSettings::try_new() {
                            let mut items = settings.mail_list_toolbar_items();
                            if item_idx < items.len() {
                                let new_alias = entry_for_resp.text().trim().replace(',', " ");
                                items[item_idx] = if new_alias.is_empty() {
                                    base_save.clone()
                                } else {
                                    format!("{base_save}={new_alias}")
                                };
                                settings.set_mail_list_toolbar_items(&items);
                            }
                        }
                    });
                    dialog.present(Some(&pg));
                });
                pop_box.append(&btn_rename);
            }

            let btn_left = make_menu_btn(&gettext("Move Left"), item_idx > 0);
            let pop_weak_l = pop.downgrade();
            btn_left.connect_clicked(move |_| {
                if let Some(p) = pop_weak_l.upgrade() {
                    p.popdown();
                }
                if let Some(settings) = AppSettings::try_new() {
                    let mut items = settings.mail_list_toolbar_items();
                    if item_idx > 0 && item_idx < items.len() {
                        items.swap(item_idx, item_idx - 1);
                        settings.set_mail_list_toolbar_items(&items);
                    }
                }
            });
            pop_box.append(&btn_left);

            let btn_right = make_menu_btn(&gettext("Move Right"), item_idx + 1 < total_len);
            let pop_weak_r = pop.downgrade();
            btn_right.connect_clicked(move |_| {
                if let Some(p) = pop_weak_r.upgrade() {
                    p.popdown();
                }
                if let Some(settings) = AppSettings::try_new() {
                    let mut items = settings.mail_list_toolbar_items();
                    if item_idx + 1 < items.len() {
                        items.swap(item_idx, item_idx + 1);
                        settings.set_mail_list_toolbar_items(&items);
                    }
                }
            });
            pop_box.append(&btn_right);

            pop_box.append(&gtk::Separator::new(gtk::Orientation::Horizontal));

            let btn_remove = make_menu_btn(&gettext("Remove from Action Bar"), true);
            let pop_weak_rem = pop.downgrade();
            btn_remove.connect_clicked(move |_| {
                if let Some(p) = pop_weak_rem.upgrade() {
                    p.popdown();
                }
                if let Some(settings) = AppSettings::try_new() {
                    let mut items = settings.mail_list_toolbar_items();
                    if item_idx < items.len() {
                        items.remove(item_idx);
                        settings.set_mail_list_toolbar_items(&items);
                    }
                }
            });
            pop_box.append(&btn_remove);

            let btn_prefs = make_menu_btn(&gettext("Customize Action Bar…"), true);
            let pop_weak_prefs = pop.downgrade();
            let page_weak_prefs = page.downgrade();
            btn_prefs.connect_clicked(move |_| {
                if let Some(p) = pop_weak_prefs.upgrade() {
                    p.popdown();
                }
                if let Some(pg) = page_weak_prefs.upgrade() {
                    let _ = pg.activate_action("win.open-mail-list-toolbar-prefs", None);
                }
            });
            pop_box.append(&btn_prefs);

            pop.connect_closed(|p| {
                let p_clone = p.clone();
                glib::idle_add_local_once(move || {
                    p_clone.unparent();
                });
            });
            pop.popup();
        });
        widget.add_controller(gesture);
    }

    fn message_context_menu() -> gio::Menu {
        thread_local! {
            static CACHED_MESSAGE_CONTEXT_MENU: RefCell<Option<gio::Menu>> = const { RefCell::new(None) };
        }
        CACHED_MESSAGE_CONTEXT_MENU.with(|cached| {
            if let Some(ref menu) = *cached.borrow() {
                return menu.clone();
            }
            let menu = gio::Menu::new();

            // Section 1: Primary Respond Actions
            let respond_section = gio::Menu::new();
            respond_section.append(Some(&gettext("Reply")), Some("win.reply"));
            respond_section.append(Some(&gettext("Reply to All")), Some("win.reply-all"));
            respond_section.append(Some(&gettext("Forward")), Some("win.forward"));
            menu.append_section(None, &respond_section);

            // Section 2: Organize / Triage
            let triage_section = gio::Menu::new();
            triage_section.append(Some(&gettext("Mark as Read")), Some("win.mark-read"));
            triage_section.append(Some(&gettext("Mark as Unread")), Some("win.mark-unread"));
            triage_section.append(Some(&gettext("Toggle Flag")), Some("win.toggle-flag"));
            triage_section.append(Some(&gettext("Archive")), Some("win.archive"));
            triage_section.append(Some(&gettext("Move to Folder…")), Some("win.move-message"));
            triage_section.append(
                Some(&gettext("Go to Containing Folder")),
                Some("win.goto-containing-folder"),
            );
            triage_section.append(Some(&gettext("Mark as Junk")), Some("win.mark-junk"));
            menu.append_section(None, &triage_section);

            // Section 3: Destructive
            let delete_section = gio::Menu::new();
            delete_section.append(Some(&gettext("Delete")), Some("win.delete"));
            menu.append_section(None, &delete_section);

            *cached.borrow_mut() = Some(menu.clone());
            menu
        })
    }

    fn configure_unclipped_popover_menu(
        popover: &gtk::PopoverMenu,
        parent: &gtk::Widget,
        px: f64,
        py: f64,
    ) {
        if let Some(sw) = popover.child().and_downcast::<gtk::ScrolledWindow>() {
            sw.set_propagate_natural_height(true);
            sw.set_propagate_natural_width(true);
            sw.set_vscrollbar_policy(gtk::PolicyType::Never);
            sw.set_hscrollbar_policy(gtk::PolicyType::Never);
        }
        if let Some(root) = parent.root().and_downcast::<gtk::Window>() {
            let root_h = root.height() as f64;
            if root_h > 0.0 {
                if let Some(pt) = parent.compute_point(
                    &root,
                    &gtk::graphene::Point::new(px as f32, py as f32),
                ) {
                    let ry = pt.y() as f64;
                    let space_above = ry;
                    let space_below = (root_h - ry).max(0.0);
                    if space_above < 440.0 && space_below < 440.0 && root_h >= 440.0 {
                        popover.set_position(gtk::PositionType::Right);
                    }
                }
            }
        }
    }

    fn popup_message_context_menu(
        &self,
        anchor_widget: &impl IsA<gtk::Widget>,
        x: f64,
        y: f64,
    ) {
        if let Some(window) = self.root().and_downcast::<crate::window::MeridianWindow>() {
            window.update_message_actions_for_current_view();
        }
        let anchor_ref: &gtk::Widget = anchor_widget.as_ref();
        let (parent_widget, px, py): (gtk::Widget, f64, f64) =
            if anchor_ref.is::<gtk::DrawingArea>() {
                if let Some(parent) = anchor_ref.parent() {
                    let (tx, ty) = anchor_ref
                        .compute_point(
                            &parent,
                            &gtk::graphene::Point::new(x as f32, y as f32),
                        )
                        .map(|p| (p.x() as f64, p.y() as f64))
                        .unwrap_or((x, y));
                    (parent, tx, ty)
                } else {
                    (anchor_ref.clone(), x, y)
                }
            } else {
                (anchor_ref.clone(), x, y)
            };

        let popover = gtk::PopoverMenu::builder()
            .menu_model(&Self::message_context_menu())
            .has_arrow(false)
            .pointing_to(&gtk::gdk::Rectangle::new(px as i32, py as i32, 1, 1))
            .build();
        popover.set_parent(&parent_widget);
        Self::configure_unclipped_popover_menu(&popover, &parent_widget, px, py);
        popover.connect_closed(|popover| {
            let popover = popover.clone();
            glib::idle_add_local_once(move || {
                popover.unparent();
            });
        });
        popover.popup();
    }

    // ── Private: Build Message List with GListStore & Search Filter ───────

    fn mail_column_child(header: &gtk::Box, column: &str) -> Option<gtk::Widget> {
        let widget_name = format!("mail-column-{column}");
        let mut child = header.first_child();
        while let Some(widget) = child {
            if widget.widget_name() == widget_name {
                return Some(widget);
            }
            child = widget.next_sibling();
        }
        None
    }

    fn append_mail_columns(
        container: &gtk::Box,
        columns: Vec<(&'static str, gtk::Widget)>,
    ) {
        let order = AppSettings::try_new()
            .map(|settings| settings.mail_list_column_order())
            .unwrap_or_else(|| {
                crate::services::settings_service::MAIL_LIST_COLUMN_IDS
                    .iter()
                    .map(|column| (*column).to_string())
                    .collect()
            });
        for column in order {
            if let Some((_, widget)) = columns.iter().find(|(id, _)| *id == column) {
                widget.set_widget_name(&format!("mail-column-{column}"));
                container.append(widget);
            }
        }
    }

    fn reorder_mail_column_container(container: &gtk::Box) {
        let order = AppSettings::try_new()
            .map(|settings| settings.mail_list_column_order())
            .unwrap_or_else(|| {
                crate::services::settings_service::MAIL_LIST_COLUMN_IDS
                    .iter()
                    .map(|column| (*column).to_string())
                    .collect()
            });

        let mut existing_names = Vec::new();
        let mut child = container.first_child();
        while let Some(widget) = child {
            child = widget.next_sibling();
            let name = widget.widget_name().to_string();
            if name.starts_with("mail-column-") {
                existing_names.push(name);
            }
        }

        let mut target_names = Vec::new();
        let mut remaining: Vec<String> = existing_names.clone();
        let take_name = |wanted: &str, rem: &mut Vec<String>| -> Option<String> {
            if let Some(pos) = rem.iter().position(|n| n == wanted) {
                Some(rem.remove(pos))
            } else {
                None
            }
        };

        let mut first_right_col_seen = false;
        for column in &order {
            let col_name = format!("mail-column-{column}");
            if let Some(n) = take_name(&col_name, &mut remaining) {
                target_names.push(n);
                if column == "sender" {
                    if let Some(sep) = take_name("mail-column-sep-sender", &mut remaining) {
                        target_names.push(sep);
                    }
                } else if column == "recipient" {
                    if let Some(sep) = take_name("mail-column-sep-recipient", &mut remaining) {
                        target_names.push(sep);
                    }
                } else if column == "subject" {
                    if let Some(sep) = take_name("mail-column-sep-date", &mut remaining) {
                        target_names.push(sep);
                    }
                } else if (column == "date" || column == "size") && !first_right_col_seen {
                    first_right_col_seen = true;
                    if let Some(sep) = take_name("mail-column-sep-size", &mut remaining) {
                        target_names.push(sep);
                    }
                }
            }
        }
        let spacer_name = take_name("mail-column-scrollbar-spacer", &mut remaining);
        target_names.extend(remaining);
        if let Some(spacer) = spacer_name {
            target_names.push(spacer);
        }

        // If the column widgets are already in the exact target order, do not remove/re-append
        // children (which would disturb any open popover or active gesture on the header).
        if existing_names == target_names {
            let mut c = container.first_child();
            while let Some(widget) = c {
                c = widget.next_sibling();
                let name = widget.widget_name();
                if matches!(
                    name.as_str(),
                    "mail-column-preview"
                        | "mail-column-follow-up-due"
                        | "mail-column-location"
                        | "mail-column-important"
                ) {
                    widget.set_visible(false);
                }
            }
            return;
        }

        let mut children = HashMap::new();
        let mut child = container.first_child();
        while let Some(widget) = child {
            child = widget.next_sibling();
            let name = widget.widget_name().to_string();
            // Never remove non-column children (e.g. an open GtkPopover attached to the header)
            if name.starts_with("mail-column-") {
                container.remove(&widget);
                children.insert(name, widget);
            }
        }

        for name in target_names {
            if let Some(widget) = children.remove(&name) {
                if matches!(
                    name.as_str(),
                    "mail-column-preview"
                        | "mail-column-follow-up-due"
                        | "mail-column-location"
                        | "mail-column-important"
                ) {
                    widget.set_visible(false);
                }
                container.append(&widget);
            }
        }
    }

    fn rebuild_mail_column_layout(&self) {
        self.imp().mail_table_layout.replace(None);
        if let Some(header) = self.imp().mail_column_header.borrow().as_ref() {
            Self::reorder_mail_column_container(header);
        }
        self.refresh_mail_column_header();
        self.sync_mail_layout_visibility();
        self.sync_view_split_button();
        self.update_mail_table_canvas_layout();
        let list_view = self.imp().mail_list_view.borrow().as_ref().cloned();
        let factory = self.imp().mail_list_factory.borrow().as_ref().cloned();
        if let (Some(list_view), Some(factory)) = (list_view, factory) {
            if list_view.is_visible() {
                list_view.set_factory(None::<&gtk::ListItemFactory>);
                list_view.set_factory(Some(&factory));
            }
        }
        if let Some(canvas) = self.imp().mail_table_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
    }

    pub(crate) fn sync_view_split_button(&self) {
        let Some(split_btn) = self.imp().view_options_split_btn.borrow().clone() else {
            return;
        };
        let settings = AppSettings::try_new();
        let profile = settings
            .as_ref()
            .map(|s| s.mail_list_view_profile())
            .unwrap_or_else(|| "messages".to_string());
        let is_cards = profile == "cards" || profile == "wide";

        // In GNOME Files (Nautilus) split-button style:
        // The main button directly toggles between Table and List view.
        // Its icon and tooltip represent the view mode it will switch to on click
        // (Action-oriented toggle: in Table view -> shows List View "view-list-symbolic" to switch to List;
        // in List/Cards view -> shows Table View "meridian-view-table-symbolic" to switch to Table).
        let (icon_name, tooltip_text) = if is_cards {
            let theme = gtk::IconTheme::for_display(&split_btn.display());
            let icon = if theme.has_icon("meridian-view-table-symbolic") {
                "meridian-view-table-symbolic"
            } else if theme.has_icon("view-grid-symbolic") {
                "view-grid-symbolic"
            } else if theme.has_icon("view-column-symbolic") {
                "view-column-symbolic"
            } else {
                "meridian-view-table-symbolic"
            };
            (icon.to_string(), gettext("Table view"))
        } else {
            let theme = gtk::IconTheme::for_display(&split_btn.display());
            let icon = if theme.has_icon("view-list-symbolic") {
                "view-list-symbolic"
            } else if theme.has_icon("meridian-view-cards-symbolic") {
                "meridian-view-cards-symbolic"
            } else {
                "view-list-symbolic"
            };
            (icon.to_string(), gettext("List view"))
        };
        split_btn.set_icon_name(&icon_name);
        split_btn.set_tooltip_text(Some(&tooltip_text));
        set_accessible_label(&split_btn, &tooltip_text);
    }

    pub(crate) fn open_mail_column_order_dialog(&self) {
        let dialog_title = gettext("Customize Column Order");
        let dialog = adw::Window::builder()
            .title(&dialog_title)
            .modal(true)
            .default_width(400)
            .default_height(640)
            .build();
        if let Some(root) = self.root().and_downcast::<gtk::Window>() {
            dialog.set_transient_for(Some(&root));
        }

        let toolbar = adw::ToolbarView::new();
        let header = adw::HeaderBar::new();
        toolbar.add_top_bar(&header);

        let scrolled = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Never)
            .vscrollbar_policy(gtk::PolicyType::Automatic)
            .vexpand(true)
            .build();

        let content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(8)
            .margin_start(14)
            .margin_end(14)
            .margin_top(6)
            .margin_bottom(12)
            .build();

        let desc_label = gtk::Label::builder()
            .label(gettext("Use the arrows to reorder columns, and toggle visibility."))
            .wrap(true)
            .xalign(0.0)
            .css_classes(["dim-label", "caption"])
            .build();
        content.append(&desc_label);

        let list_box = gtk::ListBox::builder()
            .selection_mode(gtk::SelectionMode::None)
            .css_classes(["boxed-list"])
            .build();

        const TABLE_REORDERABLE_COLUMNS: [&str; 11] = [
            "status",
            "attachment",
            "flagged",
            "follow-up",
            "memo",
            "avatar",
            "sender",
            "recipient",
            "subject",
            "date",
            "size",
        ];

        let settings = AppSettings::try_new();
        let initial_order: Vec<String> = {
            let current = settings
                .as_ref()
                .map(|s| s.mail_list_column_order())
                .unwrap_or_else(|| {
                    crate::services::settings_service::MAIL_LIST_COLUMN_IDS
                        .iter()
                        .map(|id| (*id).to_string())
                        .collect()
                });
            let mut filtered = Vec::new();
            for col in current {
                if TABLE_REORDERABLE_COLUMNS.contains(&col.as_str()) && !filtered.contains(&col) {
                    filtered.push(col);
                }
            }
            for col in TABLE_REORDERABLE_COLUMNS {
                let s = col.to_string();
                if !filtered.contains(&s) {
                    filtered.push(s);
                }
            }
            filtered
        };

        let order_state = Rc::new(RefCell::new(initial_order));
        let page_weak = self.downgrade();

        fn save_and_rebuild_column_order(
            state: &Rc<RefCell<Vec<String>>>,
            settings: &Option<AppSettings>,
            page_weak: &glib::WeakRef<MailPage>,
        ) {
            let mut full_order = state.borrow().clone();
            for id in crate::services::settings_service::MAIL_LIST_COLUMN_IDS {
                let s = id.to_string();
                if !full_order.contains(&s) {
                    full_order.push(s);
                }
            }
            if let Some(settings) = settings.as_ref() {
                settings.set_mail_list_view_profile("custom");
                settings.set_mail_list_column_order(&full_order);
            }
            if let Some(page) = page_weak.upgrade() {
                page.rebuild_mail_column_layout();
            }
        }

        fn populate_order_list(
            list: &gtk::ListBox,
            state: &Rc<RefCell<Vec<String>>>,
            settings: &Option<AppSettings>,
            page_weak: &glib::WeakRef<MailPage>,
        ) {
            while let Some(child) = list.first_child() {
                list.remove(&child);
            }
            let columns = state.borrow().clone();
            for (index, column) in columns.iter().enumerate() {
                let (label_text, icon_name) = match column.as_str() {
                    "status" => (gettext("Status"), "mail-unread-symbolic"),
                    "attachment" => (gettext("Attachment"), "mail-attachment-symbolic"),
                    "flagged" => (gettext("Flag"), "starred-symbolic"),
                    "sender" => (gettext("Sender"), "avatar-default-symbolic"),
                    "recipient" => (gettext("Recipient"), "mail-send-symbolic"),
                    "subject" => (gettext("Subject"), "mail-message-new-symbolic"),
                    "date" => (gettext("Date"), "x-office-calendar-symbolic"),
                    "follow-up" => (gettext("Follow-up"), "mail-flag-symbolic"),
                    "memo" => (gettext("Memo"), "accessories-text-editor-symbolic"),
                    "avatar" => (gettext("Avatar"), "contact-new-symbolic"),
                    "size" => (gettext("Size"), "drive-harddisk-symbolic"),
                    _ => (column.clone(), "view-column-symbolic"),
                };

                let is_subject = column == "subject";
                let visible_active = if is_subject {
                    true
                } else if column == "avatar" {
                    page_weak
                        .upgrade()
                        .map(|p| p.mail_show_table_avatar())
                        .unwrap_or(false)
                } else if column == "memo" {
                    page_weak
                        .upgrade()
                        .map(|p| p.mail_show_table_memo_column())
                        .unwrap_or(false)
                } else if let Some(s) = settings {
                    match column.as_str() {
                        "status" => s.mail_show_status(),
                        "attachment" => s.mail_show_attachment(),
                        "flagged" => s.mail_show_flagged(),
                        "follow-up" => s.mail_show_follow_up(),
                        "sender" => s.mail_show_sender(),
                        "recipient" => s.mail_show_recipient(),
                        "date" => s.mail_show_date(),
                        "size" => s.mail_show_size(),
                        _ => true,
                    }
                } else {
                    true
                };

                let row_box = gtk::Box::builder()
                    .orientation(gtk::Orientation::Horizontal)
                    .spacing(8)
                    .css_classes(["column-order-row"])
                    .build();

                let check = gtk::CheckButton::builder()
                    .active(visible_active)
                    .sensitive(!is_subject)
                    .valign(gtk::Align::Center)
                    .tooltip_text(if is_subject {
                        gettext("Subject column is always visible")
                    } else {
                        gettext("Show column")
                    })
                    .build();
                if !is_subject {
                    let col_id = column.clone();
                    let settings_for_chk = settings.clone();
                    let page_for_chk = page_weak.clone();
                    check.connect_toggled(move |btn| {
                        let active = btn.is_active();
                        if col_id == "avatar" {
                            if let Some(page) = page_for_chk.upgrade() {
                                page.set_mail_show_table_avatar(active);
                                page.refresh_sender_avatars();
                                page.rebuild_mail_column_layout();
                            }
                            return;
                        }
                        if col_id == "memo" {
                            if let Some(page) = page_for_chk.upgrade() {
                                page.set_mail_show_table_memo_column(active);
                                page.rebuild_mail_column_layout();
                            }
                            return;
                        }
                        if let Some(ref s) = settings_for_chk {
                            match col_id.as_str() {
                                "status" => s.set_mail_show_status(active),
                                "attachment" => s.set_mail_show_attachment(active),
                                "flagged" => s.set_mail_show_flagged(active),
                                "follow-up" => s.set_mail_show_follow_up(active),
                                "sender" => s.set_mail_show_sender(active),
                                "recipient" => s.set_mail_show_recipient(active),
                                "date" => s.set_mail_show_date(active),
                                "size" => s.set_mail_show_size(active),
                                _ => {}
                            }
                        }
                        if let Some(page) = page_for_chk.upgrade() {
                            page.rebuild_mail_column_layout();
                        }
                    });
                }
                row_box.append(&check);

                let col_icon = gtk::Image::builder()
                    .icon_name(icon_name)
                    .pixel_size(15)
                    .css_classes(["dim-label"])
                    .build();
                row_box.append(&col_icon);

                let title_label = gtk::Label::builder()
                    .label(&label_text)
                    .xalign(0.0)
                    .hexpand(true)
                    .valign(gtk::Align::Center)
                    .build();
                row_box.append(&title_label);

                let arrows_box = gtk::Box::builder()
                    .orientation(gtk::Orientation::Horizontal)
                    .spacing(2)
                    .halign(gtk::Align::End)
                    .valign(gtk::Align::Center)
                    .hexpand(false)
                    .build();
                let up = gtk::Button::builder()
                    .icon_name("go-up-symbolic")
                    .tooltip_text(gettext("Move column up / left"))
                    .css_classes(["flat", "circular"])
                    .valign(gtk::Align::Center)
                    .sensitive(index > 0)
                    .build();
                let down = gtk::Button::builder()
                    .icon_name("go-down-symbolic")
                    .tooltip_text(gettext("Move column down / right"))
                    .css_classes(["flat", "circular"])
                    .valign(gtk::Align::Center)
                    .sensitive(index + 1 < columns.len())
                    .build();
                arrows_box.append(&up);
                arrows_box.append(&down);
                row_box.append(&arrows_box);

                let row = gtk::ListBoxRow::builder()
                    .activatable(false)
                    .selectable(false)
                    .focusable(false)
                    .child(&row_box)
                    .build();

                for (button, target) in [(up, index.checked_sub(1)), (down, Some(index + 1))] {
                    let state_rc = Rc::clone(state);
                    let list_cloned = list.clone();
                    let settings_cloned = settings.clone();
                    let page_weak_cloned = page_weak.clone();
                    button.connect_clicked(move |_| {
                        let Some(target) = target.filter(|target| *target < state_rc.borrow().len()) else {
                            return;
                        };
                        state_rc.borrow_mut().swap(index, target);
                        save_and_rebuild_column_order(&state_rc, &settings_cloned, &page_weak_cloned);
                        populate_order_list(&list_cloned, &state_rc, &settings_cloned, &page_weak_cloned);
                    });
                }

                list.append(&row);
            }
        }

        populate_order_list(&list_box, &order_state, &settings, &page_weak);
        content.append(&list_box);

        let reset_btn = gtk::Button::builder()
            .label(gettext("Restore Default Order"))
            .css_classes(["flat"])
            .halign(gtk::Align::Center)
            .margin_top(4)
            .build();
        let state_for_reset = Rc::clone(&order_state);
        let list_for_reset = list_box.clone();
        let settings_for_reset = settings.clone();
        let page_for_reset = page_weak.clone();
        reset_btn.connect_clicked(move |_| {
            let defaults: Vec<String> = TABLE_REORDERABLE_COLUMNS
                .iter()
                .map(|id| (*id).to_string())
                .collect();
            *state_for_reset.borrow_mut() = defaults;
            save_and_rebuild_column_order(&state_for_reset, &settings_for_reset, &page_for_reset);
            populate_order_list(&list_for_reset, &state_for_reset, &settings_for_reset, &page_for_reset);
        });
        content.append(&reset_btn);

        scrolled.set_child(Some(&content));

        if let Some(col_header) = self
            .imp()
            .mail_column_header
            .borrow()
            .as_ref()
            .cloned()
            .filter(|h| h.is_mapped())
        {
            col_header.set_vexpand(false);
            col_header.set_vexpand_set(true);

            let mut child = col_header.first_child();
            while let Some(w) = child {
                child = w.next_sibling();
                if let Ok(existing_pop) = w.downcast::<gtk::Popover>() {
                    existing_pop.popdown();
                }
            }

            let header_w = col_header.width().max(1);
            let header_h = col_header.height().max(1);
            let (pos_type, point_rect) = if let Some(root) = self.root().and_downcast::<gtk::Window>() {
                let root_w = root.width() as f64;
                let (hx, _hy) = col_header
                    .compute_point(&root, &gtk::graphene::Point::new(0.0, 0.0))
                    .map(|p| (p.x() as f64, p.y() as f64))
                    .unwrap_or((0.0, 0.0));
                let right_space = root_w - (hx + header_w as f64);
                let left_space = hx;
                if right_space >= 240.0 {
                    (
                        gtk::PositionType::Right,
                        gdk::Rectangle::new((header_w - 2).max(0), header_h / 2, 1, 1),
                    )
                } else if left_space >= 200.0 {
                    (
                        gtk::PositionType::Left,
                        gdk::Rectangle::new(2, header_h / 2, 1, 1),
                    )
                } else {
                    (
                        gtk::PositionType::Bottom,
                        gdk::Rectangle::new(header_w / 2, header_h, 1, 1),
                    )
                }
            } else {
                (
                    gtk::PositionType::Right,
                    gdk::Rectangle::new((header_w - 2).max(0), header_h / 2, 1, 1),
                )
            };

            let pop_box = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .spacing(6)
                .width_request(320)
                .vexpand(false)
                .build();

            let title_row = gtk::Box::builder()
                .orientation(gtk::Orientation::Horizontal)
                .spacing(6)
                .margin_start(10)
                .margin_end(10)
                .margin_top(6)
                .build();
            let back_btn = gtk::Button::builder()
                .icon_name("go-previous-symbolic")
                .tooltip_text(gettext("Back"))
                .css_classes(["flat", "circular"])
                .valign(gtk::Align::Center)
                .build();
            let title_lbl = gtk::Label::builder()
                .label(&dialog_title)
                .xalign(0.0)
                .hexpand(true)
                .css_classes(["heading"])
                .build();
            title_row.append(&back_btn);
            title_row.append(&title_lbl);
            pop_box.append(&title_row);

            scrolled.set_vexpand(false);
            scrolled.set_propagate_natural_height(true);
            scrolled.set_max_content_height(660);
            pop_box.append(&scrolled);

            let popover = gtk::Popover::builder()
                .has_arrow(true)
                .autohide(true)
                .position(pos_type)
                .pointing_to(&point_rect)
                .child(&pop_box)
                .build();
            popover.set_parent(&col_header);

            let pop_for_back = popover.clone();
            let page_for_back = page_weak.clone();
            let header_for_back = col_header.clone();
            back_btn.connect_clicked(move |_| {
                pop_for_back.popdown();
                let page_w = page_for_back.clone();
                let hdr = header_for_back.clone();
                glib::idle_add_local_once(move || {
                    if let Some(page) = page_w.upgrade() {
                        page.show_mail_header_context_menu(
                            &hdr,
                            (hdr.width().max(1) / 2) as f64,
                            (hdr.height().max(1) / 2) as f64,
                        );
                    }
                });
            });

            popover.connect_closed(move |popover| {
                let popover = popover.clone();
                glib::idle_add_local_once(move || {
                    popover.unparent();
                });
            });
            popover.popup();
            return;
        }

        toolbar.set_content(Some(&scrolled));
        dialog.set_content(Some(&toolbar));
        dialog.present();
    }

    fn show_mail_header_context_menu(&self, header: &gtk::Box, x: f64, y: f64) {
        header.set_vexpand(false);
        header.set_vexpand_set(true);

        // Close any previously open popover attached to the header
        let mut child = header.first_child();
        while let Some(w) = child {
            child = w.next_sibling();
            if let Ok(existing_pop) = w.downcast::<gtk::Popover>() {
                existing_pop.popdown();
            }
        }

        // Position the popover to the side of the table header (over the preview pane on the right,
        // or over the folder sidebar on the left when preview is bottom/off) so the entire message
        // table (headers + rows) remains completely visible while configuring columns.
        let header_w = header.width().max(1);
        let header_h = header.height().max(1);
        let (pos_type, point_rect) = if let Some(root) = self.root().and_downcast::<gtk::Window>() {
            let root_w = root.width() as f64;
            let (hx, _hy) = header
                .compute_point(&root, &gtk::graphene::Point::new(0.0, 0.0))
                .map(|p| (p.x() as f64, p.y() as f64))
                .unwrap_or((0.0, 0.0));
            let right_space = root_w - (hx + header_w as f64);
            let left_space = hx;
            if right_space >= 240.0 {
                (
                    gtk::PositionType::Right,
                    gdk::Rectangle::new((header_w - 2).max(0), header_h / 2, 1, 1),
                )
            } else if left_space >= 200.0 {
                (
                    gtk::PositionType::Left,
                    gdk::Rectangle::new(2, header_h / 2, 1, 1),
                )
            } else {
                (
                    gtk::PositionType::Bottom,
                    gdk::Rectangle::new(x as i32, y as i32, 1, 1),
                )
            }
        } else {
            (
                gtk::PositionType::Right,
                gdk::Rectangle::new((header_w - 2).max(0), header_h / 2, 1, 1),
            )
        };

        let popover = gtk::Popover::builder()
            .has_arrow(true)
            .autohide(true)
            .position(pos_type)
            .pointing_to(&point_rect)
            .build();
        popover.add_css_class("menu");
        popover.add_css_class("context-menu");
        popover.set_parent(header);

        let content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(2)
            .margin_start(4)
            .margin_end(4)
            .margin_top(4)
            .margin_bottom(4)
            .build();

        let title = gtk::Label::builder()
            .label(gettext("Columns"))
            .halign(gtk::Align::Start)
            .css_classes(["heading"])
            .build();
        content.append(&title);

        let settings = AppSettings::try_new();

        let column_toggles: [(&'static str, String); 10] = [
            ("mail-show-status", gettext("Status")),
            ("mail-show-attachment", gettext("Attachments")),
            ("mail-show-flagged", gettext("Star")),
            ("mail-show-follow-up", gettext("Follow-up")),
            ("mail-show-memo-column", gettext("Memo")),
            ("mail-show-sender", gettext("Sender")),
            ("mail-show-recipient", gettext("Recipient")),
            ("mail-show-date", gettext("Date")),
            ("mail-show-size", gettext("Size")),
            ("mail-show-avatar", gettext("Avatar")),
        ];

        let content_toggles: [(&'static str, String); 4] = [
            ("mail-show-preview-text", gettext("Preview text")),
            ("mail-show-labels", gettext("Labels")),
            ("mail-show-memo-indicator", gettext("Memos")),
            ("mail-show-recipient-address", gettext("Recipient address")),
        ];

        let page_weak = self.downgrade();
        let all_checks: Rc<RefCell<Vec<(&'static str, gtk::CheckButton)>>> =
            Rc::new(RefCell::new(Vec::new()));
        let recipient_addr_check_slot: Rc<RefCell<Option<gtk::CheckButton>>> =
            Rc::new(RefCell::new(None));
        let initial_table_avatar = self.mail_show_table_avatar();
        let initial_table_memo_col = self.mail_show_table_memo_column();
        let initial_memo_indicator = self.mail_show_memo_indicator();
        let initial_show_recipient = settings
            .as_ref()
            .map(|s| s.mail_show_recipient())
            .unwrap_or(false);

        let make_toggle_check = |key: &'static str, label: &str| -> gtk::CheckButton {
            let active = if key == "mail-show-avatar" {
                initial_table_avatar
            } else if key == "mail-show-memo-column" {
                initial_table_memo_col
            } else if key == "mail-show-memo-indicator" {
                initial_memo_indicator
            } else if let Some(ref s) = settings {
                match key {
                    "mail-show-status" => s.mail_show_status(),
                    "mail-show-flagged" => s.mail_show_flagged(),
                    "mail-show-follow-up" => s.mail_show_follow_up(),
                    "mail-show-sender" => s.mail_show_sender(),
                    "mail-show-recipient" => s.mail_show_recipient(),
                    "mail-show-date" => s.mail_show_date(),
                    "mail-show-attachment" => s.mail_show_attachment(),
                    "mail-show-preview-text" => s.mail_show_preview_text(),
                    "mail-show-labels" => s.mail_show_labels(),
                    "mail-show-recipient-address" => s.mail_show_recipient_address(),
                    "mail-show-size" => s.mail_show_size(),
                    _ => false,
                }
            } else {
                false
            };

            let check = gtk::CheckButton::builder()
                .label(label)
                .active(active)
                .build();
            match key {
                "mail-show-preview-text" => {
                    check.set_tooltip_text(Some(&gettext(
                        "Show a short message preview inline after the subject",
                    )));
                }
                "mail-show-labels" => {
                    check.set_tooltip_text(Some(&gettext(
                        "Show colored tags/categories (e.g. [Work], [Important]) next to the subject",
                    )));
                }
                "mail-show-memo-column" => {
                    check.set_tooltip_text(Some(&gettext(
                        "Show a dedicated Memo column in the message table",
                    )));
                }
                "mail-show-memo-indicator" => {
                    check.set_tooltip_text(Some(&gettext(
                        "Show the memo note indicator inline before the subject",
                    )));
                }
                "mail-show-recipient-address" => {
                    check.set_tooltip_text(Some(&gettext(
                        "Show full email address in the Recipient column",
                    )));
                    // Only show the Recipient address detail toggle when the Recipient column is visible
                    check.set_visible(initial_show_recipient);
                }
                _ => {}
            }
            if key == "mail-show-recipient-address" {
                *recipient_addr_check_slot.borrow_mut() = Some(check.clone());
            }
            let key_str = key;
            let settings_cloned = settings.clone();
            let page_for_chk = page_weak.clone();
            let recipient_addr_slot_for_toggle = Rc::clone(&recipient_addr_check_slot);
            check.connect_toggled(move |btn| {
                if key_str == "mail-show-avatar" {
                    if let Some(page) = page_for_chk.upgrade() {
                        page.set_mail_show_table_avatar(btn.is_active());
                        page.refresh_sender_avatars();
                        page.rebuild_mail_column_layout();
                    }
                    return;
                }
                if key_str == "mail-show-memo-column" {
                    if let Some(page) = page_for_chk.upgrade() {
                        page.set_mail_show_table_memo_column(btn.is_active());
                        page.rebuild_mail_column_layout();
                    }
                    return;
                }
                if key_str == "mail-show-memo-indicator" {
                    if let Some(page) = page_for_chk.upgrade() {
                        page.set_mail_show_memo_indicator(btn.is_active());
                        page.rebuild_mail_column_layout();
                    }
                    return;
                }
                if let Some(ref s) = settings_cloned {
                    match key_str {
                        "mail-show-status" => s.set_mail_show_status(btn.is_active()),
                        "mail-show-flagged" => s.set_mail_show_flagged(btn.is_active()),
                        "mail-show-follow-up" => s.set_mail_show_follow_up(btn.is_active()),
                        "mail-show-sender" => s.set_mail_show_sender(btn.is_active()),
                        "mail-show-recipient" => s.set_mail_show_recipient(btn.is_active()),
                        "mail-show-date" => s.set_mail_show_date(btn.is_active()),
                        "mail-show-attachment" => s.set_mail_show_attachment(btn.is_active()),
                        "mail-show-preview-text" => s.set_mail_show_preview_text(btn.is_active()),
                        "mail-show-labels" => s.set_mail_show_labels(btn.is_active()),
                        "mail-show-recipient-address" => {
                            s.set_mail_show_recipient_address(btn.is_active())
                        }
                        "mail-show-size" => s.set_mail_show_size(btn.is_active()),
                        _ => {}
                    }
                }
                if key_str == "mail-show-recipient" {
                    if let Some(addr_chk) = recipient_addr_slot_for_toggle.borrow().as_ref() {
                        addr_chk.set_visible(btn.is_active());
                    }
                }
                if let Some(page) = page_for_chk.upgrade() {
                    page.rebuild_mail_column_layout();
                }
            });
            all_checks.borrow_mut().push((key, check.clone()));
            check
        };

        let col_grid = gtk::Grid::builder()
            .column_spacing(12)
            .row_spacing(2)
            .build();
        for (idx, (key, label)) in column_toggles.iter().enumerate() {
            let chk = make_toggle_check(key, label);
            col_grid.attach(&chk, (idx % 2) as i32, (idx / 2) as i32, 1, 1);
        }
        content.append(&col_grid);

        content.append(&crate::views::create_context_menu_separator());

        let content_section_title = gtk::Label::builder()
            .label(gettext("Details"))
            .halign(gtk::Align::Start)
            .margin_top(4)
            .css_classes(["heading"])
            .build();
        content.append(&content_section_title);

        for (key, label) in &content_toggles {
            let chk = make_toggle_check(key, label);
            content.append(&chk);
        }

        content.append(&crate::views::create_context_menu_separator());

        let make_popover_action_button = |icon_name: &str, label_text: &str| -> gtk::Button {
            let btn = gtk::Button::builder()
                .has_frame(false)
                .halign(gtk::Align::Fill)
                .css_classes(["flat", "context-menu-item"])
                .build();
            let row = gtk::Box::builder()
                .orientation(gtk::Orientation::Horizontal)
                .spacing(8)
                .margin_start(4)
                .margin_end(4)
                .margin_top(2)
                .margin_bottom(2)
                .valign(gtk::Align::Center)
                .build();
            let img = gtk::Image::builder()
                .icon_name(icon_name)
                .pixel_size(16)
                .valign(gtk::Align::Center)
                .css_classes(["dim-label"])
                .build();
            let lbl = gtk::Label::builder()
                .label(label_text)
                .xalign(0.0)
                .hexpand(true)
                .valign(gtk::Align::Center)
                .build();
            row.append(&img);
            row.append(&lbl);
            btn.set_child(Some(&row));
            btn
        };

        let sort_reverse_btn = make_popover_action_button("view-sort-descending-symbolic", &gettext("Reverse sort order"));
        let page_for_sort = page_weak.clone();
        sort_reverse_btn.connect_clicked(move |_| {
            if let Some(page) = page_for_sort.upgrade() {
                let current_field = page.imp().mail_sort_field.get();
                page.set_mail_sort_from_header(current_field);
            }
        });
        content.append(&sort_reverse_btn);

        let sort_reset_btn = make_popover_action_button("edit-undo-symbolic", &gettext("Reset sort order"));
        let page_for_reset = page_weak.clone();
        sort_reset_btn.connect_clicked(move |_| {
            if let Some(page) = page_for_reset.upgrade() {
                page.reset_mail_sort_to_default();
            }
        });
        content.append(&sort_reset_btn);

        let reorder_icon_name = themed_icon_name(&popover, "view-column-symbolic", "view-list-symbolic");
        let reorder_btn = make_popover_action_button(&reorder_icon_name, &gettext("Customize column order…"));
        let page_for_reorder = page_weak.clone();
        let popover_for_reorder = popover.clone();
        reorder_btn.connect_clicked(move |_| {
            popover_for_reorder.popdown();
            if let Some(page) = page_for_reorder.upgrade() {
                page.open_mail_column_order_dialog();
            }
        });
        content.append(&reorder_btn);

        let reset_btn = make_popover_action_button("edit-undo-symbolic", &gettext("Restore default columns"));
        let page_for_reset = page_weak.clone();
        let settings_for_reset = settings.clone();
        let checks_for_reset = Rc::clone(&all_checks);
        let recipient_addr_slot_for_reset = Rc::clone(&recipient_addr_check_slot);
        reset_btn.connect_clicked(move |_| {
            if let Some(page) = page_for_reset.upgrade() {
                page.set_mail_show_table_avatar(false);
                page.set_mail_show_table_memo_column(false);
                page.set_mail_show_memo_indicator(true);
            }
            if let Some(ref s) = settings_for_reset {
                let current_profile = s.mail_list_view_profile();
                let target_profile = if current_profile == "cards" || current_profile == "wide" {
                    "cards"
                } else {
                    "messages"
                };
                // Preserve global mail_show_avatar when resetting table columns
                let global_avatar = s.mail_show_avatar();
                s.apply_mail_list_view_profile(target_profile);
                if s.mail_show_avatar() != global_avatar {
                    s.set_mail_show_avatar(global_avatar);
                }
                s.set_mail_sender_column_width(180);
                s.set_mail_recipient_column_width(180);
                s.set_mail_date_column_width(MAIL_DATE_COLUMN_WIDTH);
                if let Some(addr_chk) = recipient_addr_slot_for_reset.borrow().as_ref() {
                    addr_chk.set_visible(s.mail_show_recipient());
                }
                for (key, chk) in checks_for_reset.borrow().iter() {
                    let active = match *key {
                        "mail-show-status" => s.mail_show_status(),
                        "mail-show-flagged" => s.mail_show_flagged(),
                        "mail-show-follow-up" => s.mail_show_follow_up(),
                        "mail-show-sender" => s.mail_show_sender(),
                        "mail-show-recipient" => s.mail_show_recipient(),
                        "mail-show-date" => s.mail_show_date(),
                        "mail-show-attachment" => s.mail_show_attachment(),
                        "mail-show-preview-text" => s.mail_show_preview_text(),
                        "mail-show-avatar" => false,
                        "mail-show-memo-column" => false,
                        "mail-show-memo-indicator" => true,
                        "mail-show-labels" => s.mail_show_labels(),
                        "mail-show-recipient-address" => s.mail_show_recipient_address(),
                        "mail-show-size" => s.mail_show_size(),
                        _ => chk.is_active(),
                    };
                    if chk.is_active() != active {
                        chk.set_active(active);
                    }
                }
            }
            if let Some(page) = page_for_reset.upgrade() {
                page.imp().mail_size_width.set(MAIL_SIZE_COLUMN_WIDTH);
                page.apply_mail_column_widths(180, 180, MAIL_DATE_COLUMN_WIDTH);
                page.rebuild_mail_column_layout();
            }
        });
        content.append(&reset_btn);

        popover.connect_closed(move |popover| {
            let popover = popover.clone();
            glib::idle_add_local_once(move || {
                popover.unparent();
            });
        });

        popover.set_child(Some(&content));
        popover.popup();
    }

    fn cell_label(cell: &gtk::Widget) -> Option<gtk::Label> {
        if let Some(lbl) = cell.downcast_ref::<gtk::Label>() {
            Some(lbl.clone())
        } else if let Some(bx) = cell.downcast_ref::<gtk::Box>() {
            bx.first_child().and_downcast::<gtk::Label>()
        } else {
            None
        }
    }

    fn load_persisted_table_avatar_visible() -> bool {
        let mut path = glib::user_config_dir();
        path.push("meridian");
        path.push("mail_table_avatar_column");
        std::fs::read_to_string(path)
            .ok()
            .map(|s| s.trim() == "1" || s.trim().eq_ignore_ascii_case("true"))
            .unwrap_or(false)
    }

    fn save_persisted_table_avatar_visible(visible: bool) {
        let mut dir = glib::user_config_dir();
        dir.push("meridian");
        let _ = std::fs::create_dir_all(&dir);
        dir.push("mail_table_avatar_column");
        let _ = std::fs::write(dir, if visible { "1" } else { "0" });
    }

