    fn refresh_mail_column_header(&self) {
        let Some(header) = self.imp().mail_column_header.borrow().as_ref().cloned() else {
            return;
        };
        let settings = AppSettings::try_new();
        let show_avatar = self.mail_show_table_avatar();
        let profile = settings
            .as_ref()
            .map(AppSettings::mail_list_view_profile)
            .unwrap_or_else(|| "messages".to_string());
        let order = settings
            .as_ref()
            .map(AppSettings::mail_list_column_order)
            .unwrap_or_else(|| {
                crate::services::settings_service::MAIL_LIST_COLUMN_IDS
                    .iter()
                    .map(|column| (*column).to_string())
                    .collect()
            });
        let wide_messages = mail_list_uses_wide_messages(&profile, &order);
        let show_status = settings
            .as_ref()
            .map(AppSettings::mail_show_status)
            .unwrap_or(true);
        let show_sender = settings
            .as_ref()
            .map(AppSettings::mail_show_sender)
            .unwrap_or(true);
        let show_recipient = settings
            .as_ref()
            .map(AppSettings::mail_show_recipient)
            .unwrap_or(false);
        let show_date = settings
            .as_ref()
            .map(AppSettings::mail_show_date)
            .unwrap_or(true);
        let show_attachment = settings
            .as_ref()
            .map(AppSettings::mail_show_attachment)
            .unwrap_or(true);
        let show_flagged = settings
            .as_ref()
            .map(AppSettings::mail_show_flagged)
            .unwrap_or(false);
        let show_follow_up = settings
            .as_ref()
            .map(AppSettings::mail_show_follow_up)
            .unwrap_or(true);
        let show_size = settings
            .as_ref()
            .map(AppSettings::mail_show_size)
            .unwrap_or(false);
        let sender_width = settings
            .as_ref()
            .map(AppSettings::mail_sender_column_width)
            .unwrap_or(180);
        let recipient_width = settings
            .as_ref()
            .map(AppSettings::mail_recipient_column_width)
            .unwrap_or(180);

        if let Some(avatar) = Self::mail_column_child(&header, "avatar") {
            avatar.set_visible(
                mail_list_profile_allows_column(&profile, wide_messages, "avatar") && show_avatar,
            );
        }
        if let Some(attachment) = Self::mail_column_child(&header, "attachment") {
            attachment.set_visible(
                mail_list_profile_allows_column(&profile, wide_messages, "attachment")
                    && show_attachment,
            );
            if let Some(lbl) = Self::cell_label(&attachment) {
                lbl.set_label(&self.mail_header_sort_label("📎", MailSortField::Attachments));
            }
        }
        if let Some(status) = Self::mail_column_child(&header, "status") {
            status.set_visible(
                mail_list_profile_allows_column(&profile, wide_messages, "status") && show_status,
            );
            if let Some(lbl) = Self::cell_label(&status) {
                lbl.set_label(&self.mail_header_sort_label("●", MailSortField::Unread));
            }
        }
        if let Some(follow_up) = Self::mail_column_child(&header, "follow-up") {
            follow_up.set_visible(
                mail_list_profile_allows_column(&profile, wide_messages, "follow-up")
                    && show_follow_up,
            );
            if let Some(lbl) = Self::cell_label(&follow_up) {
                lbl.set_label(&self.mail_header_sort_label("⚑", MailSortField::FollowUp));
            }
        }
        if let Some(memo) = Self::mail_column_child(&header, "memo") {
            memo.set_visible(
                mail_list_profile_allows_column(&profile, wide_messages, "memo")
                    && self.mail_show_table_memo_column(),
            );
        }
        if let Some(star) = Self::mail_column_child(&header, "flagged") {
            star.set_visible(
                mail_list_profile_allows_column(&profile, wide_messages, "flagged") && show_flagged,
            );
            if let Some(lbl) = Self::cell_label(&star) {
                lbl.set_label(&self.mail_header_sort_label("★", MailSortField::Flagged));
            }
        }
        if let Some(important) = Self::mail_column_child(&header, "important") {
            important.set_visible(false);
            if let Some(lbl) = Self::cell_label(&important) {
                lbl.set_label(&self.mail_header_sort_label("!", MailSortField::Important));
            }
        }
        if let Some(sender_column) = Self::mail_column_child(&header, "sender") {
            let visible = (mail_list_profile_allows_column(&profile, wide_messages, "sender") || show_sender)
                && show_sender && !wide_messages;
            sender_column.set_visible(visible);
            sender_column.set_width_request(sender_width);
            if let Some(sep) = self.imp().sender_separator.borrow().as_ref() {
                sep.set_visible(visible);
            }
            if let Some(sender_label) = Self::cell_label(&sender_column) {
                sender_label.set_label(&self.mail_header_sort_label(&gettext("From"), MailSortField::Sender));
            }
        }
        if let Some(recipient_column) = Self::mail_column_child(&header, "recipient") {
            let visible = (mail_list_profile_allows_column(&profile, wide_messages, "recipient") || show_recipient)
                && show_recipient && !wide_messages;
            recipient_column.set_visible(visible);
            recipient_column.set_width_request(recipient_width);
            if let Some(sep) = self.imp().recipient_separator.borrow().as_ref() {
                sep.set_visible(visible);
            }
            if let Some(recipient_label) = Self::cell_label(&recipient_column) {
                recipient_label.set_label(&self.mail_header_sort_label(&gettext("To"), MailSortField::Recipient));
            }
        }
        if let Some(subject) = Self::mail_column_child(&header, "subject") {
            subject.set_visible(mail_list_profile_allows_column(
                &profile,
                wide_messages,
                "subject",
            ));
            if let Some(lbl) = Self::cell_label(&subject) {
                lbl.set_label(&self.mail_header_sort_label(&gettext("Subject"), MailSortField::Subject));
            }
        }
        if let Some(messages) = Self::mail_column_child(&header, "messages") {
            messages.set_visible(mail_list_profile_allows_column(
                &profile,
                wide_messages,
                "messages",
            ));
            if let Some(lbl) = Self::cell_label(&messages) {
                lbl.set_label(&gettext("Messages"));
            }
        }
        if let Some(preview) = Self::mail_column_child(&header, "preview") {
            preview.set_visible(false);
        }
        let date_width = settings
            .as_ref()
            .map(AppSettings::mail_date_column_width)
            .unwrap_or(MAIL_DATE_COLUMN_WIDTH);
        let size_width = self.imp().mail_size_width.get().clamp(48, 240);
        let date_visible =
            mail_list_profile_allows_column(&profile, wide_messages, "date") && show_date;
        let size_visible = (mail_list_profile_allows_column(&profile, wide_messages, "size") || show_size)
            && show_size
            && !wide_messages;
        let pos_date = order.iter().position(|c| c == "date").unwrap_or(usize::MAX);
        let pos_size = order.iter().position(|c| c == "size").unwrap_or(usize::MAX);
        let date_is_last = date_visible && (!size_visible || pos_date > pos_size);
        let size_is_last = size_visible && (!date_visible || pos_size > pos_date);
        if let Some(date) = Self::mail_column_child(&header, "date") {
            date.set_visible(date_visible);
            date.set_width_request(date_width);
            if date_is_last {
                date.add_css_class("last-header-cell");
            } else {
                date.remove_css_class("last-header-cell");
            }
            if let Some(lbl) = Self::cell_label(&date) {
                lbl.set_label(&self.mail_header_sort_label(&gettext("Date"), MailSortField::Date));
                let align_left = AppSettings::try_new()
                    .as_ref()
                    .map(|s| s.mail_date_align() == "left")
                    .unwrap_or(false);
                lbl.set_xalign(if align_left { 0.0 } else { 1.0 });
            }
        }
        if let Some(sep) = self.imp().date_separator.borrow().as_ref() {
            sep.set_visible(date_visible || size_visible);
        }
        if let Some(sep) = self.imp().size_separator.borrow().as_ref() {
            sep.set_visible(date_visible && size_visible);
        }
        if let Some(size) = Self::mail_column_child(&header, "size") {
            size.set_visible(size_visible);
            size.set_width_request(size_width);
            if size_is_last {
                size.add_css_class("last-header-cell");
            } else {
                size.remove_css_class("last-header-cell");
            }
            if let Some(lbl) = Self::cell_label(&size) {
                lbl.set_label(&self.mail_header_sort_label(&gettext("Size"), MailSortField::Size));
            }
        }
        if let Some(due) = Self::mail_column_child(&header, "follow-up-due") {
            due.set_visible(false);
        }
        if let Some(location) = Self::mail_column_child(&header, "location") {
            location.set_visible(false);
        }
        if let Some(canvas) = self.imp().mail_table_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
    }

    fn ensure_size_groups(&self) {
        let imp = self.imp();
        let indicator_group = imp
            .status_size_group
            .borrow()
            .clone()
            .unwrap_or_else(|| gtk::SizeGroup::new(gtk::SizeGroupMode::Horizontal));
        if imp.status_size_group.borrow().is_none() {
            imp.status_size_group.replace(Some(indicator_group.clone()));
        }
        if imp.attachment_size_group.borrow().is_none() {
            imp.attachment_size_group.replace(Some(indicator_group.clone()));
        }
        if imp.follow_up_size_group.borrow().is_none() {
            imp.follow_up_size_group.replace(Some(indicator_group.clone()));
        }
        if imp.memo_size_group.borrow().is_none() {
            imp.memo_size_group.replace(Some(indicator_group.clone()));
        }
        if imp.star_size_group.borrow().is_none() {
            imp.star_size_group.replace(Some(indicator_group.clone()));
        }
        if imp.important_size_group.borrow().is_none() {
            imp.important_size_group.replace(Some(indicator_group));
        }
        if imp.avatar_size_group.borrow().is_none() {
            imp.avatar_size_group
                .replace(Some(gtk::SizeGroup::new(gtk::SizeGroupMode::Horizontal)));
        }
        if imp.preview_size_group.borrow().is_none() {
            imp.preview_size_group
                .replace(Some(gtk::SizeGroup::new(gtk::SizeGroupMode::Horizontal)));
        }
    }

    fn update_row_widths_in_widget(
        widget: &gtk::Widget,
        sender_width: i32,
        recipient_width: i32,
        date_width: i32,
    ) {
        if widget.has_css_class("message-line") {
            if let Some(bx) = widget.downcast_ref::<gtk::Box>() {
                if let Some(header_box) = bx.first_child().and_downcast::<gtk::Box>() {
                    if let Some(sender_col) = Self::mail_column_child(&header_box, "sender") {
                        sender_col.set_width_request(sender_width);
                    }
                    if let Some(recipient_col) = Self::mail_column_child(&header_box, "recipient") {
                        recipient_col.set_width_request(recipient_width);
                    }
                    if let Some(date_col) = Self::mail_column_child(&header_box, "date") {
                        date_col.set_width_request(date_width);
                    }
                }
            }
            return;
        }
        let mut child = widget.first_child();
        while let Some(c) = child {
            let next = c.next_sibling();
            Self::update_row_widths_in_widget(&c, sender_width, recipient_width, date_width);
            child = next;
        }
    }

    pub(crate) fn is_mail_table_layout_cached_valid(
        &self,
        l: &PreparedMailTableLayout,
        canvas_width: f64,
        n_items: usize,
    ) -> bool {
        let sender_w = self.imp().mail_sender_width.get() as f64;
        let recipient_w = self.imp().mail_recipient_width.get() as f64;
        let date_w = self.imp().mail_date_width.get() as f64;
        let size_w = self.imp().mail_size_width.get().max(48) as f64;
        let settings = AppSettings::try_new();
        let show_recipient_address = settings
            .as_ref()
            .map(|s| s.mail_show_recipient_address())
            .unwrap_or(false);
        let profile = settings
            .as_ref()
            .map(|s| s.mail_list_view_profile())
            .unwrap_or_else(|| "messages".to_string());
        let is_cards_mode = self.imp().is_mobile.get() || profile == "cards" || profile == "wide";
        let expected_show_avatar = if is_cards_mode {
            settings.as_ref().map(|s| s.mail_show_avatar()).unwrap_or(true)
        } else {
            self.mail_show_table_avatar()
        };
        l.is_cards_mode == is_cards_mode
            && (l.width - canvas_width).abs() < 2.0
            && l.row_count() == n_items
            && (l.sender_width - sender_w).abs() < 0.5
            && (l.recipient_width - recipient_w).abs() < 0.5
            && (l.date_width - date_w).abs() < 0.5
            && (l.size_width - size_w).abs() < 0.5
            && l.show_recipient_address == show_recipient_address
            && l.show_avatar == expected_show_avatar
            && l.show_memo == self.mail_show_table_memo_column()
            && l.show_memo_indicator == self.mail_show_memo_indicator()
    }

    fn sync_mail_column_header_widths(&self, geom: &TableColumnsGeometry) {
        if let Some(header) = self.imp().mail_column_header.borrow().as_ref() {
            if let Some(sender_col) = Self::mail_column_child(header, "sender") {
                sender_col.set_width_request(geom.sender.width.round() as i32);
            }
            if let Some(recipient_col) = Self::mail_column_child(header, "recipient") {
                recipient_col.set_width_request(geom.recipient.width.round() as i32);
            }
            if let Some(date_col) = Self::mail_column_child(header, "date") {
                date_col.set_width_request(geom.date.width.round() as i32);
            }
            if let Some(size_col) = Self::mail_column_child(header, "size") {
                size_col.set_width_request(geom.size.width.round() as i32);
            }
        }
    }

    pub(crate) fn apply_mail_column_widths(
        &self,
        sender_width: i32,
        recipient_width: i32,
        date_width: i32,
    ) {
        let size_width = self.imp().mail_size_width.get().clamp(48, 240);
        self.apply_mail_column_widths_with_size(
            sender_width,
            recipient_width,
            date_width,
            size_width,
        );
    }

    pub(crate) fn apply_mail_column_widths_with_size(
        &self,
        sender_width: i32,
        recipient_width: i32,
        date_width: i32,
        size_width: i32,
    ) {
        self.imp().mail_sender_width.set(sender_width);
        self.imp().mail_recipient_width.set(recipient_width);
        self.imp().mail_date_width.set(date_width);
        self.imp().mail_size_width.set(size_width);

        if let Some(header) = self.imp().mail_column_header.borrow().as_ref() {
            if let Some(sender_col) = Self::mail_column_child(header, "sender") {
                sender_col.set_width_request(sender_width);
            }
            if let Some(recipient_col) = Self::mail_column_child(header, "recipient") {
                recipient_col.set_width_request(recipient_width);
            }
            if let Some(date_col) = Self::mail_column_child(header, "date") {
                date_col.set_width_request(date_width);
            }
            if let Some(size_col) = Self::mail_column_child(header, "size") {
                size_col.set_width_request(size_width);
            }
        }

        if let Some(list_view) = self.imp().mail_list_view.borrow().as_ref() {
            let mut child = list_view.first_child();
            while let Some(row_widget) = child {
                let next = row_widget.next_sibling();
                Self::update_row_widths_in_widget(
                    &row_widget,
                    sender_width,
                    recipient_width,
                    date_width,
                );
                child = next;
            }
        }

        let cached_layout = self.imp().mail_table_layout.borrow().clone();
        if let Some(layout_rc) = cached_layout {
            let mut updated = (*layout_rc).clone();
            let order = AppSettings::try_new()
                .map(|s| s.mail_list_column_order())
                .unwrap_or_else(|| {
                    crate::services::settings_service::MAIL_LIST_COLUMN_IDS
                        .iter()
                        .map(|c| (*c).to_string())
                        .collect()
                });
            updated.update_column_widths_with_size(
                &order,
                sender_width as f64,
                recipient_width as f64,
                date_width as f64,
                size_width as f64,
            );
            self.imp().mail_table_layout.replace(Some(Rc::new(updated)));
        } else {
            self.imp().mail_table_layout.replace(None);
        }

        if let Some(canvas) = self.imp().mail_table_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
    }

    pub(crate) fn mail_table_row_height(&self) -> f64 {
        let profile = AppSettings::try_new()
            .map(|s| s.mail_list_view_profile())
            .unwrap_or_else(|| "messages".to_string());
        let is_cards_mode = self.imp().is_mobile.get() || profile == "cards" || profile == "wide";
        if let Some(layout) = self.imp().mail_table_layout.borrow().as_ref() {
            if layout.is_cards_mode == is_cards_mode {
                return layout.row_height;
            }
        }
        if is_cards_mode {
            return 76.0;
        }
        let settings = AppSettings::try_new();
        let (desktop_size_pt, text_scaling) = if gio::SettingsSchemaSource::default()
            .and_then(|s| s.lookup("org.gnome.desktop.interface", true))
            .is_some()
        {
            let s = gio::Settings::new("org.gnome.desktop.interface");
            let font_name = s.string("font-name");
            let scaling = s.double("text-scaling-factor").clamp(0.75, 3.0);
            let parsed_sz = if let Some(idx) = font_name.rfind(' ') {
                let (_, sz) = font_name.split_at(idx);
                sz.trim().parse::<f64>().unwrap_or(11.0)
            } else {
                11.0
            };
            (parsed_sz, scaling)
        } else {
            (11.0, 1.0)
        };

        let user_font_size = settings
            .as_ref()
            .map(|s| s.mail_font_size())
            .unwrap_or(16) as f64;
        let size_factor = if user_font_size > 0.0 && (user_font_size - 16.0).abs() > 0.5 {
            (user_font_size / 16.0).clamp(0.75, 2.0)
        } else {
            1.0
        };
        let font_size = (desktop_size_pt * text_scaling * size_factor).clamp(10.0, 32.0);

        let density = settings
            .as_ref()
            .map(|s| s.mail_row_density())
            .unwrap_or_else(|| "compact".to_string());
        match density.as_str() {
            "spacious" => (font_size * 2.7).clamp(38.0, 54.0),
            "comfortable" => (font_size * 2.4).clamp(33.0, 46.0),
            _ => (font_size * 2.25).clamp(31.0, 38.0),
        }
    }

    pub(crate) fn current_mail_table_layout(
        &self,
        selection: &gtk::MultiSelection,
        canvas_width: f64,
    ) -> PreparedMailTableLayout {
        let settings = AppSettings::try_new();
        let (desktop_family, desktop_size_pt, text_scaling) = if gio::SettingsSchemaSource::default()
            .and_then(|s| s.lookup("org.gnome.desktop.interface", true))
            .is_some()
        {
            let s = gio::Settings::new("org.gnome.desktop.interface");
            let font_name = s.string("font-name");
            let scaling = s.double("text-scaling-factor").clamp(0.75, 3.0);
            let (family, size_pt) = if let Some(idx) = font_name.rfind(' ') {
                let (fam, sz) = font_name.split_at(idx);
                let parsed_sz = sz.trim().parse::<f64>().unwrap_or(11.0);
                (fam.trim().to_string(), parsed_sz)
            } else {
                (font_name.trim().to_string(), 11.0)
            };
            (family, size_pt, scaling)
        } else {
            ("Adwaita Sans".to_string(), 11.0, 1.0)
        };

        let configured_family = settings
            .as_ref()
            .map(|s| s.mail_font_family())
            .unwrap_or_default();
        let font_family = if configured_family.is_empty()
            || configured_family == "system-ui, sans-serif"
            || configured_family.contains("sans-serif")
        {
            format!("{}, Adwaita Sans, Cantarell, sans-serif", desktop_family)
        } else {
            format!("{}, {}, Adwaita Sans, Cantarell, sans-serif", configured_family, desktop_family)
        };

        let user_font_size = settings
            .as_ref()
            .map(|s| s.mail_font_size())
            .unwrap_or(16) as f64;
        let size_factor = if user_font_size > 0.0 && (user_font_size - 16.0).abs() > 0.5 {
            (user_font_size / 16.0).clamp(0.75, 2.0)
        } else {
            1.0
        };
        let font_size = (desktop_size_pt * text_scaling * size_factor).clamp(10.0, 32.0);

        let profile = settings
            .as_ref()
            .map(|s| s.mail_list_view_profile())
            .unwrap_or_else(|| "messages".to_string());
        let is_cards_mode = self.imp().is_mobile.get() || profile == "cards" || profile == "wide";
        let row_height = if is_cards_mode { 76.0 } else { self.mail_table_row_height() };
        let order = settings
            .as_ref()
            .map(|s| s.mail_list_column_order())
            .unwrap_or_else(|| {
                crate::services::settings_service::MAIL_LIST_COLUMN_IDS
                    .iter()
                    .map(|c| (*c).to_string())
                    .collect()
            });
        let wide_messages = mail_list_uses_wide_messages(&profile, &order);

        let show_status = mail_list_profile_allows_column(&profile, wide_messages, "status")
            && settings.as_ref().map(|s| s.mail_show_status()).unwrap_or(true);

        let show_attachment = mail_list_profile_allows_column(&profile, wide_messages, "attachment")
            && settings.as_ref().map(|s| s.mail_show_attachment()).unwrap_or(true);

        let show_flagged = mail_list_profile_allows_column(&profile, wide_messages, "flagged")
            && settings.as_ref().map(|s| s.mail_show_flagged()).unwrap_or(true);

        let show_follow_up = mail_list_profile_allows_column(&profile, wide_messages, "follow-up")
            && settings.as_ref().map(|s| s.mail_show_follow_up()).unwrap_or(true);

        let show_memo = mail_list_profile_allows_column(&profile, wide_messages, "memo")
            && self.mail_show_table_memo_column();

        let show_memo_indicator = self.mail_show_memo_indicator();

        let show_sender = (mail_list_profile_allows_column(&profile, wide_messages, "sender")
            || settings.as_ref().map(|s| s.mail_show_sender()).unwrap_or(true))
            && settings.as_ref().map(|s| s.mail_show_sender()).unwrap_or(true)
            && !wide_messages;

        let show_recipient = (mail_list_profile_allows_column(&profile, wide_messages, "recipient")
            || settings.as_ref().map(|s| s.mail_show_recipient()).unwrap_or(false))
            && settings.as_ref().map(|s| s.mail_show_recipient()).unwrap_or(false)
            && !wide_messages;

        let show_date = mail_list_profile_allows_column(&profile, wide_messages, "date")
            && settings.as_ref().map(|s| s.mail_show_date()).unwrap_or(true);

        let show_size = (mail_list_profile_allows_column(&profile, wide_messages, "size")
            || settings.as_ref().map(|s| s.mail_show_size()).unwrap_or(false))
            && settings.as_ref().map(|s| s.mail_show_size()).unwrap_or(false)
            && !wide_messages;

        let show_avatar = if is_cards_mode {
            settings
                .as_ref()
                .map(|s| s.mail_show_avatar())
                .unwrap_or(true)
        } else {
            self.mail_show_table_avatar()
        };

        let show_labels = settings
            .as_ref()
            .map(|s| s.mail_show_labels())
            .unwrap_or(true);

        let show_preview_text = settings
            .as_ref()
            .map(|s| s.mail_show_preview_text())
            .unwrap_or(true);

        let show_recipient_address = settings
            .as_ref()
            .map(|s| s.mail_show_recipient_address())
            .unwrap_or(false);

        let sender_width = self.imp().mail_sender_width.get() as f64;
        let recipient_width = self.imp().mail_recipient_width.get() as f64;
        let date_width = self.imp().mail_date_width.get() as f64;

        let date_format = settings
            .as_ref()
            .map(|s| s.mail_date_format())
            .unwrap_or_else(|| "standard".to_string());
        let date_custom_format = settings
            .as_ref()
            .map(|s| s.mail_date_custom_format())
            .unwrap_or_default();
        let time_format = settings
            .as_ref()
            .map(|s| s.time_format())
            .unwrap_or_else(|| "24h".to_string());
        let date_align = settings
            .as_ref()
            .map(|s| s.mail_date_align())
            .unwrap_or_else(|| "right".to_string());
        let date_align_left = date_align == "left";

        let now_date = chrono::Local::now().date_naive();
        let cache_key = format!("{date_format}:{date_custom_format}:{time_format}:{now_date}");

        let show_account_pip = false;

        let n = selection.n_items();
        let total_rows = n as usize;
        let eager_rows = total_rows <= 512;
        let mut rows = if eager_rows {
            Vec::with_capacity(total_rows)
        } else {
            Vec::new()
        };

        if eager_rows {
            for i in 0..n {
                if let Some(row) = self.build_prepared_mail_table_row(
                    selection,
                    i,
                    row_height,
                    &date_format,
                    &date_custom_format,
                    &time_format,
                    now_date,
                    &cache_key,
                    show_preview_text,
                    show_labels,
                    show_recipient_address,
                    show_account_pip,
                ) {
                    rows.push(row);
                }
            }
        }

        let effective_row_count = if eager_rows { rows.len() } else { total_rows };
        let height = (effective_row_count as f64 * row_height).max(40.0);
        let (
            primary_desc_normal,
            primary_desc_bold,
            secondary_desc,
            primary_text_offset,
            secondary_text_offset,
        ) = PreparedMailTableLayout::compute_font_metrics(&font_family, font_size, row_height);

        let sep_width = 1.0;
        let size_width = (self.imp().mail_size_width.get().clamp(48, 240)) as f64;

        let geom = compute_table_columns_geometry_with_memo(
            &order,
            canvas_width.max(120.0),
            show_status,
            show_attachment,
            show_flagged,
            show_follow_up,
            show_memo,
            show_avatar,
            show_sender,
            sender_width,
            show_recipient,
            recipient_width,
            show_date,
            date_width,
            show_size,
            size_width,
            sep_width,
        );

        self.sync_mail_column_header_widths(&geom);

        PreparedMailTableLayout {
            rows,
            total_rows: effective_row_count,
            virtual_rows: std::rc::Rc::new(std::cell::RefCell::new(
                std::collections::HashMap::with_capacity(if eager_rows { 0 } else { 128 }),
            )),
            width: canvas_width.max(120.0),
            height,
            row_height,
            sender_width: sender_width.max(60.0),
            recipient_width: recipient_width.max(0.0),
            date_width: date_width.max(60.0),
            size_width,
            sep_width,
            font_size,
            font_family,
            show_status,
            show_attachment,
            show_flagged,
            show_follow_up,
            show_memo,
            show_memo_indicator,
            show_sender,
            show_recipient,
            show_recipient_address,
            show_date,
            show_size,
            show_avatar,
            show_labels,
            show_preview_text,
            date_align_left,
            is_cards_mode,
            col_status: geom.status,
            col_attachment: geom.attachment,
            col_flagged: geom.flagged,
            col_follow_up: geom.follow_up,
            col_memo: geom.memo,
            col_avatar: geom.avatar,
            col_sender: geom.sender,
            col_recipient: geom.recipient,
            col_subject: geom.subject,
            col_date: geom.date,
            col_size: geom.size,
            primary_desc_normal,
            primary_desc_bold,
            secondary_desc,
            primary_text_offset,
            secondary_text_offset,
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn build_prepared_mail_table_row(
        &self,
        selection: &gtk::MultiSelection,
        i: u32,
        row_height: f64,
        date_format: &str,
        date_custom_format: &str,
        time_format: &str,
        now_date: NaiveDate,
        cache_key: &str,
        show_preview_text: bool,
        show_labels: bool,
        show_recipient_address: bool,
        show_account_pip: bool,
    ) -> Option<PreparedMailTableRow> {
        let item = selection.item(i)?;
        let (depth, is_expandable, is_expanded, message) =
            if let Some(tree_row) = item.downcast_ref::<gtk::TreeListRow>() {
                let depth = tree_row.depth() as usize;
                let expandable = tree_row.is_expandable();
                let expanded = tree_row.is_expanded();
                let msg = tree_row.item().and_downcast::<MailMessageObject>();
                (depth, expandable, expanded, msg)
            } else if let Ok(msg) = item.downcast::<MailMessageObject>() {
                (0, false, false, Some(msg))
            } else {
                return None;
            };

        let msg = message?;
        let selected = false;
        let is_collapsed_root = depth == 0 && is_expandable && !is_expanded;

        let (sender_str, raw_date_for_row, snippet_for_row, is_unread, is_flagged) = if is_collapsed_root {
            let members_guard = self.imp().thread_members.borrow();
            if let Some(members_map) = members_guard.as_ref() {
                let map_ref = members_map.borrow();
                if let Some(members) = map_ref.get(&msg.thread_id()) {
                    let participants = format_thread_participants(members, &msg.sender_name());
                    let newest = members
                        .iter()
                        .max_by_key(|m| m.timestamp_cached(parse_message_timestamp))
                        .unwrap_or(&msg);
                    let has_unread = members.iter().any(|m| m.is_unread());
                    let has_flagged = members.iter().any(|m| m.is_flagged());
                    (
                        participants,
                        newest.date_str(),
                        newest.preview_snippet(),
                        msg.is_unread() || has_unread,
                        msg.is_flagged() || has_flagged,
                    )
                } else {
                    (
                        msg.sender_name(),
                        msg.date_str(),
                        msg.preview_snippet(),
                        msg.is_unread(),
                        msg.is_flagged(),
                    )
                }
            } else {
                (
                    msg.sender_name(),
                    msg.date_str(),
                    msg.preview_snippet(),
                    msg.is_unread(),
                    msg.is_flagged(),
                )
            }
        } else {
            (
                msg.sender_name(),
                msg.date_str(),
                msg.preview_snippet(),
                msg.is_unread(),
                msg.is_flagged(),
            )
        };

        let size = msg.message_size();
        let size_str = if size > 0 {
            format_message_size(size)
        } else {
            String::new()
        };

        let date = if is_collapsed_root {
            format_mail_table_date_with_now(
                &raw_date_for_row,
                date_format,
                date_custom_format,
                time_format,
                now_date,
            )
        } else {
            msg.formatted_date_cached(cache_key, |raw| {
                format_mail_table_date_with_now(
                    raw,
                    date_format,
                    date_custom_format,
                    time_format,
                    now_date,
                )
            })
        };

        let subject = msg.subject();
        let snippet = snippet_for_row;
        let is_important = msg.is_important();
        let labels = msg.labels();
        let markup_dark = format_mail_table_subject_markup(
            &subject,
            &snippet,
            &labels,
            is_unread,
            show_preview_text,
            show_labels,
            true,
            is_important,
        );
        let markup_light = format_mail_table_subject_markup(
            &subject,
            &snippet,
            &labels,
            is_unread,
            show_preview_text,
            show_labels,
            false,
            is_important,
        );

        {
            let mids = self.imp().linked_memo_mids.borrow();
            if !mids.is_empty() {
                let mut has_linked = mids.contains(&Self::message_memo_link_uri(&msg));
                if !has_linked && is_collapsed_root {
                    if let Some(members_map) = self.imp().thread_members.borrow().as_ref() {
                        if let Some(members) = members_map.borrow().get(&msg.thread_id()) {
                            has_linked = members
                                .iter()
                                .any(|m| mids.contains(&Self::message_memo_link_uri(m)));
                        }
                    }
                }
                if has_linked {
                    self.imp().linked_memo_row_ids.borrow_mut().insert(msg.id());
                }
            }
        }

        Some(PreparedMailTableRow {
            model_index: i as usize,
            id: msg.id(),
            thread_id: msg.thread_id(),
            depth,
            is_expandable,
            is_expanded,
            is_unread,
            is_flagged,
            follow_up_state: msg.follow_up_state(),
            is_important,
            is_replied: msg.is_replied(),
            is_forwarded: msg.is_forwarded(),
            attachment_kind: msg.attachment_kind(),
            has_attachments: msg.attachment_count() > 0,
            sender: sender_str,
            sender_email: msg.sender_email(),
            recipient: {
                let to = msg.recipient_to();
                let cc = msg.recipient_cc();
                if !to.trim().is_empty() {
                    format_recipient_display(&to, show_recipient_address)
                } else if !cc.trim().is_empty() {
                    format!("Cc: {}", format_recipient_display(&cc, show_recipient_address))
                } else {
                    String::new()
                }
            },
            subject,
            snippet,
            date,
            size_str,
            selected,
            y: (i as f64) * row_height,
            height: row_height,
            markup_dark,
            markup_light,
            labels,
            thread_size: msg.thread_size(),
            account_color: if show_account_pip {
                account_color_for_message(&msg)
            } else {
                None
            },
        })
    }

    pub(crate) fn ensure_mail_table_layout_rows_range(
        &self,
        layout: &PreparedMailTableLayout,
        selection: &gtk::MultiSelection,
        start_row: usize,
        end_row: usize,
    ) {
        if !layout.rows.is_empty() || layout.total_rows == 0 {
            return;
        }
        let clamped_end = end_row.min(layout.total_rows);
        if start_row >= clamped_end {
            return;
        }
        let all_present = {
            let vrows = layout.virtual_rows.borrow();
            (start_row..clamped_end).all(|idx| vrows.contains_key(&idx))
        };
        if all_present {
            return;
        }

        let settings = AppSettings::try_new();
        let date_format = settings
            .as_ref()
            .map(|s| s.mail_date_format())
            .unwrap_or_else(|| "standard".to_string());
        let date_custom_format = settings
            .as_ref()
            .map(|s| s.mail_date_custom_format())
            .unwrap_or_default();
        let time_format = settings
            .as_ref()
            .map(|s| s.time_format())
            .unwrap_or_else(|| "24h".to_string());
        let now_date = chrono::Local::now().date_naive();
        let cache_key = format!("{date_format}:{date_custom_format}:{time_format}:{now_date}");

        let mut built = Vec::with_capacity(clamped_end - start_row);
        for idx in start_row..clamped_end {
            if layout.virtual_rows.borrow().contains_key(&idx) {
                continue;
            }
            if let Some(row) = self.build_prepared_mail_table_row(
                selection,
                idx as u32,
                layout.row_height,
                &date_format,
                &date_custom_format,
                &time_format,
                now_date,
                &cache_key,
                layout.show_preview_text,
                layout.show_labels,
                layout.show_recipient_address,
                false,
            ) {
                built.push((idx, row));
            }
        }

        let mut vrows = layout.virtual_rows.borrow_mut();
        if vrows.len() > 2048 {
            vrows.clear();
        }
        for (idx, row) in built {
            vrows.insert(idx, row);
        }
    }

    pub(crate) fn update_mail_table_canvas_layout(&self) {
        self.imp().mail_table_layout.replace(None);
        if let Some(canvas) = self.imp().mail_table_canvas.borrow().as_ref() {
            if let Some(thread_sel) = self.imp().thread_selection.borrow().as_ref() {
                let w = canvas.width().max(120) as f64;
                let layout = self.current_mail_table_layout(thread_sel, w);
                if let Some(adj) = self.imp().list_vadjustment.borrow().as_ref() {
                    let page_h = adj.page_size().max(100.0);
                    adj.set_step_increment(layout.row_height);
                    adj.set_upper(layout.height.max(page_h));
                    let max_val = (layout.height - page_h).max(0.0);
                    if adj.value() > max_val {
                        adj.set_value(max_val);
                    }
                }
                self.imp().mail_table_layout.replace(Some(Rc::new(layout)));
            }
            canvas.queue_draw();
        }
    }

    pub(crate) fn scroll_mail_table_to_selected(&self) {
        if let (Some(thread_sel), Some(adj)) = (
            self.imp().thread_selection.borrow().as_ref(),
            self.imp().list_vadjustment.borrow().as_ref(),
        ) {
            let selected = self.imp().last_selected_mail_index.get()
                .filter(|&idx| thread_sel.is_selected(idx))
                .or_else(|| {
                    let sel = thread_sel.selection();
                    (!sel.is_empty()).then(|| sel.minimum())
                });
            if let Some(selected) = selected {
                let row_h = self
                    .imp()
                    .mail_table_layout
                    .borrow()
                    .as_ref()
                    .map(|l| l.row_height)
                    .unwrap_or_else(|| self.mail_table_row_height());
                let row_y = (selected as f64) * row_h;
                let page_size = adj.page_size();
                let cur_val = adj.value();
                if row_y < cur_val {
                    adj.set_value(row_y);
                } else if row_y + row_h > cur_val + page_size {
                    adj.set_value((row_y + row_h - page_size).max(0.0));
                }
            }
        }
    }

    fn setup_column_header_drag_and_sort(
        &self,
        column_id: &'static str,
        column_widget: &gtk::Box,
        sort_field: Option<MailSortField>,
        sort_gesture: &gtk::GestureClick,
        header: &gtk::Box,
    ) {
        let is_dragging = Rc::new(Cell::new(false));
        let start_header_x = Rc::new(Cell::new(0.0f64));
        let drop_target = Rc::new(RefCell::new(None::<(String, bool)>));

        let page_weak_sort = self.downgrade();
        let is_dragging_for_sort = Rc::clone(&is_dragging);
        sort_gesture.connect_released(move |_, _, _, _| {
            if is_dragging_for_sort.get() {
                return;
            }
            if let Some(field) = sort_field {
                if let Some(page) = page_weak_sort.upgrade() {
                    page.set_mail_sort_from_header(field);
                }
            }
        });

        let drag_gesture = gtk::GestureDrag::new();
        drag_gesture.set_button(1);

        let col_widget_begin = column_widget.clone();
        let header_begin = header.clone();
        let is_dragging_begin = Rc::clone(&is_dragging);
        let start_x_begin = Rc::clone(&start_header_x);
        let drop_target_begin = Rc::clone(&drop_target);

        drag_gesture.connect_drag_begin(move |_, start_x, start_y| {
            is_dragging_begin.set(false);
            *drop_target_begin.borrow_mut() = None;
            let h_x = col_widget_begin
                .compute_point(&header_begin, &gtk::graphene::Point::new(start_x as f32, start_y as f32))
                .map(|p| p.x() as f64)
                .unwrap_or(start_x);
            start_x_begin.set(h_x);
        });

        let col_widget_update = column_widget.clone();
        let header_update = header.clone();
        let is_dragging_update = Rc::clone(&is_dragging);
        let start_x_update = Rc::clone(&start_header_x);
        let drop_target_update = Rc::clone(&drop_target);

        drag_gesture.connect_drag_update(move |gesture, offset_x, _offset_y| {
            if offset_x.abs() > 6.0 || is_dragging_update.get() {
                is_dragging_update.set(true);
                gesture.set_state(gtk::EventSequenceState::Claimed);
                col_widget_update.add_css_class("column-dragging");
                col_widget_update.set_cursor(gdk::Cursor::from_name("grabbing", None).as_ref());

                let cur_header_x = start_x_update.get() + offset_x;

                let mut columns: Vec<(String, gtk::Widget, f64, f64)> = Vec::new();
                let mut child = header_update.first_child();
                while let Some(w) = child {
                    child = w.next_sibling();
                    let name = w.widget_name().to_string();
                    if name.starts_with("mail-column-") && !name.starts_with("mail-column-sep-") && w.is_visible() {
                        let id = name.trim_start_matches("mail-column-").to_string();
                        if let Some(pt) = w.compute_point(&header_update, &gtk::graphene::Point::new(0.0, 0.0)) {
                            let width = w.width().max(1) as f64;
                            columns.push((id, w.clone(), pt.x() as f64, width));
                        }
                    }
                }

                for (_, w, _, _) in &columns {
                    w.remove_css_class("drop-target-left");
                    w.remove_css_class("drop-target-right");
                }

                let mut target = None;
                if !columns.is_empty() {
                    if cur_header_x < columns[0].2 {
                        let (first_id, first_w, _, _) = &columns[0];
                        if first_id != column_id {
                            first_w.add_css_class("drop-target-left");
                        }
                        target = Some((first_id.clone(), false));
                    } else if cur_header_x > columns.last().unwrap().2 + columns.last().unwrap().3 {
                        let (last_id, last_w, _, _) = columns.last().unwrap();
                        if last_id != column_id {
                            last_w.add_css_class("drop-target-right");
                        }
                        target = Some((last_id.clone(), true));
                    } else {
                        for (id, w, x, width) in &columns {
                            if cur_header_x >= *x && cur_header_x <= *x + *width {
                                let drop_after = cur_header_x >= (*x + *width / 2.0);
                                if id != column_id {
                                    if drop_after {
                                        w.add_css_class("drop-target-right");
                                    } else {
                                        w.add_css_class("drop-target-left");
                                    }
                                }
                                target = Some((id.clone(), drop_after));
                                break;
                            }
                        }
                    }
                }
                *drop_target_update.borrow_mut() = target;
            }
        });

        let col_widget_end = column_widget.clone();
        let header_end = header.clone();
        let is_dragging_end = Rc::clone(&is_dragging);
        let drop_target_end = Rc::clone(&drop_target);
        let page_weak_end = self.downgrade();

        drag_gesture.connect_drag_end(move |_, _, _| {
            col_widget_end.remove_css_class("column-dragging");
            col_widget_end.set_cursor(None);
            let mut child = header_end.first_child();
            while let Some(w) = child {
                child = w.next_sibling();
                w.remove_css_class("drop-target-left");
                w.remove_css_class("drop-target-right");
            }

            if is_dragging_end.get() {
                if let Some((target_id, drop_after)) = drop_target_end.borrow_mut().take() {
                    if target_id != column_id {
                        if let Some(settings) = AppSettings::try_new() {
                            let mut order = settings.mail_list_column_order();
                            if let Some(src_pos) = order.iter().position(|id| id == column_id) {
                                let item = order.remove(src_pos);
                                if let Some(tgt_pos) = order.iter().position(|id| id == &target_id) {
                                    let insert_pos = if drop_after { tgt_pos + 1 } else { tgt_pos };
                                    order.insert(insert_pos.min(order.len()), item);
                                    settings.set_mail_list_view_profile("custom");
                                    settings.set_mail_list_column_order(&order);
                                    if let Some(page) = page_weak_end.upgrade() {
                                        page.rebuild_mail_column_layout();
                                    }
                                }
                            }
                        }
                    }
                }
                let is_dragging_reset = Rc::clone(&is_dragging_end);
                glib::idle_add_local_once(move || {
                    is_dragging_reset.set(false);
                });
            }
        });

        column_widget.add_controller(drag_gesture);
    }

