    #[test]
    fn message_context_menu_exposes_daily_state_and_label_actions() {
        let actions = MESSAGE_CONTEXT_ACTIONS
            .iter()
            .map(|(_, action)| *action)
            .collect::<HashSet<_>>();

        for required in [
            "win.reply",
            "win.reply-list",
            "win.forward-inline",
            "win.forward-quoted",
            "win.export",
            "win.mail-print",
            "win.mail-print-preview",
            "win.view-message-source",
            "win.copy-message-link",
            "win.goto-containing-folder",
            "win.add-sender-contact",
            "win.edit-as-new",
            "win.edit-labels",
            "win.move-message",
            "win.copy-message",
            "win.mark-junk",
            "win.mark-not-junk",
            "win.archive",
            "win.delete",
            "win.undelete",
        ] {
            assert!(actions.contains(required), "missing {required}");
        }

        let menu = MailPage::message_context_menu();
        let mut model_actions = HashSet::new();
        for section_idx in 0..menu.n_items() {
            if let Some(section) =
                menu.item_link(section_idx, &gio::MENU_LINK_SECTION)
            {
                for item_idx in 0..section.n_items() {
                    if let Some(action) = section.item_attribute_value(
                        item_idx,
                        &gio::MENU_ATTRIBUTE_ACTION,
                        Some(glib::VariantTy::STRING),
                    ) {
                        if let Some(action_str) = action.str() {
                            model_actions.insert(action_str.to_string());
                        }
                    }
                }
            }
        }
        assert!(
            model_actions.contains("win.goto-containing-folder"),
            "message_context_menu missing win.goto-containing-folder"
        );
    }

    #[test]
    fn reader_reply_forward_variants_parse_list_post_safely() {
        assert_eq!(
            list_post_recipient_from_headers(Some(
                b"From: sender@example.org\r\nList-Post: <mailto:list@example.org>\r\n\r\n",
            )),
            Some("list@example.org".to_string())
        );
        assert_eq!(
            list_post_recipient_from_headers(Some(
                b"list-post: <MAILTO:team%2Bdev@example.org?subject=ignored>\n\n",
            )),
            Some("team+dev@example.org".to_string())
        );
        for headers in [
            b"List-Post: NO\r\n\r\n".as_slice(),
            b"List-Post: <https://lists.example.org/post>\r\n\r\n".as_slice(),
            b"List-Post: <mailto:not-an-address>\r\n\r\n".as_slice(),
            b"List-Post: <mailto:list%0D%0ABcc%3Aevil@example.org>\r\n\r\n".as_slice(),
        ] {
            assert_eq!(list_post_recipient_from_headers(Some(headers)), None);
        }
        assert_eq!(list_post_recipient_from_headers(None), None);
    }

