    #[test]
    fn test_format_mail_table_subject_markup() {
        // Multi-line subject is flattened to single line, and snippet appended with hyphen
        let markup = format_mail_table_subject_markup(
            "Multi-line\r\nSubject   with\nbreaks",
            "This is the body\r\npreview text",
            &[],
            true,
            true,
            false,
            false,
            false,
        );
        assert!(markup.contains("Multi-line Subject with breaks"));
        assert!(markup.contains("weight=\"bold\""));
        assert!(markup.contains("- This is the body preview text"));
        assert!(!markup.contains('\n'));
        assert!(!markup.contains('\r'));

        // Snippet disabled: only subject displayed (medium weight for read messages)
        let markup_no_snippet = format_mail_table_subject_markup(
            "Project Update",
            "Ignored snippet text",
            &[],
            false,
            false,
            false,
            false,
            false,
        );
        assert!(markup_no_snippet.contains("Project Update"));
        assert!(markup_no_snippet.contains("weight=\"medium\""));
        assert!(!markup_no_snippet.contains("Ignored snippet text"));

        // Read message with snippet: subject is medium (weight 500), snippet is normal (weight 400)
        let markup_read_with_snip = format_mail_table_subject_markup(
            "Meeting Notes",
            "Here are the notes from today",
            &[],
            false,
            true,
            false,
            false,
            false,
        );
        assert!(markup_read_with_snip.contains("weight=\"medium\">Meeting Notes</span>"));
        assert!(markup_read_with_snip.contains("weight=\"normal\">- Here are the notes from today</span>"));

        // Empty subject fallback
        let markup_empty = format_mail_table_subject_markup(
            "   \n  ",
            "Some preview",
            &[],
            false,
            true,
            false,
            false,
            false,
        );
        assert!(markup_empty.contains(&gettext("(No Subject)")));
        assert!(markup_empty.contains("- Some preview"));

        // XML characters escaped safely
        let markup_escaped = format_mail_table_subject_markup(
            "Alpha & Beta <Gamma>",
            "1 < 2 && 3 > 2",
            &[],
            false,
            true,
            false,
            false,
            false,
        );
        assert!(markup_escaped.contains("Alpha &amp; Beta &lt;Gamma&gt;"));
        assert!(markup_escaped.contains("1 &lt; 2 &amp;&amp; 3 &gt; 2"));

        // "(Keine Nachricht)" must never be appended as snippet
        let markup_keine_nachricht = format_mail_table_subject_markup(
            "Important Update",
            "(Keine Nachricht)",
            &[],
            false,
            true,
            false,
            false,
            false,
        );
        assert!(markup_keine_nachricht.contains("Important Update"));
        assert!(!markup_keine_nachricht.contains("Keine Nachricht"));
        assert!(!markup_keine_nachricht.contains(" - "));

        // Evolution signature red text for important messages
        let markup_imp_light = format_mail_table_subject_markup(
            "Urgent Server Alert",
            "Please check immediately",
            &[],
            false,
            true,
            false,
            false,
            true,
        );
        assert!(markup_imp_light.contains("foreground=\"#A7453E\""));

        let markup_imp_dark = format_mail_table_subject_markup(
            "Urgent Server Alert",
            "Please check immediately",
            &[],
            true,
            true,
            false,
            true,
            true,
        );
        assert!(markup_imp_dark.contains("foreground=\"#FF6B6B\""));

        // Labels rendered in table mode when show_labels is true
        let labels = vec!["$Labelwork".to_string(), "Important".to_string()];
        let markup_with_labels = format_mail_table_subject_markup(
            "Roadmap 2027",
            "Preview of next year",
            &labels,
            true,
            true,
            true,
            false,
            false,
        );
        assert!(markup_with_labels.contains("[Work]"));
        assert!(markup_with_labels.contains("[Important]"));
        assert!(markup_with_labels.contains("Roadmap 2027"));

        // Labels hidden when show_labels is false
        let markup_labels_hidden = format_mail_table_subject_markup(
            "Roadmap 2027",
            "Preview of next year",
            &labels,
            true,
            true,
            false,
            false,
            false,
        );
        assert!(!markup_labels_hidden.contains("[Work]"));
        assert!(!markup_labels_hidden.contains("[Important]"));
        assert!(markup_labels_hidden.contains("Roadmap 2027"));
    }

    #[test]
    fn test_format_recipient_display() {
        // 1. Single recipient with name and email:
        // When show_address is false: display name
        assert_eq!(
            format_recipient_display("Max Jensen <MJensen@corp.local>", false),
            "Max Jensen"
        );
        // When show_address is true: pure email
        assert_eq!(
            format_recipient_display("Max Jensen <MJensen@corp.local>", true),
            "mjensen@corp.local"
        );

        // 2. Email only (no display name in header):
        // When show_address is false: resolved Klarname (capitalized/acronym)
        assert_eq!(
            format_recipient_display("support@example.com", false),
            "Support"
        );
        assert_eq!(
            format_recipient_display("intern_edv@acme-corp.example", false),
            "Intern EDV"
        );
        assert_eq!(
            format_recipient_display("john.doe@example.com", false),
            "John Doe"
        );
        // When show_address is true: pure email
        assert_eq!(
            format_recipient_display("support@example.com", true),
            "support@example.com"
        );
        assert_eq!(
            format_recipient_display("intern_edv@acme-corp.example", true),
            "intern_edv@acme-corp.example"
        );

        // 3. Multiple recipients:
        let multi = "Max Jensen <MJensen@corp.local>, Anna Schmidt <anna@example.com>";
        assert_eq!(
            format_recipient_display(multi, false),
            "Max Jensen, Anna Schmidt"
        );
        assert_eq!(
            format_recipient_display(multi, true),
            "mjensen@corp.local, anna@example.com"
        );

        let multi_mixed = "intern_edv@acme-corp.example, Max Mustermann <max@example.com>";
        assert_eq!(
            format_recipient_display(multi_mixed, false),
            "Intern EDV, Max Mustermann"
        );
        assert_eq!(
            format_recipient_display(multi_mixed, true),
            "intern_edv@acme-corp.example, max@example.com"
        );

        // 4. Empty string
        assert_eq!(format_recipient_display("", false), "");
        assert_eq!(format_recipient_display("   ", true), "");
    }

    #[test]
    fn test_smart_responsive_column_scaling() {
        let order = vec![
            "status".to_string(),
            "sender".to_string(),
            "recipient".to_string(),
            "subject".to_string(),
            "date".to_string(),
        ];

        // Wide layout (1000px): ample space -> sender & recipient retain full 180px
        let geom_wide = compute_table_columns_geometry(
            &order,
            1000.0,
            true,  // status (28)
            false,
            false,
            false,
            false,
            true,  // sender
            180.0,
            true,  // recipient
            180.0,
            true,  // date (120)
            120.0,
            false, // size
            0.0,
            6.0,   // sep_width
        );
        assert_eq!(geom_wide.sender.width, 180.0);
        assert_eq!(geom_wide.recipient.width, 180.0);
        assert!(geom_wide.subject.width > 250.0);

        // Narrow layout (450px): constrained -> sender & recipient scale down proportionally,
        // ensuring subject is not crushed to 60px minimum!
        let geom_narrow = compute_table_columns_geometry(
            &order,
            450.0,
            true,  // status (28)
            false,
            false,
            false,
            false,
            true,  // sender
            180.0,
            true,  // recipient
            180.0,
            true,  // date (120)
            120.0,
            false, // size
            0.0,
            6.0,   // sep_width
        );
        assert!(geom_narrow.sender.width < 180.0);
        assert!(geom_narrow.sender.width >= 60.0);
        assert!(geom_narrow.recipient.width < 180.0);
        assert!(geom_narrow.recipient.width >= 60.0);
        assert!(geom_narrow.subject.width >= 60.0);
        // Date stays fixed at 120 so timestamps are not truncated
        assert_eq!(geom_narrow.date.width, 120.0);
    }

