    #[test]
    fn test_unified_folders_selection_and_matching() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };

        // 1. FolderSelection construction and titles
        let sel_inbox = FolderSelection::from_folder_id("unified_inbox");
        assert_eq!(sel_inbox.folder_id, "unified_inbox");
        assert_eq!(sel_inbox.source_uid, None);
        let (title, icon) = sel_inbox.title_and_icon();
        assert_eq!(title, gettext("All Inboxes"));
        assert_eq!(icon, "mail-inbox-symbolic");

        let sel_unread = FolderSelection::from_folder_id("unified_unread");
        let (title, icon) = sel_unread.title_and_icon();
        assert_eq!(title, gettext("All Unread"));
        assert_eq!(icon, "mail-unread-symbolic");

        let sel_flagged = FolderSelection::from_folder_id("unified_flagged");
        let (title, icon) = sel_flagged.title_and_icon();
        assert_eq!(title, gettext("All Flagged"));
        assert_eq!(icon, "starred-symbolic");

        let sel_sent = FolderSelection::from_folder_id("unified_sent");
        let (title, icon) = sel_sent.title_and_icon();
        assert_eq!(title, gettext("All Sent"));
        assert_eq!(icon, "mail-send-symbolic");

        // 2. Message matching
        let msg_inbox = create_test_mail_object("msg-1", "inbox", true, false, None);
        let msg_sent = create_test_mail_object("msg-2", "sent", false, true, None);
        let msg_trash = create_test_mail_object("msg-3", "trash", true, false, None);

        assert!(sel_inbox.matches(&msg_inbox));
        assert!(!sel_inbox.matches(&msg_sent));

        assert!(sel_unread.matches(&msg_inbox));
        assert!(!sel_unread.matches(&msg_sent));
        assert!(!sel_unread.matches(&msg_trash)); // Trash excluded from unified unread

        assert!(!sel_flagged.matches(&msg_inbox));
        assert!(sel_flagged.matches(&msg_sent));

        assert!(!sel_sent.matches(&msg_inbox));
        assert!(sel_sent.matches(&msg_sent));

        // 3. Account colors
        let loc1 = crate::services::mail_store_service::MailBackendLocation {
            source_uid: "account-alpha".to_string(),
            folder_name: "INBOX".to_string(),
            message_uid: "101".to_string(),
            message_id: None,
        };
        let msg_loc1 = create_test_mail_object("msg-4", "inbox", false, false, Some(loc1));
        let color1 = account_color_for_message(&msg_loc1);
        assert!(color1.is_some());

        let loc2 = crate::services::mail_store_service::MailBackendLocation {
            source_uid: "account-beta".to_string(),
            folder_name: "INBOX".to_string(),
            message_uid: "102".to_string(),
            message_id: None,
        };
        let msg_loc2 = create_test_mail_object("msg-5", "inbox", false, false, Some(loc2));
        let color2 = account_color_for_message(&msg_loc2);
        assert!(color2.is_some());

        // Stable color per source_uid
        let color1_repeat = account_color_for_message(&msg_loc1);
        assert_eq!(color1, color1_repeat);
    }

    #[test]
    fn test_sidebar_subfolder_and_unified_indentation_contract() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };

        // 1. Unified folder row margin_start must be 20px (matching depth 1 with expander column and Contacts sidebar)
        let unified_row = MailPage::create_unified_folder_row(
            "unified_inbox",
            "mail-inbox-symbolic",
            "All Inboxes",
            "",
        );
        let hbox = unified_row
            .child()
            .and_downcast::<gtk::Box>()
            .expect("Unified folder row must have a child Box");
        assert_eq!(
            hbox.margin_start(),
            20,
            "Unified folder rows must have margin_start = 20 to align with level-1 subfolders (matching Contacts sidebar)"
        );

        // 2. TreeExpander configuration contract:
        // Account root: indent_for_depth = false, indent_for_icon = false
        let root_expander = gtk::TreeExpander::new();
        root_expander.set_indent_for_depth(false);
        root_expander.set_indent_for_icon(false);
        assert!(!root_expander.is_indent_for_depth());
        assert!(!root_expander.is_indent_for_icon());

        // Level-1 subfolder (directly under account): indent_for_depth = false, indent_for_icon = true
        let level1_expander = gtk::TreeExpander::new();
        level1_expander.set_indent_for_depth(false);
        level1_expander.set_indent_for_icon(true);
        assert!(!level1_expander.is_indent_for_depth());
        assert!(level1_expander.is_indent_for_icon());

        // Nested subfolder (depth >= 2): indent_for_depth = false, indent_for_icon = true, margin_start = 16 * (depth - 1)
        let child_expander = gtk::TreeExpander::new();
        child_expander.set_indent_for_depth(false);
        child_expander.set_indent_for_icon(true);
        child_expander.set_margin_start(16);
        assert!(!child_expander.is_indent_for_depth());
        assert!(child_expander.is_indent_for_icon());
        assert_eq!(child_expander.margin_start(), 16);

        // 3. folder-sub-expander class contract for depth >= 2:
        child_expander.add_css_class("folder-sub-expander");
        assert!(child_expander.has_css_class("folder-sub-expander"));
        level1_expander.remove_css_class("folder-sub-expander");
        assert!(!level1_expander.has_css_class("folder-sub-expander"));
        root_expander.remove_css_class("folder-sub-expander");
        assert!(!root_expander.has_css_class("folder-sub-expander"));

        // 4. Subfolder icon & display name isolation contracts:
        // Nested subfolders do NOT inherit parent folder icons unless their leaf name explicitly matches
        assert_eq!(MailPage::folder_icon_name_for("ews:1/Posteingang/Kunden", "Posteingang/Kunden"), "folder-symbolic");
        assert_eq!(MailPage::folder_icon_name_for("ews:1/Synchronisierungsprobleme/Konflikte", "Synchronisierungsprobleme/Konflikte"), "folder-symbolic");
        assert_eq!(MailPage::folder_icon_name_for("ews:1/Gesendete Elemente/Projekt2024", "Gesendete Elemente/Projekt2024"), "folder-symbolic");
        assert_eq!(MailPage::folder_icon_name_for("inbox", "Posteingang"), "mail-inbox-symbolic");
        assert_eq!(MailPage::folder_icon_name_for("sent", "Gesendete Elemente"), "mail-send-symbolic");
    }

    #[test]
    fn test_view_options_split_button_and_toggle_contract() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };

        let page = MailPage::new();
        let split_btn = page.imp().view_options_split_btn.borrow().clone();
        assert!(split_btn.is_some(), "view_options_split_btn must be present on MailPage");
        let split_btn = split_btn.unwrap();

        // 1. Dropdown tooltip must be "View options"
        assert_eq!(
            split_btn.dropdown_tooltip().as_str(),
            gettext("View options")
        );

        // 2. Synchronized state between Table view and List view:
        if let Some(settings) = AppSettings::try_new() {
            // When in messages (table) view profile:
            settings.apply_mail_list_view_profile("messages");
            page.sync_view_split_button();
            assert_eq!(
                split_btn.tooltip_text().unwrap_or_default().as_str(),
                gettext("List view")
            );
            assert_eq!(
                split_btn.icon_name().unwrap_or_default().as_str(),
                "view-list-symbolic"
            );

            // When in cards (list) view profile:
            settings.apply_mail_list_view_profile("cards");
            page.sync_view_split_button();
            assert_eq!(
                split_btn.tooltip_text().unwrap_or_default().as_str(),
                gettext("Table view")
            );
            let icon = split_btn.icon_name().unwrap_or_default();
            assert!(
                icon == "meridian-view-table-symbolic"
                    || icon == "view-grid-symbolic"
                    || icon == "view-column-symbolic",
                "unexpected icon: {icon}"
            );
        }
    }

    #[test]
    fn test_view_options_avatar_logos_revealer() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };

        let listbox = gtk::ListBox::new();
        let row_avatars = adw::ActionRow::builder()
            .title("Show avatars")
            .build();
        listbox.append(&row_avatars);

        let row_logos = adw::ActionRow::builder()
            .title("Load sender logos")
            .subtitle("Download favicons from the Internet")
            .build();

        let revealer = gtk::Revealer::builder()
            .transition_type(gtk::RevealerTransitionType::SlideDown)
            .transition_duration(200)
            .reveal_child(false)
            .child(&row_logos)
            .build();

        let row_logos_container = gtk::ListBoxRow::builder()
            .activatable(false)
            .selectable(false)
            .css_classes(["view-options-revealer-row"])
            .child(&revealer)
            .visible(false)
            .build();

        listbox.append(&row_logos_container);
        assert!(!revealer.reveals_child());
        assert!(!row_logos_container.is_visible());

        row_logos_container.set_visible(true);
        revealer.set_reveal_child(true);
        assert!(revealer.reveals_child());
        assert!(row_logos_container.is_visible());
    }

