    #[gtk::test]
    fn test_same_folder_refresh_preserves_messages_and_selection() {
        let page = MailPage::new();
        let store = page.imp().message_store.borrow().clone().expect("message_store");
        let viewer = page.imp().mail_viewer.borrow().clone().expect("mail_viewer");

        let mut msg_data = ParsedMail {
            id: "eds:account:edv@acme-corp.example:Posteingang:12345".to_string(),
            folder_id: "inbox".to_string(),
            folder_name: "Posteingang".to_string(),
            backend_location: Some(MailBackendLocation {
                source_uid: "account:edv@acme-corp.example".to_string(),
                folder_name: "Posteingang".to_string(),
                message_uid: "12345".to_string(),
                message_id: None,
            }),
            sender_name: "Sender".to_string(),
            sender_email: "sender@example.com".to_string(),
            recipient_to: "edv@acme-corp.example".to_string(),
            recipient_cc: String::new(),
            recipient_bcc: String::new(),
            reply_to: String::new(),
            subject: "Subject".to_string(),
            message_id: None,
            in_reply_to: Vec::new(),
            references: Vec::new(),
            thread_id: "t1".to_string(),
            thread_size: 1,
            thread_position: 0,
            date_str: "2026-10-09".to_string(),
            message_size: 100,
            preview_snippet: "Snippet".to_string(),
            html_body: "<p>Body</p>".to_string(),
            raw_headers: None,
            raw_mime: None,
            is_unread: true,
            is_flagged: false,
            is_important: false,
            is_replied: false,
            is_forwarded: false,
            follow_up: Default::default(),
            follow_up_state: Default::default(),
            labels: Vec::new(),
            attachments: Vec::new(),
            is_preview_only: false,
        };
        let msg = msg_data.clone().into_object();
        store.append(&msg);
        viewer.imp().current_message_id.replace(Some(msg.id().to_string()));

        let request = MailLoadRequest {
            source_uid: Some("account:edv@acme-corp.example".to_string()),
            folder_name: Some("Posteingang".to_string()),
            offset: 0,
            max_messages_per_folder: 50,
            graph_cursors: HashMap::new(),
        };
        page.imp().active_request.replace(Some(request.clone()));

        // Simulate incoming message from refresh with updated unread flag (marked read)
        msg_data.is_unread = false;

        let mut pending = PendingMailApply::from_local(
            request,
            "Sync".to_string(),
            vec![msg_data],
            HashSet::new(),
            HashMap::new(),
            HashSet::new(),
            true,
            MailSelectionAnchor {
                id: Some(msg.id().to_string()),
                index: Some(0),
            },
            1,
            true,
        );

        // Prepopulate existing maps as begin_pending_mail_apply does
        for index in 0..store.n_items() {
            if let Some(m) = store.item(index).and_downcast::<MailMessageObject>() {
                pending.existing_messages.insert(m.id(), m.clone());
                pending.existing_ids.insert(m.id());
                if let Some(loc) = m.backend_location() {
                    pending.existing_messages_by_uid.insert(loc.message_uid, m.clone());
                }
            }
        }

        let done = page.process_pending_mail_apply(&mut pending);
        assert!(done);
        page.finish_pending_mail_apply(&pending);

        // Message should be updated in-place:
        assert_eq!(store.n_items(), 1);
        assert!(!msg.is_unread(), "Message unread flag should be updated in place");
        assert_eq!(viewer.imp().current_message_id.borrow().as_deref(), Some("eds:account:edv@acme-corp.example:Posteingang:12345"));
    }

    #[test]
    fn test_attachment_section_evolution_collapsible_drawer() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };
        let page = MailPage::new();
        let (
            _detail_view,
            mail_viewer,
            itip_banner,
            _crypto_label,
            _lbl_crypto,
            _crypto_chip,
            attachment_bar,
            _thread_context,
            _all_headers_revealer,
            _all_headers_grid,
            _message_find_revealer,
            _message_find_entry,
        ) = page.build_detail_view();

        // Initially attachment_bar is hidden
        assert!(!attachment_bar.is_visible());
        let widgets = MailPage::find_attachment_section_widgets(&attachment_bar)
            .expect("attachment section widgets should be present in build_detail_view hierarchy");

        let msg = scope_test_message("msg-att-evo", "acc", "inbox", false);
        *msg.imp().html_body.borrow_mut() = "<p>Long email body line</p>\n".repeat(25);
        *msg.imp().attachments.borrow_mut() = vec![
            crate::models::mail_message::AttachmentInfo {
                filename: "invoice.pdf".to_string(),
                size_formatted: "15 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([1, 2, 3, 4, 5]),
            },
            crate::models::mail_message::AttachmentInfo {
                filename: "spec.docx".to_string(),
                size_formatted: "25 KB".to_string(),
                mime_type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([6, 7, 8]),
            },
        ];

        MailPage::render_message_content(&msg, &mail_viewer, &attachment_bar, None, &[]);

        // Section and bar should now be visible
        assert!(attachment_bar.is_visible());

        // Summary label text should reflect 2 attachments
        let label_text = widgets.summary_label.text();
        assert!(label_text.contains('2'), "Summary label should contain attachment count 2: {label_text}");

        fn has_descendant_with_class(root: &impl gtk::prelude::IsA<gtk::Widget>, class: &str) -> bool {
            if root.has_css_class(class) {
                return true;
            }
            let mut child = root.first_child();
            while let Some(c) = child {
                if has_descendant_with_class(&c, class) {
                    return true;
                }
                child = c.next_sibling();
            }
            false
        }

        // Save all button should be in save_all_box and have attachment-save-all-btn class
        let save_all_btn = widgets.save_all_box.first_child().and_downcast::<gtk::Button>()
            .expect("save all button should be present for multiple attachments");
        assert!(save_all_btn.has_css_class("attachment-save-all-btn"));
        assert!(has_descendant_with_class(&save_all_btn, "attachment-save-all-label"), "save all button must render a visible label");

        // Default state for long email: collapsed so attachments do not consume vertical space, with compact chips visible in the bar
        assert!(!widgets.revealer.reveals_child());
        assert!(widgets.chip_box.is_visible());
        let chip = widgets.chip_box.first_child().expect("chip exists in chip_box");
        assert!(has_descendant_with_class(&chip, "attachment-chip-download-btn"), "compact chip must have a 1-click download button");
        assert!(!widgets.summary_box.is_visible());
        assert!(!widgets.view_toggle_box.is_visible());

        // Check listbox has children for list view with download button
        let list_row = widgets.listbox.first_child().expect("listbox has row");
        assert!(list_row.has_css_class("attachment-list-row"));
        assert!(has_descendant_with_class(&list_row, "attachment-list-download-btn"), "list row must have a 1-click download button");

        // Check drawer card exists in attachment_bar
        assert!(
            has_descendant_with_class(&attachment_bar, "attachment-drawer-card"),
            "attachment_bar must contain cards with .attachment-drawer-card"
        );
        assert!(
            has_descendant_with_class(&attachment_bar, "attachment-card-download-btn"),
            "drawer card must have a 1-click download button"
        );

        // Toggling to expanded
        widgets.btn_collapse.emit_clicked();
        assert!(widgets.revealer.reveals_child());
        assert!(!widgets.chip_box.is_visible());
        assert!(widgets.summary_box.is_visible());
        assert!(widgets.view_toggle_box.is_visible());
        assert_eq!(widgets.stack.visible_child_name().as_deref(), Some("icons"));

        // Switch to list view
        widgets.btn_list.emit_clicked();
        assert_eq!(widgets.stack.visible_child_name().as_deref(), Some("list"));

        // Switch back to icons view
        widgets.btn_icons.emit_clicked();
        assert_eq!(widgets.stack.visible_child_name().as_deref(), Some("icons"));

        // Collapse again
        widgets.btn_collapse.emit_clicked();
        assert!(!widgets.revealer.reveals_child());
        assert!(widgets.chip_box.is_visible());
        assert!(!widgets.summary_box.is_visible());
        assert!(!widgets.view_toggle_box.is_visible());

        // Compact chip should display both filename and size label
        assert!(has_descendant_with_class(&chip, "attachment-chip-size"), "compact chip must show size label");

        // List row must NOT contain a redundant open button (click on row opens attachment)
        assert!(!has_descendant_with_class(&list_row, "document-open-symbolic"), "list row must not have redundant open button");

        // When switching to a message with 5 attachments (exceeding max_chips = 3) on a long email:
        let msg_many = scope_test_message("msg-many-att-evo", "acc", "inbox", false);
        *msg_many.imp().html_body.borrow_mut() = "<p>Long email body line</p>\n".repeat(25);
        *msg_many.imp().attachments.borrow_mut() = vec![
            crate::models::mail_message::AttachmentInfo {
                filename: "a.pdf".to_string(),
                size_formatted: "100 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([1, 2, 3]),
            },
            crate::models::mail_message::AttachmentInfo {
                filename: "b.pdf".to_string(),
                size_formatted: "200 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([4, 5, 6]),
            },
            crate::models::mail_message::AttachmentInfo {
                filename: "c.pdf".to_string(),
                size_formatted: "300 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([7, 8, 9]),
            },
            crate::models::mail_message::AttachmentInfo {
                filename: "d.pdf".to_string(),
                size_formatted: "400 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([10, 11]),
            },
            crate::models::mail_message::AttachmentInfo {
                filename: "e.pdf".to_string(),
                size_formatted: "500 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([12, 13]),
            },
        ];
        MailPage::render_message_content(&msg_many, &mail_viewer, &attachment_bar, None, &[]);

        // In collapsed state with > max_chips, summary_box is directly visible showing total count & size
        assert!(widgets.summary_box.is_visible(), "summary box should be directly visible when attachments do not fit as pills");
        assert!(!widgets.chip_box.is_visible(), "chip box should be hidden when attachments do not fit as pills");
        assert!(widgets.summary_label.text().contains('5'), "summary label should show count 5");
        assert!(widgets.save_all_box.first_child().is_some(), "save all button should be visible");

        // When switching to a short email, drawer remains collapsed by default so it stays compact and unobtrusive
        let msg_short = scope_test_message("msg-att-evo-short", "acc", "inbox", false);
        *msg_short.imp().html_body.borrow_mut() = "<p>Short email body</p>".to_string();
        *msg_short.imp().attachments.borrow_mut() = vec![
            crate::models::mail_message::AttachmentInfo {
                filename: "quick.pdf".to_string(),
                size_formatted: "10 KB".to_string(),
                mime_type: "application/pdf".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from([1, 2]),
            },
        ];
        MailPage::render_message_content(&msg_short, &mail_viewer, &attachment_bar, None, &[]);
        assert!(!widgets.revealer.reveals_child(), "Short email drawer should stay collapsed by default");
        assert!(!widgets.summary_box.is_visible());
        assert!(widgets.chip_box.is_visible());
        assert!(!widgets.view_toggle_box.is_visible());

        // When switching to a message without attachments, section and bar hide and save_all_box clears
        let msg_no_att = scope_test_message("msg-no-att-evo", "acc", "inbox", false);
        MailPage::render_message_content(&msg_no_att, &mail_viewer, &attachment_bar, None, &[]);

        assert!(!attachment_bar.is_visible());
        assert!(widgets.save_all_box.first_child().is_none());
        assert!(widgets.listbox.first_child().is_none());

        // When an email is a calendar invitation rendered in ItipBanner, redundant invite.ics is suppressed from attachment bar
        let msg_itip = scope_test_message("msg-itip-only", "acc", "inbox", false);
        let sample_ics = b"BEGIN:VCALENDAR\r\nVERSION:2.0\r\nMETHOD:REQUEST\r\nBEGIN:VEVENT\r\nUID:itip-1\r\nSUMMARY:Sync\r\nDTSTART:20261020T100000Z\r\nDTEND:20261020T110000Z\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";
        *msg_itip.imp().attachments.borrow_mut() = vec![
            crate::models::mail_message::AttachmentInfo {
                filename: "invite.ics".to_string(),
                size_formatted: "1 KB".to_string(),
                mime_type: "text/calendar".to_string(),
                content_id: None,
                is_inline: false,
                content: std::sync::Arc::from(&sample_ics[..]),
            },
        ];
        MailPage::render_message_content(&msg_itip, &mail_viewer, &attachment_bar, Some(&itip_banner), &[]);
        assert!(!attachment_bar.is_visible(), "Redundant .ics attachment should be hidden when rendered in ItipBanner");
    }

    #[gtk::test]
    fn test_clicking_thread_group_root_updates_mail_preview() {
        let _ = adw::init();
        let page = MailPage::new();
        page.imp().mail_threading.set(true);
        if let Some(folder_sel) = page.imp().folder_selection.borrow().as_ref() {
            folder_sel.replace(FolderSelection::from_folder_id("inbox"));
        }

        let store = page.imp().message_store.borrow().clone().expect("message_store");
        let viewer = page.imp().mail_viewer.borrow().clone().expect("mail_viewer");

        // Create a 2-message thread where the newest message (thread root with dropdown)
        // is a Sent reply (cross-folder) and the child is in Inbox.
        let root_sent = MailMessageObject::new(
            "eds:acc:Sent:20",
            "sent",
            "Me",
            "me@example.com",
            "alice@example.com",
            "",
            "",
            "",
            "Re: Project Status",
            Some("<msg-20@example.com>".to_string()),
            vec!["<msg-10@example.com>".to_string()],
            vec!["<msg-10@example.com>".to_string()],
            "thread-1",
            2,
            0,
            "Mon, 09 Nov 2026 12:00:00 +0000",
            256,
            "Latest reply snippet",
            "<p>Latest reply body</p>",
            false,
            false,
            false,
            MailFollowUpState::None,
            MailFollowUpMetadata::default(),
            Vec::new(),
            None,
            Vec::new(),
        );
        let child_inbox = MailMessageObject::new(
            "eds:acc:Inbox:10",
            "inbox",
            "Alice",
            "alice@example.com",
            "me@example.com",
            "",
            "",
            "",
            "Project Status",
            Some("<msg-10@example.com>".to_string()),
            Vec::new(),
            Vec::new(),
            "thread-1",
            2,
            1,
            "Mon, 09 Nov 2026 10:00:00 +0000",
            256,
            "Original inbox snippet",
            "<p>Original inbox body</p>",
            false,
            false,
            false,
            MailFollowUpState::None,
            MailFollowUpMetadata::default(),
            Vec::new(),
            None,
            Vec::new(),
        );
        store.append(&root_sent);
        store.append(&child_inbox);

        let root_store = page.imp().thread_root_store.borrow().clone().expect("thread_root_store");
        root_store.append(&root_sent);

        let children_store = gio::ListStore::new::<MailMessageObject>();
        children_store.append(&child_inbox);
        if let Some(children_map) = page.imp().thread_children.borrow().as_ref() {
            children_map.borrow_mut().insert("thread-1".to_string(), children_store);
        }
        if let Some(members_map) = page.imp().thread_members.borrow().as_ref() {
            members_map.borrow_mut().insert(
                "thread-1".to_string(),
                vec![root_sent.clone(), child_inbox.clone()],
            );
        }
        page.imp().expanded_threads.borrow_mut().insert("thread-1".to_string());
        page.invalidate_message_filters();
        page.restore_expanded_threads();

        let thread_sel = page.imp().thread_selection.borrow().clone().expect("thread_selection");
        assert_eq!(thread_sel.n_items(), 2, "Expanded thread should have 2 rows (root + child)");

        // 1. Select child (index 1, in Inbox) -> preview shows child_inbox
        page.select_single_thread_row(&thread_sel, 1);
        assert_eq!(
            viewer.imp().current_message_id.borrow().as_deref(),
            Some("eds:acc:Inbox:10")
        );

        // 2. Click first element of thread group (index 0, root with dropdown) -> preview MUST update to root_sent
        page.select_single_thread_row(&thread_sel, 0);
        assert_eq!(
            viewer.imp().current_message_id.borrow().as_deref(),
            Some("eds:acc:Sent:20"),
            "Clicking the first element (root) of a thread group must update the mail preview"
        );

        // 3. Even if thread_sel already had index 0 selected while viewer showed child_inbox,
        // clicking index 0 again must force preview to update to root_sent
        viewer.imp().current_message_id.replace(Some("eds:acc:Inbox:10".to_string()));
        page.select_single_thread_row(&thread_sel, 0);
        assert_eq!(
            viewer.imp().current_message_id.borrow().as_deref(),
            Some("eds:acc:Sent:20"),
            "Clicking an already-selected thread root when viewer shows a different message must re-sync preview"
        );
    }

    #[gtk::test]
    fn disabled_account_and_hidden_local_fallback_excluded_from_unread_and_search() {
        let _ = adw::init();
        let page = MailPage::new();
        let store = page.imp().message_store.borrow().clone().expect("message_store");
        store.remove_all();

        // Mark "disabled@example.com" as a disabled/paused account
        page.imp()
            .dynamic_folder_expanded
            .borrow_mut()
            .insert("account-paused:disabled@example.com".to_string());

        // Simulate active remote account in mail_folder_summaries
        page.imp().mail_folder_summaries.replace(vec![CamelFolderSummary {
            source_uid: "active-exchange".to_string(),
            source_display_name: "Exchange".to_string(),
            folder_name: "INBOX".to_string(),
            display_name: "Inbox".to_string(),
            folder_id: "inbox".to_string(),
            unread_count: 0,
            total_count: 1,
            is_selectable: true,
        }]);

        // Add a local fallback .eml message in built-in "inbox" addressed to the disabled account
        let local_lieferando = MailMessageObject::new(
            "👍 OR 👎  for Re Castello_",
            "inbox",
            "Lieferando",
            "no-reply@connect.lieferando.de",
            "disabled@example.com",
            "",
            "",
            "",
            "👍 OR 👎 for Re Castello?",
            Some("<lieferando@example.com>".to_string()),
            Vec::new(),
            Vec::new(),
            "thread-lieferando",
            1,
            0,
            "Mon, 09 Nov 2026 11:00:00 +0000",
            512,
            "Rate your order at Lieferando",
            "<p>Rate your order at Lieferando</p>",
            true,
            false,
            false,
            MailFollowUpState::None,
            MailFollowUpMetadata::default(),
            Vec::new(),
            None,
            Vec::new(),
        );
        store.append(&local_lieferando);

        // 1. Message addressed to disabled account must not be considered active
        assert!(
            !page.is_message_account_active(&local_lieferando),
            "Local fallback message addressed to disabled account must not be active"
        );

        // 2. Local folder counts and total_inbox_unread_count must be 0
        assert!(page.current_local_folder_counts().is_empty());
        assert_eq!(page.total_inbox_unread_count(), 0);

        // 3. Even if local_counts had a stray "inbox" unread entry, update_camel_folder_counts
        // must not add built-in local "inbox" unread to All Inboxes when remote folders exist
        if let Some(folder_list) = page.imp().folder_list.borrow().as_ref() {
            let mut stray_local_counts = HashMap::new();
            stray_local_counts.insert("inbox".to_string(), (1u32, 1u32));
            let summaries = page.imp().mail_folder_summaries.borrow().clone();
            page.update_camel_folder_counts(folder_list, &summaries, Some(&stray_local_counts));
        }
        if let Some(unified_list) = page.imp().unified_folder_list.borrow().as_ref() {
            for index in 0..unified_list.observe_children().n_items() {
                if let Some(row) = unified_list.row_at_index(index as i32).and_downcast::<gtk::ListBoxRow>() {
                    let row_id = unsafe { row.data::<String>("folder-id").map(|p| p.as_ref().clone()) }.unwrap_or_default();
                    if row_id == "unified_inbox" || row_id == "unified_unread" {
                        if let Some(badge) = unsafe { row.data::<gtk::Label>("folder-badge").map(|p| p.as_ref()) } {
                            assert!(!badge.is_visible(), "{row_id} badge must remain hidden when active remote accounts have 0 unread");
                        }
                    }
                }
            }
        }

        // 4. Filtering by Unread or searching for "lieferando" must not return the disabled account's mail
        if let Some(filter_state) = page.imp().message_filter_state.borrow().as_ref() {
            filter_state.set(MessageFilter::Unread);
        }
        page.invalidate_message_filters();
        let msg_sel = page.imp().message_selection.borrow().clone().expect("message_selection");
        assert_eq!(msg_sel.n_items(), 0, "Unread filter must not show disabled account mail");

        if let Some(filter_state) = page.imp().message_filter_state.borrow().as_ref() {
            filter_state.set(MessageFilter::All);
        }
        page.handle_search_changed("lieferando");
        page.invalidate_message_filters();
        assert_eq!(msg_sel.n_items(), 0, "Search for 'lieferando' must not show disabled account mail");
    }
